class AnEmptyFirstPageOrAnEmptyWholeBoardListIsAReadingFault(unittest.TestCase):
    """**#181, batch 5.** Two adapters printed a bare zero with exit 0 on the
    one shape that, on their boards, can only be a reading fault:

    - `randstad.py list` broke out of the page loop on an empty page 1 and
      printed «0 emitted, 0 ads over 0 page(s)» — the board serves hundreds
      of ads, page 1 is never empty;
    - `swissdevjobs.py list` read the whole-board endpoint, passed the
      «is it a list» check on `[]`, and printed «0 of 0 postings kept» — an
      empty list from the endpoint that IS the board (193 on 2026-09-11).

    Both now die 6 and say what they saw. Mutated: the `n == 1` die removed →
    the randstad case reddens on exit None and «0 emitted»; the `if not d`
    die removed → the swissdevjobs case reddens on «0 of 0».
    """

    def _load(self, name):
        spec = importlib.util.spec_from_file_location(
            f"_{name}181b5", os.path.join(SCRIPTS, f"{name}.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def test_randstad_page_1_with_no_cards_dies_with_the_bytes(self):
        import contextlib
        mod = self._load("randstad")
        mod.get = lambda url: (200, "<html>" + "x" * 5000 + "</html>")
        a = argparse.Namespace(max_pages=3, search=None, place=None,
                               with_detail=False)
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                mod.cmd_list(a)
            except SystemExit as e:
                code = e.code
        self.assertEqual(code, 6)
        self.assertEqual(out.getvalue(), "")
        self.assertIn("5013 characters", err.getvalue())
        self.assertIn("not an empty board", err.getvalue())
        self.assertNotIn("0 emitted", err.getvalue())

    def test_randstad_a_later_empty_page_is_still_the_end(self):
        """The direction that must stay open: page 2 empty after a full
        page 1 is the end of the listing, not a fault."""
        import contextlib
        mod = self._load("randstad")
        page1 = ("<html>" + "".join(
            f'<a href="/jobs/{i:08x}-0000-4000-8000-000000000000/">' for i in
            range(3)) + "</html>")
        real_cards = mod.cards
        mod.get = lambda url: (200, page1 if url.endswith("page=1") or
                               "page" not in url else "<html></html>")
        mod.cards = lambda body: ([{"id": str(i), "title": "t"} for i in
                                   range(3)] if "jobs" in body else [])
        a = argparse.Namespace(max_pages=3, search=None, place=None,
                               with_detail=False)
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                mod.cmd_list(a)
            except SystemExit as e:
                code = e.code
        mod.cards = real_cards
        self.assertIsNone(code, err.getvalue())
        self.assertIn("3 emitted, 3 ads over 1 page(s)", err.getvalue())

    def test_swissdevjobs_an_empty_list_from_the_whole_board_dies(self):
        import contextlib
        mod = self._load("swissdevjobs")
        mod.get_json = lambda url: []
        err = io.StringIO()
        code = None
        with contextlib.redirect_stderr(err):
            try:
                mod.fetch_board()
            except SystemExit as e:
                code = e.code
        self.assertEqual(code, 6)
        self.assertIn("EMPTY job list", err.getvalue())
        self.assertIn("not an empty board", err.getvalue())
        # and a non-empty list still passes through untouched
        mod.get_json = lambda url: [{"jobUrl": "x"}]
        self.assertEqual(mod.fetch_board(), [{"jobUrl": "x"}])


class ABoardThatPadsAZeroWithSuggestionsIsReadOnItsOwnList(unittest.TestCase):
    r"""**#219, 2026-09-11.** `jobbkk.py` returned 29 advertisements for
    `zzzqqqxxx`, `engineer` and the empty keyword alike. The filter had
    worked: the page's own store says `"jobpost_list":[]`, `"total":0` for the
    absurd word — and fills `"jobpost_list_suggest"` with 25 recommendations,
    which the adapter emitted as results. *A plain that affirms, the mirror
    of #181's zero that affirms.* `total` is 3 399 for `engineer`: the board
    declares its count, and the adapter never read it.

    Now only `jobpost_list` is emitted, `total` is printed beside the count
    («25 emitted … board states 3399 — 3374 short»), a stated 0 with an empty
    list is a real zero (nothing emitted, exit 0, the suggestions named), and
    a stated N > 0 with an empty list is a reading fault, exit 6.

    Mutated, `python3 -B`, detached copy: the results slice widened to the
    end of the store (suggestions leak) → the results case reddens; the
    `stated == 0` branch made unconditional → the reading-fault case reddens;
    the anchor dropped from the note → the results case reddens.
    """

    def _page(self, results, suggestions, total):
        def rec(i):
            return ('{\\"jobpost_id\\":%d,\\"company_id\\":9,\\"position\\":\\"P%d\\",'
                    '\\"salary_start\\":\\"\\",\\"salary_end\\":\\"\\"}' % (i, i))
        links = "".join(f'<a href="/jobs/detail/9/{i}">x</a>'
                        for i in results + suggestions)
        payload = ('self.__next_f.push([1,"\\"jobpost_list\\":['
                   + ",".join(rec(i) for i in results)
                   + '],\\"jobpost_list_suggest\\":['
                   + ",".join(rec(i) for i in suggestions)
                   + '],\\"total\\":%s,\\"search_result\\":[]"])' % total)
        return "<html>" + links + "<script>" + payload + "</script></html>"

    def _run(self, page):
        import contextlib
        spec = importlib.util.spec_from_file_location(
            "_jobbkk219", os.path.join(SCRIPTS, "jobbkk.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        mod.get = lambda path: page
        a = argparse.Namespace(keyword="x", province=None, category=None,
                               limit=None, pages=1, delay=0)
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                mod.cmd_search(a)
            except SystemExit as e:
                code = e.code
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        return code, rows, err.getvalue()

    def test_the_store_splits_results_from_suggestions_and_reads_the_total(self):
        spec = importlib.util.spec_from_file_location(
            "_jobbkk219s", os.path.join(SCRIPTS, "jobbkk.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        res, sug, total = mod.store(self._page([1, 2], [7, 8, 9], 3399))
        self.assertEqual([r["jobpost_id"] for r in res], [1, 2])
        self.assertEqual([r["jobpost_id"] for r in sug], [7, 8, 9])
        self.assertEqual(total, 3399)
        self.assertEqual(mod.store("<html>no store</html>"), (None, None, None))

    def test_only_results_are_emitted_and_the_boards_total_stands_beside_them(self):
        code, rows, err = self._run(self._page([1, 2], [7, 8, 9], 3399))
        self.assertIsNone(code, err)
        self.assertEqual([r["id"] for r in rows], ["9/1", "9/2"],
                         "a suggestion card reached stdout")
        self.assertIn("2 emitted over 1 page(s) read, board states 3399 — 3397 short", err)

    def test_a_stated_zero_with_suggestions_is_a_real_zero_and_emits_nothing(self):
        code, rows, err = self._run(self._page([], [7, 8, 9], 0))
        self.assertIsNone(code, err)
        self.assertEqual(rows, [])
        self.assertIn("board states 0 result(s)", err)
        self.assertIn("3 card(s) on the page are the board's own suggestions", err)

    def test_a_stated_count_with_an_empty_list_is_a_reading_fault(self):
        code, rows, err = self._run(self._page([], [7, 8, 9], 42))
        self.assertEqual(code, 6)
        self.assertEqual(rows, [])
        self.assertIn("reading fault", err)
        self.assertIn("42", err)


class TheLastThreeOfTheRePassDieThroughEmptyFirstPage(unittest.TestCase):
    """**#181, batch 5's two «absent» and one blind side — the last three of
    105, on the closure criterion the pilot set: a second figure from another
    branch wherever one exists, a motivated (b) where none does.**

    - `taleez`: a payload WITHOUT the `jobs` key read as «0 ads, a real zero»
      → dies 6 through `empty_first_page` with the payload's size; a payload
      WITH an empty `jobs` list is (b): the tenant's own feed, present and
      empty, the tenant named — the site's zero, said with its second signal;
    - `zaposli`: a child sitemap parsing to zero `<url>` entries printed a
      JSON of zeros, exit 0 → dies 6 with the size;
    - `talentsoft`: the `(N offres)` counter missing AND no card on page 1
      printed `? ads announced` then a zero, exit 0 → dies 6 with the size;
      the counter missing with cards present says so and continues.
    """

    def _mod(self, name):
        spec = importlib.util.spec_from_file_location(
            "_last3_" + name, os.path.join(SCRIPTS, name + ".py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _run(self, fn, *args):
        import contextlib
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                fn(*args)
            except SystemExit as e:
                code = e.code
        return code, out.getvalue(), err.getvalue()

    def test_taleez_a_payload_without_the_jobs_key_is_indeterminate(self):
        mod = self._mod("taleez")
        mod.robots_verdict = lambda host: {"sweep": True, "host": host,
                                           "reason": ""}
        mod.fetch = lambda url, as_json=False: {"name": "Acme",
                                                "properties": [], "x": "y" * 3000}
        a = argparse.Namespace(tenant="acme", url=None, with_detail=False,
                               delay=0)
        code, out, err = self._run(mod.cmd_jobs, a)
        self.assertEqual(code, 6, err)
        self.assertEqual(out, "")
        self.assertIn("characters", err)
        self.assertIn("INDETERMINATE", err)
        self.assertNotIn("a real zero", err)

    def test_taleez_an_empty_jobs_list_is_the_sites_own_zero_named(self):
        """(b), motivated: the second signal is the tenant's name in the
        payload, and the sentence says the list is present and empty."""
        mod = self._mod("taleez")
        mod.robots_verdict = lambda host: {"sweep": True, "host": host,
                                           "reason": ""}
        mod.fetch = lambda url, as_json=False: {"name": "Acme", "jobs": [],
                                                "properties": []}
        a = argparse.Namespace(tenant="acme", url=None, with_detail=False,
                               delay=0)
        code, out, err = self._run(mod.cmd_jobs, a)
        self.assertIsNone(code, err)
        self.assertIn("'Acme'", err)
        self.assertIn("present and", err)
        self.assertIn("empty: that is the site's own zero", err)
        self.assertIn("0 cards returned", err)

    def test_zaposli_a_child_sitemap_with_no_entries_is_indeterminate(self):
        mod = self._mod("zaposli")
        index = ('<sitemapindex><sitemap><loc>https://www.zaposli.me/sitemap/'
                 'oglasi.xml</loc></sitemap></sitemapindex>')
        child = "<urlset>" + "x" * 8000 + "</urlset>"
        mod.get = lambda url: (200, index if url.endswith("/sitemap.xml")
                               else child)
        code, out, err = self._run(mod.entries)
        self.assertEqual(code, 6, err)
        self.assertIn("8 ", err)                       # the size, formatted
        self.assertIn("<url> entry", err)
        self.assertIn("INDETERMINATE", err)

    def test_talentsoft_no_counter_and_no_card_is_indeterminate(self):
        mod = self._mod("talentsoft")
        mod.fetch = lambda url: "<html>" + "x" * 6000 + "</html>"
        a = argparse.Namespace(tenant="acme", url=None, lcid="fr-FR",
                               max_pages=2, delay=0, with_detail=False)
        code, out, err = self._run(mod.cmd_jobs, a)
        self.assertEqual(code, 6, err)
        self.assertEqual(out, "")
        self.assertIn("6 013 characters", err)
        self.assertIn("counter was not found", err)
        self.assertNotIn("? ads announced", err)

    def test_talentsoft_no_counter_with_cards_says_so_and_continues(self):
        """The direction that stays open: cards without a counter is a
        sweep with no anchor, said aloud, not a die."""
        mod = self._mod("talentsoft")
        real_rows = mod.rows
        mod.rows = lambda page: (["<block>"] if "first" in page else [])
        mod.card = lambda b, t: {"url": "https://x/1", "title": "t"}
        mod.fetch = lambda url: ("first" if "page=1" in url or
                                 url.endswith("(1)") else "second")
        a = argparse.Namespace(tenant="acme", url=None, lcid="fr-FR",
                               max_pages=2, delay=0, with_detail=False)
        code, out, err = self._run(mod.cmd_jobs, a)
        mod.rows = real_rows
        self.assertIsNone(code, err)
        self.assertIn("? ads announced", err)
        self.assertIn("NOT found", err)


class ACountryPageIsGeneratedFromTheCardsAndNamesItsDenominators(unittest.TestCase):
    """#195 — `bin/country-boards.py`. What a country page must carry, from
    the repository alone: the board table, the five numbers, the two ratios
    each naming its denominator, the fixed notice that the denominator is our
    list and not the market. Fixtures, not `shared/boards/`: a card with a
    script, a `none` with a date (faisable établi), a `none` with no date (à
    revérifier — #195 ①: an undated «not feasible» is not a denominator), a
    `none` with a DATED 403 (INDÉTERMINÉ, named), a worldwide `*` card (listed
    apart), and a README carrying three `countries:` lines of example that
    must not enter its own count.
    """

    TOOL = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                        "bin", "country-boards.py")

    def _boards(self):
        import tempfile
        d = tempfile.mkdtemp()
        def card(name, body):
            with open(os.path.join(d, name + ".md"), "w", encoding="utf-8") as fh:
                fh.write(body)
        card("README", "# Cards\n\n<!-- countries: XX -->\n<!-- countries: XX YY -->\n"
                       "<!-- countries: * -->\n<!-- script: example.py -->\n")
        card("alpha", "# A\n\n<!-- verified: 2026-09-01 -->\n<!-- hosts: a.example -->\n"
                      "<!-- script: alpha.py -->\n<!-- countries: XX -->\n"
                      "<!-- content: measured · 12 ads · 2026-09-01 -->\n")
        card("beta", "# B\n\n<!-- verified: 2026-09-02 -->\n<!-- hosts: b.example -->\n"
                     "<!-- script: none -->\n<!-- countries: XX YY -->\n"
                     "<!-- content: measured · 40 ads stated by the site · 2026-09-02 -->\n"
                     "Rules open, the index served 40 `<loc>`.\n")
        card("gamma", "# G\n\n<!-- hosts: g.example -->\n<!-- script: none -->\n"
                      "<!-- countries: XX -->\n"
                      "The host refuses our client. No date was recorded.\n")
        card("delta", "# D\n\n<!-- verified: 2026-09-08 -->\n<!-- hosts: d.example -->\n"
                      "<!-- script: none -->\n<!-- countries: XX -->\n"
                      "<!-- content: measured · 300 ads · 2026-09-08 -->\n"
                      "GET / -> HTTP 403, 25 bytes, fetch-body.py, 2026-09-08\n")
        card("world", "# W\n\n<!-- hosts: w.example -->\n<!-- script: world.py -->\n"
                      "<!-- countries: * -->\n")
        # the two closures no route crosses — counted apart, named, out of
        # «faisable», in «total» — and a card that DECLARES itself indeterminate
        card("wall", "# Wall\n\n<!-- verified: 2026-09-11 -->\n<!-- hosts: wall.example -->\n"
                     "<!-- script: none -->\n<!-- countries: ZZ -->\n\n```\nUser-agent: *\n"
                     "Disallow: /\n```\n")
        card("dead", "# Dead\n\n<!-- verified: 2026-09-11 -->\n<!-- hosts: dead.example -->\n"
                     "<!-- script: none -->\n<!-- countries: ZZ -->\n\n1.1.1.1 NXDOMAIN, 8.8.8.8 NXDOMAIN\n")
        card("shell", "# Shell\n\n<!-- verified: 2026-09-11 -->\n<!-- hosts: s.example -->\n"
                      "<!-- script: none -->\n<!-- countries: ZZ -->\n"
                      "<!-- content: indeterminate · a shell, zero advertisements · 2026-09-11 -->\n")
        return d

    def _run(self, *args):
        import subprocess
        r = subprocess.run([sys.executable, "-B", self.TOOL, *args],
                           capture_output=True, text=True)
        return r.returncode, r.stdout, r.stderr

    def test_the_table_has_one_row_per_card_declaring_the_country_readme_excluded(self):
        d = self._boards()
        code, out, err = self._run("XX", "--boards", d)
        self.assertEqual(code, 0, err)
        rows = [l for l in out.splitlines() if l.startswith("| `")]
        self.assertEqual([r.split("`")[1] for r in rows],
                         ["alpha", "beta", "delta", "gamma"])
        self.assertNotIn("`README`", out)
        self.assertNotIn("example.py", out)
        self.assertIn("8 fiches, README exclu", out)       # the population, said
        self.assertIn("| Board | Ce qu'il couvre | Accès | Statut | Mesuré |", out)

    def test_the_five_numbers_and_the_two_ratios_name_their_denominators(self):
        d = self._boards()
        _c, out, _e = self._run("XX", "--boards", d)
        self.assertIn("fait              1", out)
        self.assertIn("mesuré sans refus 1", out)      # ex-«faisable établi», #232
        self.assertIn("INDÉTERMINÉS      1     refus consigné avec sa date — delta", out)
        self.assertIn("à REVÉRIFIER      1     sans date, ou refus sans date — gamma", out)
        self.assertIn("total             4", out)
        # #232: the INDÉTERMINÉ (delta) and the à REVÉRIFIER (gamma) stay IN
        # the denominator — 1 / 4, not 1 / 2 — and are named as counting
        self.assertIn("fait / faisable   1 / 4    (faisable = total - écartés datés et motivés - non faisables ; "
                      "dont 1 indéterminé(s) et 1 à revérifier, qui COMPTENT)", out)
        self.assertIn("fait / total      1 / 4    (total = toutes les fiches déclarant XX", out)
        self.assertIn("Ce n'est pas le marché du pays.", out)

    def test_an_undated_none_is_a_recheck_not_a_denominator(self):
        """#195 ①, the direction that must stay closed: `gamma` must not
        raise `faisable` — with it, the ratio would read 1 / 3."""
        d = self._boards()
        _c, out, _e = self._run("XX", "--boards", d)
        self.assertNotIn("1 / 3", out)
        self.assertIn("gamma` |", out)
        self.assertIn("| à REVÉRIFIER | — |", out)

    def test_worldwide_cards_are_listed_apart_and_outside_the_ratios(self):
        d = self._boards()
        _c, out, _e = self._run("YY", "--boards", d)
        self.assertIn("total             1", out)             # beta only
        self.assertIn("Boards mondiaux (`countries: *`) — 1", out)
        self.assertIn("`world`", out)

    def test_the_html_fragment_carries_the_same_content_and_is_well_formed(self):
        import html.parser
        d = self._boards()
        _c, out, _e = self._run("XX", "--boards", d, "--html")

        class P(html.parser.HTMLParser):
            def __init__(self):
                super().__init__()
                self.stack = []

            def handle_starttag(self, t, a):
                self.stack.append(t)

            def handle_endtag(self, t):
                assert self.stack and self.stack[-1] == t, (self.stack[-3:], t)
                self.stack.pop()
        p = P()
        p.feed(out)
        self.assertEqual(p.stack, [])
        self.assertEqual(out.count("<tr>"), 5)               # header + 4
        self.assertIn("fait / total      1 / 4", out)
        self.assertIn("marché du pays", out)

    def test_a_written_refusal_and_a_dead_name_are_excluded_apart_not_feasible(self):
        """A `Disallow: /` to `*` (bound 1) and an NXDOMAIN on two resolvers
        are closures no route crosses — neither INDÉTERMINÉ nor faisable —
        counted apart as «écartés NON validés», named, out of the feasible
        denominator and in the total; and `content: indeterminate` is the
        card's own word, read as such."""
        d = self._boards()
        _c, out, _e = self._run("ZZ", "--boards", d)
        self.assertIn("écartés NON validés 2", out)
        self.assertIn("— dead, wall", out)
        self.assertIn("refus écrit dans les règles", out)
        self.assertIn("NXDOMAIN sur deux résolveurs", out)
        self.assertIn("INDÉTERMINÉS      1     refus consigné avec sa date — shell", out)
        # #232: the two dated, motivated exclusions leave the denominator;
        # the INDÉTERMINÉ (shell) stays — 0 / 1, not 0 / 0
        self.assertIn("fait / faisable   0 / 1", out)
        self.assertIn("fait / total      0 / 3", out)
        self.assertIn("écartés VALIDÉS   0", out)

    def test_all_counts_per_member_and_never_prints_zero_for_an_unmapped_one(self):
        import tempfile
        d = self._boards()
        m = tempfile.NamedTemporaryFile("w", suffix=".txt", delete=False,
                                        encoding="utf-8")
        # the members file speaks alpha-3; XX/YY are not ISO, so a real code
        # with no card (CHE) and an unknown one (ZZZ) are the two edges
        m.write("CHE\tSuisse\tsuisse\thttps://x\nZZZ\tNulle-part\tnp\thttps://y\n")
        m.close()
        self.addCleanup(os.unlink, m.name)
        code, out, err = self._run("--all", "--members", m.name, "--boards", d)
        self.assertEqual(code, 0, err)
        self.assertIn("CHE\tCH\tSuisse\t0\t0\t0\t0\t0\t0", out)
        self.assertIn("ZZZ\tUNMAPPED\tNulle-part\t?\t?\t?\t?\t?\t?", out)
        self.assertIn("1 UNMAPPED (not zero: unknown)", err)
        self.assertIn("3 ISO2 declared by cards and absent from the members file: XX, YY, ZZ", err)


class JobindexReadsPageOneAndSaysTheRulesAreTheCap(unittest.TestCase):
    """`jobindex.py` — Denmark's first adapter, 2026-09-11. The board's
    `www` rules refuse `/jobsoegning*page=`, so a query is one page of 20
    with one parameter, and the count the adapter prints carries the site's
    `hitcount` beside what it emitted, and the sentence that the cap is the
    rules'. The data is a JSON the page embeds (`Stash`); no JSON is a
    reading fault (exit 6, size beside the zero), `hitcount: 0` with no
    result is a real zero said aloud, and results and hitcount disagreeing
    is a fault. The apex `jobindex.dk` publishes `Disallow: /` — every URL
    is built on `www`, and the guard is asked inside `get()`.
    """

    def _mod(self):
        spec = importlib.util.spec_from_file_location(
            "_jobindex_t", os.path.join(SCRIPTS, "jobindex.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _page(results, hitcount, pages=None):
        import json as _j
        sr = {"hitcount": hitcount, "page_size": 20,
              "total_pages": pages if pages is not None else (hitcount + 19) // 20,
              "results": results}
        stash = {"common": {}, "jobsearch/result_app": {"storeData": {"searchResponse": sr}}}
        return ("<html><script>//<![CDATA[ var Stash = " + _j.dumps(stash)
                + ";//]]></script>" + "x" * 3000 + "</html>")

    def _run(self, mod, fn, a):
        import contextlib
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                fn(a)
            except SystemExit as e:
                code = e.code
        return code, out.getvalue(), err.getvalue()

    def test_every_url_is_built_on_www_and_the_ad_url_comes_from_the_id(self):
        mod = self._mod()
        self.assertEqual(mod.HOST, "www.jobindex.dk")
        self.assertEqual(mod.search_url("udvikler"),
                         "https://www.jobindex.dk/jobsoegning?q=udvikler")
        self.assertEqual(mod.search_url("udvikler", "it"),
                         "https://www.jobindex.dk/jobsoegning/it?q=udvikler")
        self.assertEqual(mod.ad_url("h1697049"),
                         "https://www.jobindex.dk/vis-job/h1697049")
        src = open(os.path.join(SCRIPTS, "jobindex.py"), encoding="utf-8").read()
