class ACumulativeCounterIsNotTheAnchorAndTheDeadlineIs(unittest.TestCase):
    """**`greatugandajobs.py`, 2026-09-11.** The site says «103 391 Jobs
    Posted» — everything ever posted, 102 924 nine days earlier — and no page
    says how many are open. The anchor is the deadline every card carries,
    read against the day: live versus expired, printed beside the count. And
    the listing is a live stream: pinned Gold cards on every page, a step
    that counts the whole page, new ids arriving between requests — so rows
    read stand beside distinct and nothing claims completeness.

    Mutated, `python3 -B`, detached copy: the deadline parser returning None
    → the live/expired case reddens; the cumulative counter printed as
    «board states» → the counter case reddens; Gold cards dropped from the
    dedupe (repeated not counted) → the stream case reddens; the empty-page
    die removed → the empty case reddens.
    """

    def _mod(self):
        spec = importlib.util.spec_from_file_location(
            "_gu", os.path.join(SCRIPTS, "greatugandajobs.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _card(ident, title, deadline, gold=False):
        st = '<span class="js-status js-type">Full-time</span><span class="js-status bg-new">New</span>'
        if gold:
            st += '<span class="js-status bg-gold">Gold</span>'
        return ('<div class="js-toprow"><div class="js-image"><a href="/jobs/company-detail/company-Acme-79/nav-31">'
                '<img src="x" title="Acme Ltd"></a></div><div class="js-data"><div class="js-first-row">'
                f'<span class="js-title">{st}</span></div><div class="js-first-row"><span class="js-title">'
                f'<a class="jobtitle" href="/jobs/job-detail/job-{title.replace(" ", "-")}-{ident}">{title}</a></span></div>'
                '<div class="js-second-row"><div class="js-fields"><span class="js-bold">Job Category: </span>IT jobs in Uganda</div>'
                '<div class="js-fields"><span class="js-bold">Posted: </span>Today</div>'
                f'<div class="js-fields"><span class="js-bold">Deadline of this Job:&nbsp</span><span class="get-text">{deadline}</span></div>'
                '<div class="js-fields"><span class="js-bold">Duty Station:&nbsp</span><span class="get-text">Kampala | Uganda</span></div>'
                '</div></div></div>')

    def _page(self, cards, total="102836"):
        return ('<html><body><div class="page_heading">Jobs in Uganda <div class="totaljobsheading">Total jobs: '
                f'<span>{total}</span></div></div><div id="js-jobs-wrapper">' + "".join(cards) + '</div></body></html>')

    def _run(self, mod, pages, argv=None):
        import contextlib
        served = iter(pages)
        mod.get = lambda url: (200, next(served, self._page([])))
        a = argparse.Namespace(pages=len(pages), live=False, limit=None, delay=0)
        for k, v in (argv or {}).items():
            setattr(a, k, v)
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                mod.cmd_list(a)
            except SystemExit as e:
                code = e.code
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        return code, rows, err.getvalue()

    def test_the_deadline_is_read_and_splits_live_from_expired(self):
        mod = self._mod()
        self.assertEqual(mod.deadline_iso("Thursday, October 8 2026"), "2026-10-08")
        self.assertIsNone(mod.deadline_iso("À définir"))
        page = self._page([self._card("1", "Nurse", "Thursday, October 8 2099"),
                           self._card("2", "Driver", "Monday, January 5 2015")])
        code, rows, err = self._run(mod, [page])
        self.assertIsNone(code, err)
        self.assertEqual([r["deadline"] for r in rows], ["2099-10-08", "2015-01-05"])
        self.assertIn("live 1 · expired 1 · undated 0", err)
        code, rows, err = self._run(mod, [page], {"live": True})
        self.assertEqual([r["id"] for r in rows], ["1"])

    def test_the_cumulative_counter_is_named_and_never_stands_as_the_anchor(self):
        mod = self._mod()
        _, _, err = self._run(mod, [self._page([self._card("1", "Nurse", "Thursday, October 8 2099")])])
        self.assertIn("«Total jobs: 102 836»", err)
        self.assertIn("cumulative counter", err)
        self.assertNotIn("board states", err)
        self.assertNotIn("short", err)

    def test_a_pinned_gold_card_is_emitted_once_and_counted_as_repeated(self):
        mod = self._mod()
        gold = self._card("9", "Gold Manager", "Thursday, October 8 2099", gold=True)
        p1 = self._page([gold, self._card("1", "Nurse", "Thursday, October 8 2099")])
        p2 = self._page([gold, self._card("2", "Driver", "Thursday, October 8 2099")])
        code, rows, err = self._run(mod, [p1, p2])
        self.assertIsNone(code, err)
        self.assertEqual([r["id"] for r in rows], ["9", "1", "2"])
        self.assertTrue(rows[0]["gold"])
        self.assertIn("3 emitted of 3 distinct; 4 rows read on 2 page(s) (2+2), 1 repeated", err)

    def test_an_empty_first_page_is_indeterminate(self):
        mod = self._mod()
        code, rows, err = self._run(mod, [self._page([])])
        self.assertEqual(code, 6)
        self.assertEqual(rows, [])
        self.assertIn("INDETERMINATE", err)

    def test_the_second_page_asks_for_the_whole_page_step(self):
        mod = self._mod()
        urls = []
        real = self._page([self._card("1", "Nurse", "Thursday, October 8 2099")])
        page2 = self._page([self._card("2", "Driver", "Thursday, October 8 2099")])
        served = iter([real, page2])
        mod.get = lambda url: (urls.append(url), (200, next(served)))[1]
        import contextlib
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_list(argparse.Namespace(pages=2, live=False, limit=None, delay=0))
        self.assertEqual(urls[1], mod.LIST + "?start=28")


class AnInventoryOfAddressesSaysItIsNotAnInventoryOfAdvertisements(unittest.TestCase):
    """**`wuzzuf.py`, 2026-09-11.** The host serves its sitemap and answers
    a challenge on every page: 5 491 addresses, none readable. So the adapter
    counts where it decides — raw, matched, unmatched, distinct — maps the
    country off the slug's tail, shows `--country` reducing, names a single
    `<lastmod>` value as a rebuild stamp, and `ad` names the challenge
    rather than returning an empty page. Mutated (`-B`, detached copy): the
    country tail map emptied → the split case reddens; `unmatched` folded
    into `matched` → the shape case reddens; the stamp sentence removed →
    the stamp case reddens; `ad`'s challenge branch removed → the ad case
    reddens (exit 6, not 9)."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location(
            "_wuzzuf", os.path.join(SCRIPTS, "wuzzuf.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    INDEX = ('<sitemapindex><sitemap><loc>https://wuzzuf.net/sitemap-job-1.xml</loc></sitemap>'
             '<sitemap><loc>https://wuzzuf.net/sitemap-saudi-job-1.xml</loc></sitemap></sitemapindex>')

    @staticmethod
    def _file(urls, stamp="2026-09-11T02:04:48+03:00"):
        return "<urlset>" + "".join(f"<url><loc>{u}</loc><lastmod>{stamp}</lastmod></url>" for u in urls) + "</urlset>"

    URLS = ["https://wuzzuf.net/jobs/p/reb7hiksiwdr-ai-video-engineer-ius-cairo-egypt",
            "https://wuzzuf.net/jobs/p/1dmprnl4o95e-bd-executive-olis-dubai-united-arab-emirates",
            "https://wuzzuf.net/internship/ysxvu8mwwhfn-marketing-intern-smart-cairo-egypt",
            "https://wuzzuf.net/saudi/jobs/p/kn3scntb3ugj-sharepoint-admin-wsc-riyadh-saudi-arabia",
            "https://wuzzuf.net/jobs/browse/cairo"]

    def _run(self, mod, bodies, **argv):
        import contextlib
        served = iter(bodies)
        mod.get = lambda url: next(served)
        a = argparse.Namespace(country=None, saudi=False, limit=None)
        for k, v in argv.items():
            setattr(a, k, v)
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                mod.cmd_sitemap(a)
            except SystemExit as e:
                code = e.code
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        return code, rows, err.getvalue()

    def test_the_slug_tail_becomes_a_country_and_the_filter_reduces(self):
        mod = self._mod()
        code, rows, err = self._run(mod, [(200, self.INDEX), (200, self._file(self.URLS))])
        self.assertIsNone(code, err)
        self.assertEqual([r["country"] for r in rows], ["EG", "AE", "EG", "SA"])
        self.assertTrue(all(r["readable_by_script"] is False for r in rows))
        code, rows, err = self._run(mod, [(200, self.INDEX), (200, self._file(self.URLS))], country="eg")
        self.assertEqual([r["id"] for r in rows], ["reb7hiksiwdr", "ysxvu8mwwhfn"])
        self.assertIn("2 distinct id(s) after --country eg", err)

    def test_raw_matched_unmatched_are_counted_where_they_are_decided(self):
        mod = self._mod()
        _, _, err = self._run(mod, [(200, self.INDEX), (200, self._file(self.URLS))])
        self.assertIn("5 <loc> in 1 file(s); 4 matched the advertisement shape and 1 did not; 4 distinct", err)
        self.assertIn("jobs/p 2", err)

    def test_one_lastmod_value_on_every_entry_is_named_a_rebuild_stamp(self):
        mod = self._mod()
        _, _, err = self._run(mod, [(200, self.INDEX), (200, self._file(self.URLS))])
        self.assertIn("regeneration stamp", err)
        self.assertIn("addresses, not advertisements", err)

    def test_ad_names_the_challenge_and_exits_9(self):
        import contextlib
        mod = self._mod()
        mod.get = lambda url: (403, "<html><title>Just a moment...</title>" + "x" * 5600 + "</html>")
        err = io.StringIO()
        code = None
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err):
            try:
                mod.cmd_ad(argparse.Namespace(url=self.URLS[0]))
            except SystemExit as e:
                code = e.code
        self.assertEqual(code, 9)
        self.assertIn("anti-robot challenge", err.getvalue())
        self.assertIn("does not attempt to pass it", err.getvalue())


class ARefusalIsClassifiedByWhoWroteItNotByWhetherItRefuses(unittest.TestCase):
    """**#226, 2026-09-11.** `jobmada.com` publishes `User-agent: * /
    Disallow: /` — 26 bytes — and `identity()` said `browser`: both tokens
    refused, so «the browser branch applies». *They were refused by the group
    addressed to everybody.* Borne 1 of the 2026-09-07 decision: a refusal
    written in the rules blocks every route, the browser included. `browser`
    was written for the other shape — both tokens named and refused, `*`
    open — and `verdict()` had this one right («everything closed, evenly»).
    The fourth disagreement between the module's paths, after #201's on HTTP
    codes.

    So `identity()` now returns `closed` for a refusal by `*` (or by a rules
    file refused at the transport), with the rule that decided, and
    `browser` only for the named refusal of both tokens with `*` open. And
    the concordance table of #201 extends from HTTP codes to the SHAPES of a
    refusal — one row per shape, all three paths asked, the one known
    divergence named as such rather than hidden.

    Mutated (`python3 -B`, detached copy): the `named` test loosened so a
    `*` refusal counts as named → the `*`-closed row reddens; `closed`
    renamed back to `browser` → the same row and the transport row redden;
    the `rule` dropped → the `*`-closed row reddens on its rule.
    """

    SHAPES = {
        # name: (robots body or HTTP status, verdict.sweep, allowed, identity.state)
        "star closed — jobmada": ("User-agent: *\nDisallow: /\n", False, False, "closed"),
        "both tokens named and closed, star open": (
            "User-agent: ClaudeBot\nDisallow: /\nUser-agent: Claude-User\nDisallow: /\n"
            "User-agent: *\nAllow: /\n", False, False, "browser"),
        "both tokens named and closed, no star group": (
            "User-agent: ClaudeBot\nDisallow: /\nUser-agent: Claude-User\nDisallow: /\n",
            False, False, "browser"),
        "ClaudeBot named by star, Claude-User refused by star": (
            "User-agent: ClaudeBot\nDisallow: /\nUser-agent: *\nDisallow: /\n", False, False, "closed"),
        "ClaudeBot named and closed, star open (2026-09-07)": (
            "User-agent: ClaudeBot\nDisallow: /\nUser-agent: *\nAllow: /\n", True, True, "http"),
        "no group at all (#180)": ("Disallow: /admin/\nDisallow: /tmp/\n", True, True, "http"),
        "401 on the rules file (#201)": (401, True, True, "http"),
        # #283, owner's decision of 2026-09-13: every unread rules file is an
        # absence of rules — these two rows read (False, False, "closed")
        # until then, and a guard that asserted that would be restored as a fix
        "403 on the rules file (#283)": (403, True, True, "http"),
        "429 on the rules file (#283)": (429, True, True, "http"),
    }

    class _Resp:
        def __init__(self, body):
            self._b = body.encode("utf-8")
            self.headers = {"Content-Type": "text/plain"}
        def read(self):
            return self._b
        def getcode(self):
            return 200
        def geturl(self):
            return "https://h.example/robots.txt"
        def __enter__(self):
            return self
        def __exit__(self, *a):
            return False

    def _paths(self, shape):
        import _robots
        real = _robots.urllib.request.urlopen
        back = _robots._BACKOFF
        _robots._BACKOFF = (0, 0)
        _robots._CACHE.clear()
        _robots._ALIAS.clear()
        if isinstance(shape, int):
            def serve(*a, **k):
                raise _robots.urllib.error.HTTPError(
                    "https://h.example/robots.txt", shape, "x", {}, io.BytesIO(b""))
        else:
            def serve(*a, **k):
                return self._Resp(shape)
        _robots.urllib.request.urlopen = serve
        try:
            v = _robots.verdict("h.example")
            a = _robots.allowed("h.example", "/x")
            i = _robots.identity("h.example", "/x")
            return v, a, i
        finally:
            _robots.urllib.request.urlopen = real
            _robots._BACKOFF = back
            _robots._CACHE.clear()
            _robots._ALIAS.clear()

    def test_every_shape_gives_the_same_answer_on_all_three_paths(self):
        for name, (shape, sweep, allowed, state) in self.SHAPES.items():
            with self.subTest(shape=name):
                v, a, i = self._paths(shape)
                self.assertIs(v["sweep"], sweep, f"verdict() on {name}")
                self.assertIs(a["allowed"], allowed, f"allowed() on {name}")
                self.assertEqual(i["state"], state, f"identity() on {name}: {i['reason'][:120]}")

    def test_a_star_refusal_names_the_rule_that_decided_and_is_not_the_browser_branch(self):
        _, _, i = self._paths("User-agent: *\nDisallow: /\n")
        self.assertEqual(i["state"], "closed")
        self.assertEqual(i["rule"], "/")
        self.assertIsNone(i["token"])
        self.assertIn("addressed to everybody", i["reason"])
        self.assertIn("not the browser branch", i["reason"])

    def test_a_named_refusal_of_both_with_star_open_is_the_browser_branch(self):
        _, _, i = self._paths("User-agent: ClaudeBot\nDisallow: /\nUser-agent: Claude-User\n"
                              "Disallow: /\nUser-agent: *\nAllow: /\n")
        self.assertEqual(i["state"], "browser")
        self.assertIn("BY NAME", i["reason"])

    def test_a_rules_file_refused_at_the_transport_is_the_http_route_since_283(self):
        # REPLACES `…_is_closed_with_the_transport_reason` (2026-09-11) — #283,
        # owner's decision of 2026-09-13: nothing was read, nothing forbids
        _, _, i = self._paths(403)
        self.assertEqual(i["state"], "http")
        self.assertEqual(i["token"], "claude-user")
        self.assertIsNone(i.get("rule"))

    def test_verdict_follows_the_named_refusal_decision_since_2026_09_11(self):
        """**Flipped on purpose, the same day it was pinned.** This was
        `…_KNOWN_DIVERGENCE`: `ClaudeBot` named and refused, `*` open —
        `allowed()` and `identity()` followed the owner's decision of
        2026-09-07 and `verdict()['sweep']` did not, so nineteen adapters
        gating on it exited 7 on hosts the decision had opened. The pilot
        read the decision's own consequences back («thirteen boards open by
        ordinary HTTP») and the sweep now follows: swept as `claude-user`,
        the closing record still named in the reason."""
        v, a, i = self._paths("User-agent: ClaudeBot\nDisallow: /\nUser-agent: *\nAllow: /\n")
        self.assertIs(a["allowed"], True)
        self.assertEqual(i["state"], "http")
        self.assertEqual(i["token"], "claude-user")
        self.assertIs(v["sweep"], True)
        self.assertEqual(v["sweep_token"], "claude-user")
        self.assertIn("claudebot", v["reason"])
        # and a refusal by `*` still closes the sweep — the decision is about
        # a NAMED record, not about refusals in general
        v2, _, _ = self._paths("User-agent: *\nDisallow: /\n")
        self.assertIs(v2["sweep"], False)


class AnAdapterGatingOnSweepNoLongerExits7OnANamedRefusal(unittest.TestCase):
    """**The consequence the decision of 2026-09-07 named — «thirteen boards
    open by ordinary HTTP» — reached `allowed()` and not `verdict()['sweep']`,
    and nineteen adapters gate their listing on `sweep` before ever asking
    `allowed()`.** So this drives one of them, `successfactors.cmd_list`,
    through the REAL `verdict()` on the Cloudflare managed file served for a
    fixture host, with the network stopped right after the gate: before
    2026-09-11 it exited 7 there; now it passes the gate and reaches the
    search. Mutated: the sweep-follows block in `verdict()` disabled →
    exit 7 again and this case reddens."""

    MANAGED = ("User-agent: *\nContent-Signal: search=yes,ai-train=no\nAllow: /\n\n"
               "User-agent: ClaudeBot\nDisallow: /\n")

    def test_successfactors_passes_the_gate_on_a_managed_file(self):
        import contextlib
        import _robots
        spec = importlib.util.spec_from_file_location(
            "_sf_sweep", os.path.join(SCRIPTS, "successfactors.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)

        class Resp:
            headers = {"Content-Type": "text/plain"}
            def read(self_):
                return self.MANAGED.encode()
            def getcode(self_):
                return 200
            def geturl(self_):
                return "https://t.example/robots.txt"
            def __enter__(self_):
                return self_
            def __exit__(self_, *a):
                return False
        real = _robots.urllib.request.urlopen
        back = _robots._BACKOFF
        _robots._BACKOFF = (0, 0)
        _robots._CACHE.clear()
        _robots._ALIAS.clear()
        _robots.urllib.request.urlopen = lambda *a, **k: Resp()
        reached = []
        mod.route_for = lambda host: (reached.append("route"), ("api", "stubbed"))[1]
        mod.search = lambda *a, **k: (reached.append("search"), {"totalJobs": 0, "jobSearchResult": []})[1]
        mod.refuse_on_error = lambda *a, **k: None
        code = None
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            try:
                mod.cmd_list(argparse.Namespace(host="t.example", locale="fr_FR", keywords=None,
                                                pages=1, with_description=False))
            except SystemExit as e:
                code = e.code
            finally:
                _robots.urllib.request.urlopen = real
                _robots._BACKOFF = back
                _robots._CACHE.clear()
                _robots._ALIAS.clear()
        self.assertNotEqual(code, 7, "the gate on `sweep` still exits 7 on a file "
                                     "that names ClaudeBot and leaves `*` open")
        self.assertIn("search", reached, "the run never reached the listing")


class NetEmpregosReadsTheTwoFeedsThatHoldAndNamesTheFourThatDoNot(unittest.TestCase):
    """`netempregos.py` — Portugal's first adapter, 2026-09-11. The host
    declares seven sitemaps; two hold (the RSS, 1 000 items with the employer
    on each; the sitemap, 5 000 advertisement URLs) and four answer the HOME
    PAGE with a 200 and ~71 KB — a status check and a size check both pass
    them, and only the count of advertisements extracted sees it. So a feed
    that yields zero items dies through `empty_first_page`, and says when the
    body is the home page. The ad page's `JobPosting` carries the reader's
    clock as `datePosted`; the adapter emits it under a name that says so.
    """

    HOME = ('\r \r <!DOCTYPE html>\r <html lang="pt-pt">\r <head><title>Emprego  '
            'Trovit_all.asp  - Setembro 2026</title></head><body>' + "x" * 70000
            + "</body></html>")

    @staticmethod
    def _item(ident, zona, cat, company="ACME LDA"):
        return (f"<item><title><![CDATA[Title {ident}]]></title>"
                f"<dc:creator><![CDATA[{company}]]></dc:creator>"
                f"<link>https://www.net-empregos.com/{ident}/some-slug/</link>"
                f"<description><![CDATA[&lt;b&gt;Empresa: &lt;/b&gt;{company}&lt;br&gt;"
                f"&lt;b&gt;Categoria: &lt;/b&gt;{cat}&lt;br&gt;&lt;b&gt;Zona: &lt;/b&gt; {zona}"
                f"&lt;br&gt;&lt;b&gt;Data: &lt;/b&gt;11-9-2026&lt;br&gt;&lt;br&gt;"
                f"&lt;b&gt;Descrição: &lt;/b&gt;Texto da oferta...]]></description>"
                f"<pubDate>Fri, 11 Sep 2026 15:19:31 GMT</pubDate>"
                f"<guid>https://www.net-empregos.com/{ident}/some-slug/</guid></item>")

    def _mod(self):
        spec = importlib.util.spec_from_file_location(
            "_netempregos_t", os.path.join(SCRIPTS, "netempregos.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _run(self, fn, a):
        import contextlib
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                fn(a)
            except SystemExit as e:
                code = e.code
        return code, out.getvalue(), err.getvalue()

    def test_the_feed_yields_cards_with_the_employer_and_the_feeds_dates(self):
        mod = self._mod()
        rss = ("<rss><channel>" + self._item(1, "Lisboa", "Informática ( Programação )")
               + self._item(2, "Porto", "Comercial / Vendas") + "</channel></rss>")
        mod.get = lambda url: (200, rss)
        a = argparse.Namespace(zona=None, categoria=None, limit=0)
        code, out, err = self._run(mod.cmd_feed, a)
        self.assertIsNone(code, err)
        rows = [json.loads(l) for l in out.splitlines()]
        self.assertEqual(len(rows), 2)
        self.assertEqual(rows[0]["ledger_id"], "net-empregos:1")
        self.assertEqual(rows[0]["company"], "ACME LDA")
        self.assertEqual(rows[0]["location"], "Lisboa")
        self.assertEqual(rows[0]["category"], "Informática ( Programação )")
        self.assertEqual(rows[0]["date"], "11-9-2026")
        self.assertIn("2 emitted, 2 items read", err)
        self.assertIn("2 of 2 name their employer", err)
        self.assertIn("its own cap, not the board's", err)

    def test_a_filter_reduces_and_an_empty_filter_prints_what_the_feed_spells(self):
        mod = self._mod()
        rss = ("<rss>" + self._item(1, "Lisboa", "A") + self._item(2, "Porto", "B")
               + self._item(3, "Porto", "A") + "</rss>")
        mod.get = lambda url: (200, rss)
        code, out, err = self._run(mod.cmd_feed, argparse.Namespace(
            zona="Porto", categoria=None, limit=0))
        self.assertEqual(len(out.splitlines()), 2)
        self.assertIn("2 emitted, 3 items read, 1 dropped", err)
        code, out, err = self._run(mod.cmd_feed, argparse.Namespace(
            zona="Faro", categoria=None, limit=0))
        self.assertEqual(out, "")
        self.assertIsNone(code)
        self.assertIn("the feed is not empty", err)
        self.assertIn("Porto 2", err)
        self.assertIn("Lisboa 1", err)

    def test_the_four_feeds_that_answer_the_home_page_are_a_reading_fault_named(self):
        """The negative fixture: a 200 of 70 KB that is the home page. A status
        check passes it, a size check passes it; the count of items is zero
        and the adapter dies 6, and says the body is the HOME PAGE."""
        mod = self._mod()
        mod.get = lambda url: (200, self.HOME)
        for fn, ns in ((mod.cmd_feed, argparse.Namespace(zona=None, categoria=None, limit=0)),
                       (mod.cmd_list, argparse.Namespace(limit=0))):
            with self.subTest(cmd=fn.__name__):
                code, out, err = self._run(fn, ns)
                self.assertEqual(code, 6, err)
                self.assertEqual(out, "")
                self.assertIn("HOME PAGE", err)
                self.assertIn("INDETERMINATE", err)
                self.assertIn("characters", err)

    def test_the_sitemap_lists_distinct_ids_and_counts_the_duplicates(self):
        mod = self._mod()
        body = ("\r  https://www.net-empregos.com/10/a/\r https://www.net-empregos.com/11/b/\r"
                " https://www.net-empregos.com/10/a/\r")
        mod.get = lambda url: (200, body)
        code, out, err = self._run(mod.cmd_list, argparse.Namespace(limit=0))
        self.assertIsNone(code, err)
        self.assertEqual(len(out.splitlines()), 2)
        self.assertIn("2 emitted, 2 distinct ids in 3 advertisement URLs from 3 lines, 1 duplicate", err)

    def test_the_ad_emits_the_jobposting_dates_under_names_that_say_they_are_the_clock(self):
        mod = self._mod()
        page = ('<html><script type = "application/ld+json" >{"@context":"http://schema.org",'
                '"@type":"JobPosting","title":"T","datePosted":"2026-9-11 15:24 UTC",'
                '"validThrough":"2026-10-11 15:24 UTC","hiringOrganization":{"@type":"Organization",'
                '"name":"ACME"},"jobLocation":{"@type":"Place","address":{"@type":"PostalAddress",'
                '"addressLocality":"Setubal"}},"description":"<p>Texto</p>"}</script></html>')
        mod.get = lambda url: (200, page)
        code, out, err = self._run(mod.cmd_ad, argparse.Namespace(id="15978698"))
        self.assertIsNone(code, err)
        d = json.loads(out)
        self.assertEqual(d["rendered_at_as_datePosted"], "2026-9-11 15:24 UTC")
        self.assertNotIn("datePosted", d)
        self.assertNotIn("date", {k for k in d if k not in ("rendered_at_as_datePosted",)})
        self.assertEqual(d["company"], "ACME")
        self.assertEqual(d["description"], "Texto")
        self.assertEqual(d["url"], "https://www.net-empregos.com/15978698/oferta/")


class ExpressoEmpregoReadsTheLiveListingNotTheFossilSitemap(unittest.TestCase):
    """`expressoemprego.py` — 2026-09-11. The host declares a sitemap whose
    1 513 advertisement URLs all carry a `lastmod` of 2019; the live route
    is the listing, 15 a page, with the site's own total in the page («1 917
    empregos para a sua pesquisa»), and a search routed by path segments read
    off the site's `main.js`. `?page=` is 1-based with `page=1` the first
    page again; the site's zero is a sentence, «Não foram encontradas
    Ofertas de Emprego para a sua pesquisa»; `/emprego` bare answers a 200
    «Oops» page with no row and no total.
    """

    @staticmethod
    def _row(ident, title, company, loc=None):
        return ('<div class="posRelative bgGray1 resultadosBox fOpenSansRegular ">'
                f'<h3 class="x"><a href="/emprego/slug-{ident}/{ident}" title="{title}">{title}</a></h3>'
                f'<h4 class="y">{company}</h4>'
                '<span class="px13 colorBlack">11.09.2026 <span class="colorBlue2 fontBold">|</span> '
                + (loc or "") + '</span> <span class="colorBlue2 fontBold">|</span> '
                f'<span class="colorGray8">Referência:</span> {ident}</span></div>')

    @staticmethod
    def _page(rows_html, total):
        head = (f'<div class="pull-left"><span class="px14"><b>{total}</b></span> '
                '<span class="px15">empregos para a sua pesquisa</span></div>') if total is not None else ""
        return "<html>" + head + rows_html + "x" * 40000 + "</html>"

    def _mod(self):
        spec = importlib.util.spec_from_file_location(
            "_expresso_t", os.path.join(SCRIPTS, "expressoemprego.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _run(self, fn, a):
        import contextlib
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                fn(a)
            except SystemExit as e:
                code = e.code
        return code, out.getvalue(), err.getvalue()

    def test_the_search_url_is_the_sites_routing_and_the_page_parameter_is_one_based(self):
        mod = self._mod()
        self.assertEqual(mod.search_url(), "https://expressoemprego.pt/ofertas-emprego")
        self.assertEqual(mod.search_url(page=1), "https://expressoemprego.pt/ofertas-emprego?page=2")
        self.assertEqual(mod.search_url(q="juristas"), "https://expressoemprego.pt/emprego/pesquisa/juristas/")
        self.assertEqual(mod.search_url(localizacao="lisboa"),
                         "https://expressoemprego.pt/emprego/pesquisa/query/lisboa/")
        self.assertEqual(mod.search_url(q="juristas", localizacao="lisboa"),
                         "https://expressoemprego.pt/emprego/pesquisa/juristas/lisboa/")
        self.assertEqual(mod.ad_url("2466610"), "https://expressoemprego.pt/emprego/oferta/2466610")
        src = open(os.path.join(SCRIPTS, "expressoemprego.py"), encoding="utf-8").read()
        self.assertNotIn("sitemap.xml\"", src.split("def get")[1], "the fossil sitemap must not be read")

    def test_rows_carry_the_listings_fields_and_the_sites_total_is_printed_beside_them(self):
        mod = self._mod()
        page = self._page(self._row(1, "Juristas", "ERSAR") + self._row(2, "Dev", "Acme", "Lisboa, Portugal"), "1 917")
        mod.get = lambda url: (200, page if "page=" not in url else self._page("", "1 917"))
        a = argparse.Namespace(q=None, localizacao=None, pages=2, limit=0)
        code, out, err = self._run(mod.cmd_search, a)
        self.assertIsNone(code, err)
        rows = [json.loads(l) for l in out.splitlines()]
        self.assertEqual([r["id"] for r in rows], ["1", "2"])
        self.assertEqual(rows[0]["ledger_id"], "expressoemprego:1")
        self.assertEqual(rows[0]["company"], "ERSAR")
        self.assertEqual(rows[0]["date"], "11.09.2026")
        self.assertIsNone(rows[0]["location"])
        self.assertEqual(rows[1]["location"], "Lisboa, Portugal")
        self.assertIn("2 emitted, 2 distinct over 1 page(s) of 15; the site states 1917", err)
        self.assertIn("page 1 carried no row — the end of the listing", err)

    def test_the_sites_zero_sentence_is_a_real_zero_and_the_oops_page_is_not(self):
        mod = self._mod()
        zero = "<html>Não foram encontradas Ofertas de Emprego para a sua pesquisa" + "x" * 80000 + "</html>"
        mod.get = lambda url: (200, zero)
        code, out, err = self._run(mod.cmd_search, argparse.Namespace(q="zzz", localizacao=None, pages=1, limit=0))
        self.assertIsNone(code, err)
        self.assertEqual(out, "")
        self.assertIn("a real zero, in the site's words", err)
        oops = "<html><title>Expresso Emprego</title>Oops, a página que procura não se encontra disponível" + "x" * 43000 + "</html>"
        mod.get = lambda url: (200, oops)
        code, out, err = self._run(mod.cmd_search, argparse.Namespace(q=None, localizacao=None, pages=1, limit=0))
        self.assertEqual(code, 6, err)
        self.assertIn("INDETERMINATE", err)
        self.assertIn("«Oops»", err)

    def test_rows_and_total_disagreeing_is_a_fault(self):
        mod = self._mod()
        mod.get = lambda url: (200, self._page("", "1 917"))
        code, out, err = self._run(mod.cmd_search, argparse.Namespace(q=None, localizacao=None, pages=1, limit=0))
        self.assertEqual(code, 6, err)
        self.assertIn("the two disagree", err)

    def test_the_ad_text_starts_inside_the_container_and_stops_before_the_similar_jobs(self):
        mod = self._mod()
        page = ('<html><title>Juristas | ERSAR</title><div class="wucAnuncioDet"><p>Descrição da Empresa</p>'
                '<p>Texto.</p></div><div>EMPREGOS SEMELHANTES</div><p>Outro</p></html>')
        mod.get = lambda url: (200, page)
        code, out, err = self._run(mod.cmd_ad, argparse.Namespace(id="2466610"))
        self.assertIsNone(code, err)
        d = json.loads(out)
        self.assertEqual(d["title"], "Juristas")
        self.assertEqual(d["text"], "Descrição da Empresa\nTexto.")
        self.assertNotIn("wucAnuncioDet", d["text"])


class ASitemapThatKeepsClosedAdvertisementsIsASupersetAndSaysSo(unittest.TestCase):
    r"""**`mynavi.py`, 2026-09-11.** Seven job files, 346 385 URLs, up to 53
    facet variants of one id; the home page states 掲載求人数 61 989 and the
    sitemap holds 77 504 distinct ids. So: the id is the key and variants are
    counted, `<lastmod>` is kept per id (the newest), `--since` narrows on it,
    the site's total is printed beside the count and named as REFUTING
    «sitemap = board» when it is smaller — never as «board states N — short».
    And a gzip stream decoded as text yields zero `<loc>` from 270 766
    characters: `get()` undoes the encoding by header or magic bytes.

    Mutated (`-B`, detached copy): variants no longer counted (dedupe by
    URL) → the variants case reddens; the newest `<lastmod>` not kept → the
    lastmod case reddens; the «SUPERSET» sentence replaced by «short» → the
    total case reddens; the magic-bytes gunzip removed → the gzip case
    reddens; `--since` filter dropped → the since case reddens.
    """

    def _mod(self):
        spec = importlib.util.spec_from_file_location(
            "_mynavi", os.path.join(SCRIPTS, "mynavi.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    INDEX = ('<sitemapindex><sitemap><loc>https://tenshoku.mynavi.jp/sitemap/sitemap_jobs_01.xml.gz</loc></sitemap>'
             '<sitemap><loc>https://tenshoku.mynavi.jp/sitemap/sitemap_company_01.xml.gz</loc></sitemap></sitemapindex>')

    @staticmethod
    def _file(entries):
        return "<urlset>" + "".join(
            f"<url><loc>https://tenshoku.mynavi.jp/jobinfo-{i}-{a}-{b}-1/</loc><lastmod>{d}T00:00:00+09:00</lastmod></url>"
            for i, a, b, d in entries) + "</urlset>"

    HOME = '<html><body><span>掲載求人数</span> <em>61,989</em> <span>件</span></body></html>'

    def _run(self, mod, bodies, **argv):
        import contextlib
        served = iter(bodies)
        mod.get = lambda url: (200, next(served))
        a = argparse.Namespace(files=None, since=None, limit=None, no_site_total=False)
        for k, v in argv.items():
            setattr(a, k, v)
        out, err = io.StringIO(), io.StringIO()
        code = None
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                mod.cmd_sitemap(a)
            except SystemExit as e:
                code = e.code
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        return code, rows, err.getvalue()

    # the newest <lastmod> of 407994 comes LAST, so «keep the first seen»
    # is a different answer from «keep the newest»
    ENTRIES = [("407994", 5, 3, "2026-06-01"), ("407994", 5, 2, "2026-09-01"),
               ("388227", 1, 1, "2025-01-15"), ("407994", 1, 46, "2026-09-08")]

    def test_the_id_is_the_key_and_variants_are_counted(self):
        mod = self._mod()
        code, rows, err = self._run(mod, [self.INDEX, self._file(self.ENTRIES), self.HOME])
        self.assertIsNone(code, err)
        self.assertEqual([r["id"] for r in rows], ["407994", "388227"])   # newest first
        self.assertEqual(rows[0]["variants"], 3)
        self.assertIn("4 <loc> in 1 of 1 job file(s) (4); 4 matched the advertisement shape and 0 did not; **2 distinct", err)

    def test_the_newest_lastmod_is_kept_per_id(self):
        mod = self._mod()
        _, rows, _ = self._run(mod, [self.INDEX, self._file(self.ENTRIES), self.HOME])
        self.assertEqual(rows[0]["lastmod"], "2026-09-08")

    def test_since_narrows_on_lastmod(self):
        mod = self._mod()
        _, rows, err = self._run(mod, [self.INDEX, self._file(self.ENTRIES), self.HOME], since="2026-01-01")
        self.assertEqual([r["id"] for r in rows], ["407994"])
        self.assertIn("--since 2026-01-01: 1 of 2", err)

    def test_the_site_total_is_named_as_refuting_not_as_a_shortfall(self):
        mod = self._mod()
        big = [(str(100000 + i), 1, 1, "2024-03-01") for i in range(70000)]
        _, _, err = self._run(mod, [self.INDEX, self._file(big), self.HOME])
        self.assertIn("site states 掲載求人数 61 989 件", err)
        self.assertIn("SUPERSET of the board", err)
        self.assertNotIn("short", err)

    def test_a_gzip_body_is_undone_by_its_magic_bytes(self):
        import gzip
        mod = self._mod()
        payload = gzip.compress(self._file(self.ENTRIES).encode("utf-8"))

        class R:
            headers = {"Content-Type": "application/x-gzip"}
            def read(self_):
                return payload
            def getcode(self_):
                return 200
            def __enter__(self_):
                return self_
            def __exit__(self_, *a):
                return False
        mod.gate = lambda url: None
        mod._PACE.wait = lambda: None
        # `mod.urllib` IS the shared module: patched for the whole process,
        # so restored on cleanup — the first version of this case left it
        # patched and two unrelated cases erred (the #185 harness's lesson).
        real = mod.urllib.request.urlopen
        self.addCleanup(setattr, mod.urllib.request, "urlopen", real)
        mod.urllib.request.urlopen = lambda *a, **k: R()
        code, body = mod.get("https://tenshoku.mynavi.jp/sitemap/sitemap_jobs_01.xml.gz")
        self.assertEqual(code, 200)
        self.assertEqual(body.count("<loc>"), 4)


