class ACountryPageSurvivesAWindowsConsole(unittest.TestCase):
    """**2026-09-12, after five red runs on `windows-latest`.** #232 put a
    U+2212 «−» into a line `country-boards.py` prints; Windows' default
    stdout is cp1252, which has no such character, and the tool died with
    `UnicodeEncodeError` on the first table — six tests red, on Windows only,
    green on three other platforms. The class is «a character outside cp1252
    on stdout», not that one sign: this runs the tool under a strict cp1252
    stdout on EVERY platform and asserts it exits 0 with its table. Mutated
    (`-B`, detached copy): the hyphen put back to U+2212 → exit 1, red."""

    def test_every_character_the_tool_prints_survives_cp1252(self):
        import subprocess
        base = ACountryPageIsGeneratedFromTheCardsAndNamesItsDenominators()
        d = base._boards()
        env = dict(os.environ, PYTHONIOENCODING="cp1252:strict")
        r = subprocess.run([sys.executable, "-B", base.TOOL, "XX", "--boards", d],
                           capture_output=True, env=env)
        self.assertEqual(r.returncode, 0, r.stderr.decode("utf-8", "replace")[-600:])
        out = r.stdout.decode("cp1252")
        self.assertIn("fait / faisable", out)
        self.assertIn("total - ", out)


class ASecondBranchOnAnotherPageIsComparedToTheUnit(unittest.TestCase):
    """**`greenjapan.py`, 2026-09-12.** The job sitemap has no `<lastmod>`
    and the root states no count; `/search` states «求人を28284件掲載» in its
    meta description, and the adapter prints that figure beside its distinct
    count — «equal», or «k short», never a bare count. Two page values are
    emitted AS PUBLISHED and flagged (`validThrough` = read date + 1 year,
    `currency: YEN`), not corrected. Mutated (`-B`, detached copy): the
    site-count regex broken → «no second source» reddens the equal case;
    «short» replaced by «equal» in the gap branch → the gap case reddens;
    the dedup removed → the equal case reddens (3 ≠ 2); `YEN` rewritten to
    `JPY` in `cmd_ad` → the as-published case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_greenjapan", os.path.join(SCRIPTS, "greenjapan.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    INDEX = "<sitemapindex><sitemap><loc>https://www.green-japan.com/sitemap/jobs.xml</loc></sitemap></sitemapindex>"
    JOBS = ("<urlset>" + "".join(f"<url><loc>https://www.green-japan.com/company/{c}/job/{i}</loc></url>"
                                 for c, i in ((2, 301424), (24, 256642), (2, 301424)))
            + "<url><loc>https://www.green-japan.com/company/9</loc></url></urlset>")

    def _search(self, n):
        return f'<html><head><meta content="求人を{n}件掲載。職種・エリア・年収など" name="Description"/></head></html>'

    def _sitemap(self, mod, search_html):
        import contextlib
        served = iter([(200, self.INDEX), (200, self.JOBS), (200, search_html)])
        mod.get = lambda url: next(served)
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_sitemap(argparse.Namespace(limit=None, no_site_total=False))
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        return rows, err.getvalue()

    def test_the_site_count_equal_to_the_distinct_count_is_said_equal(self):
        rows, err = self._sitemap(self._mod(), self._search(2))
        self.assertEqual([r["id"] for r in rows], ["301424", "256642"])
        self.assertIn("**2 distinct advertisement id(s)** across 2 companies. No <lastmod>", err)
        self.assertIn("2 emitted, site states 2 on https://www.green-japan.com/search — equal.", err)
        self.assertNotIn("no second source", err)

    def test_a_site_count_above_the_distinct_count_is_named_short_with_the_gap(self):
        rows, err = self._sitemap(self._mod(), self._search("28,284"))
        self.assertIn("2 emitted, site states 28 284 on https://www.green-japan.com/search — 28 282 short", err)
        self.assertNotIn("equal", err)

    def test_the_two_values_are_emitted_as_published_and_flagged(self):
        import contextlib
        mod = self._mod()
        ld = json.dumps({"@context": "https://schema.org/", "@type": "JobPosting", "title": "経理",
                         "datePosted": "2025-11-07", "validThrough": "2027-09-12",
                         "hiringOrganization": {"@type": "Organization", "name": "X株式会社"},
                         "jobLocation": {"@type": "Place", "address": {"@type": "PostalAddress", "addressLocality": "141-0032\r\n東京都"}},
                         "baseSalary": {"@type": "MonetaryAmount", "currency": "YEN",
                                        "value": {"@type": "QuantitativeValue", "minValue": 7000000, "maxValue": 9000000, "unitText": "YEAR"}},
                         "description": "《職務内容》"}, ensure_ascii=False)
        page = f'<html><head><script type="application/ld+json">{ld}</script></head><body></body></html>'
        mod.get = lambda url: (200, page)
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_ad(argparse.Namespace(url="https://www.green-japan.com/company/2/job/301424"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["valid_through"], d["salary_currency"], d["salary_min"], d["salary_unit"]),
                         ("2027-09-12", "YEN", 7000000, "YEAR"))
        self.assertEqual(d["address"], "141-0032\r\n東京都")
        self.assertIn("as published", err.getvalue())
        self.assertIn("YEN», not the ISO JPY; neither is corrected", err.getvalue())


class OneSitemapSevenTimesTheBoardAndTheListingStatesTheCount(unittest.TestCase):
    """**`cypruswork.py`, 2026-09-12 (#233 lot 3 → adapter).** One `urlset`
    of 10 708 `<loc>` holds 1 475 `/job/<id>/<slug>/` beside 8 874 `/company/`
    pages — counting the file would report the board 7× larger — and `/jobs/`
    states «1475 jobs» in its `<h1>`, printed beside the distinct count:
    «equal», or «k short», never a bare count. Every `<lastmod>` carries one
    value, the day of the read: measured in the run, not assumed, and named a
    rebuild stamp only when it IS one value. The country comes from the
    advertisement (`addressCountry: Cyprus` → `CY`, any other name as
    published) and the language from the script of the text (Greek → `el`).
    Mutated (`-B`, detached copy): the site-count regex broken → «no second
    source» reddens the equal case; «short» → «equal» in the gap branch → the
    gap case reddens; the dedup removed → 3 ≠ 2 reddens the equal case; the
    lastmod set replaced by a constant one-element set → the two-stamp case
    reddens; `COUNTRY` lookup bypassed → the `CY` case reddens; `GREEK_RE`
    made to match nothing → the `el` case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_cypruswork", os.path.join(SCRIPTS, "cypruswork.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _urlset(self, stamps=("2026-09-12", "2026-09-12", "2026-09-12")):
        ads = ((110094, "business-development-manager"), (108508, "γραμματέας-λευκωσία"), (110094, "business-development-manager"))
        return ("<urlset>" + "".join(
            f"<url><loc>https://www.cypruswork.com/job/{i}/{slug}/</loc><lastmod>{lm}</lastmod></url>"
            for (i, slug), lm in zip(ads, stamps))
            + "<url><loc>https://www.cypruswork.com/company/9/acme/</loc><lastmod>2026-09-12</lastmod></url>"
            + "<url><loc>https://www.cypruswork.com/jobs/limassol/</loc><lastmod>2026-09-12</lastmod></url></urlset>")

    def _listing(self, n):
        return f'<html><body><h1 class="search-results__title"> {n} jobs </h1></body></html>'

    def _sitemap(self, mod, urlset, listing):
        import contextlib
        served = iter([(200, urlset), (200, listing)])
        mod.get = lambda url: next(served)
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_sitemap(argparse.Namespace(limit=None, no_site_total=False))
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        return rows, err.getvalue()

    def test_the_site_count_equal_to_the_distinct_count_is_said_equal(self):
        rows, err = self._sitemap(self._mod(), self._urlset(), self._listing(2))
        self.assertEqual([r["id"] for r in rows], ["110094", "108508"])
        self.assertIn("5 <loc> in the sitemap; 3 matched the advertisement shape and 2 did not", err)
        self.assertIn("**2 distinct advertisement id(s)**. One <lastmod> value on every advertisement entry (2026-09-12) — a rebuild stamp", err)
        self.assertIn("2 emitted, site states 2 on https://www.cypruswork.com/jobs/ — equal.", err)
        self.assertNotIn("no second source", err)

    def test_a_site_count_above_the_distinct_count_is_named_short_with_the_gap(self):
        rows, err = self._sitemap(self._mod(), self._urlset(), self._listing("1,475"))
        self.assertIn("2 emitted, site states 1 475 on https://www.cypruswork.com/jobs/ — 1 473 short", err)
        self.assertNotIn("equal", err)

    def test_two_lastmod_values_are_not_called_a_rebuild_stamp(self):
        rows, err = self._sitemap(self._mod(), self._urlset(("2026-09-12", "2026-08-01", "2026-09-12")), self._listing(2))
        self.assertIn("2 distinct <lastmod> values on the advertisement entries", err)
        self.assertNotIn("rebuild stamp", err)

    def _ad(self, mod, ld, url="https://www.cypruswork.com/job/108508/γραμματέας-λευκωσία/"):
        import contextlib
        page = f'<html><head><script type="application/ld+json">{json.dumps(ld, ensure_ascii=False)}</script></head><body></body></html>'
        mod.get = lambda u: (200, page)
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_ad(argparse.Namespace(url=url))
        return json.loads(out.getvalue())

    def _ld(self, **over):
        d = {"@context": "https://schema.org", "@type": "JobPosting", "title": "Γραμματέας - Λευκωσία",
             "datePosted": "2026-07-14T11:42:16+03:00", "validThrough": "2026-09-12T11:42:16+03:00",
             "employmentType": ["FULL_TIME"], "occupationalCategory": ["Legal", "Secretarial"],
             "hiringOrganization": {"@type": "Organization", "name": "Katsaros LLC", "sameAs": "https://k.example"},
             "jobLocation": {"@type": "Place", "address": {"addressLocality": "Nicosia", "addressRegion": "Nicosia", "addressCountry": "Cyprus"}},
             "baseSalary": {"@type": "MonetaryAmount", "currency": "EUR",
                            "value": {"@type": "QuantitativeValue", "minValue": "", "maxValue": "", "unitText": "YEAR"}},
             "description": "<p>Η Δικηγορική Εταιρεία ζητά γραμματέα.</p>"}
        d.update(over)
        return d

    def test_cyprus_by_name_becomes_the_iso_code_and_greek_script_is_el(self):
        d = self._ad(self._mod(), self._ld())
        self.assertEqual((d["country"], d["language"], d["city"], d["employment_type"]), ("CY", "el", "Nicosia", "FULL_TIME"))
        self.assertEqual((d["salary_currency"], d["salary_min"], d["salary_unit"]), ("EUR", None, "YEAR"))
        self.assertEqual(d["categories"], ["Legal", "Secretarial"])
        self.assertEqual(d["employer_site"], "https://k.example")

    def test_another_country_name_is_emitted_as_published_and_latin_text_is_en(self):
        d = self._ad(self._mod(), self._ld(title="Accountant", description="<p>Books and ledgers.</p>",
                                           jobLocation={"@type": "Place", "address": {"addressLocality": "Athens", "addressCountry": "Greece"}}))
        self.assertEqual((d["country"], d["language"], d["city"], d["region"]), ("Greece", "en", "Athens", None))


class ARestCollectionAndAJobSitemapAreTwoEnumerationsOfOneStore(unittest.TestCase):
    """**`albaniajobs.py`, 2026-09-12 (#233 lot 4 → adapter).** A WordPress
    board: the REST collection `job-listings` is the route (post id, link,
    title, dates, meta, term ids), the AIOSEO `job_listing-sitemap.xml` the
    second document — «n emitted, sitemap lists N — equal», or «k short».
    The URL carries no id (a leading `13` on most entries); the key is the
    post id, and `ad` reads it back from the `JobPosting`'s `identifier.value`
    (`…?post_type=job_listing&p=<id>`). Term ids become names through the
    three taxonomy endpoints, ids when `--no-terms`. WordPress' `date_gmt`
    carries no zone marker and is emitted with a `Z`. Mutated (`-B`, detached
    copy): the dedup removed → 3 ≠ 2 reddens the equal case; «short» →
    «equal» in the gap branch → the gap case reddens; the `/job/` filter on
    the sitemap dropped → the equal case reddens (a company URL counted);
    `named()` made to return ids → the names case reddens; `POST_ID_RE`
    broken → the ad case reddens (`id` null); the `Z` suffix dropped → the
    date case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_albaniajobs", os.path.join(SCRIPTS, "albaniajobs.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _item(self, i, slug, region=181, typ=13):
        return {"id": i, "link": f"https://albaniajobs.al/job/13-{slug}/", "date": "2026-08-11T14:48:06",
                "date_gmt": "2026-08-11T12:48:06", "modified_gmt": "2026-08-17T12:23:25", "status": "publish",
                "title": {"rendered": slug.replace("-", " ").title()}, "excerpt": {"rendered": "<p>Kërkojmë&hellip;</p>"},
                "meta": {"_company_name": "", "_job_salary": "", "_remote_position": "", "_filled": ""},
                "job_listing_region": [region], "job-types": [typ], "job-categories": []}

    def _served(self, items, sitemap_urls, terms=True):
        pages = [json.dumps(items[:100]), json.dumps(items[100:]) if len(items) > 100 else None]
        T = {"job_listing_region": json.dumps([{"id": 181, "name": "Tiran&euml;", "count": 91}]),
             "job-types": json.dumps([{"id": 13, "name": "Kohë e Plotë", "count": 118}]),
             "job-categories": json.dumps([])}
        sm = "<urlset>" + "".join(f"<url><loc><![CDATA[{u}]]></loc><lastmod>2026-08-17</lastmod></url>" for u in sitemap_urls) + "</urlset>"

        def get(url):
            if "job-listings" in url:
                n = int(url.rsplit("page=", 1)[1])
                return (200, pages[n - 1]) if n <= len(pages) and pages[n - 1] is not None else (400, "")
            for tax, body in T.items():
                if f"/{tax}?" in url:
                    return 200, body
            if "sitemap" in url:
                return 200, sm
            raise AssertionError(url)
        return get

    def _list(self, mod, get, **opts):
        import contextlib
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(argparse.Namespace(limit=None, no_terms=opts.get("no_terms", False), no_site_total=False))
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        return rows, err.getvalue()

    ITEMS = None

    def setUp(self):
        self.items = [self._item(3248, "truck-driver-poland"), self._item(3227, "marketing-specialist"), self._item(3248, "truck-driver-poland")]
        self.urls = ["https://albaniajobs.al/job/13-truck-driver-poland/", "https://albaniajobs.al/job/13-marketing-specialist/",
                     "https://albaniajobs.al/company/acme/"]

    def test_the_sitemap_count_equal_to_the_distinct_count_is_said_equal_and_terms_are_names(self):
        rows, err = self._list(self._mod(), self._served(self.items, self.urls))
        self.assertEqual([r["id"] for r in rows], ["3248", "3227"])
        self.assertEqual((rows[0]["regions"], rows[0]["types"], rows[0]["posted"]), (["Tiranë"], ["Kohë e Plotë"], "2026-08-11T12:48:06Z"))
        self.assertIn("**2 distinct post id(s)**", err)
        self.assertIn("2 emitted, sitemap lists 2 — equal.", err)

    def test_a_sitemap_longer_than_the_collection_is_named_short_with_the_gap(self):
        rows, err = self._list(self._mod(), self._served(self.items, self.urls + ["https://albaniajobs.al/job/13-x/", "https://albaniajobs.al/job/13-y/"]))
        self.assertIn("2 emitted, sitemap lists 4 — 2 short", err)
        self.assertNotIn("equal", err)

    def test_no_terms_emits_the_ids(self):
        rows, err = self._list(self._mod(), self._served(self.items, self.urls), no_terms=True)
        self.assertEqual((rows[0]["regions"], rows[0]["types"]), ([181], [13]))
        self.assertIn("Term ids emitted, not names.", err)

    def test_the_post_id_is_read_back_from_the_identifier_on_the_page(self):
        import contextlib
        mod = self._mod()
        ld = json.dumps({"@context": "http://schema.org/", "@type": "JobPosting", "title": "Account Manager",
                         "datePosted": "2025-12-22T08:19:08+01:00", "description": "&lt;p&gt;Remote&lt;/p&gt;",
                         "hiringOrganization": {"@type": "Organization", "name": "Group Getaways"},
                         "identifier": {"@type": "PropertyValue", "name": "Group Getaways",
                                        "value": "https://albaniajobs.al/?post_type=job_listing&amp;#038;p=2993"},
                         "jobLocation": {"@type": "Place", "address": "Shqipëri"}, "jobLocationType": "TELECOMMUTE", "directApply": True})
        mod.get = lambda u: (200, f'<html><head><script type="application/ld+json">{ld}</script></head><body></body></html>')
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_ad(argparse.Namespace(url="https://albaniajobs.al/job/544-account-manager/"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["ledger_id"], d["employer"], d["place"], d["remote"]), ("2993", "albaniajobs:2993", "Group Getaways", "Shqipëri", True))
        self.assertEqual(d["description"], "Remote")


class TheActiveSitemapsAreTheRouteAndTheHandWrittenPathsAreNeverRead(unittest.TestCase):
    """**`founditgulf.py`, 2026-09-12 (#233 lot 4 → adapter).** The rules
    carry a hand-written group naming ClaudeBot with `Disallow: /jobs/`,
    `/search/`; Claude-User is not in it — and the adapter still never reads
    those two paths (`gate()` exits 7 on them before the rules are asked).
    The index's `active-jobs-sitemap<n>.xml.gz` files are the enumeration
    (58 930 distinct ids on 2026-09-12; the `expired-jobs` files are refused
    to `*` and never matched), `todays-jobs-sitemap.xml` the second document
    — «consistent» when every id of today's is among the active, «NOT among»
    with the count when not — and the root's «Over 800,000+ jobs» is printed
    as a slogan, never compared. Dates arrive as `DD-MM-YYYY` and are emitted
    as published beside their ISO; the country is the advertisement's own
    `addressCountry`. Mutated (`-B`, detached copy): `NEVER` emptied → the
    gate case reddens; `ACTIVE_RE` widened to `-sitemap` → an expired file is
    asked for and the equal case errors; the dedup removed → 3 ≠ 2; `missing`
    forced empty → the disagreement case reddens; `iso()` made identity → the
    date case reddens; `SLOGAN_RE` broken → the slogan case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_founditgulf", os.path.join(SCRIPTS, "founditgulf.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    INDEX = ("<sitemapindex>" + "".join(f"<sitemap><loc>https://www.founditgulf.com/xmlsitemap/{n}</loc></sitemap>" for n in
             ("active-jobs-sitemap0.xml.gz", "jobs-by-skills-sitemap0.xml.gz", "active-jobs-sitemap1.xml.gz", "expired-jobs-sitemap0.xml.gz"))
             + "</sitemapindex>")

    @staticmethod
    def _urlset(ids):
        return "<urlset>" + "".join(f"<url><loc>https://www.founditgulf.com/job/nurse-x-{i}</loc><lastmod>2026-09-11T13:06:53+02:00</lastmod></url>" for i in ids) + "</urlset>"

    def _served(self, today_ids, slogan="Over 800,000+ jobs to explore"):
        def get(url, binary=False):
            if url.endswith("sitemap-index.xml"):
                return 200, self.INDEX
            if "active-jobs-sitemap0" in url:
                return 200, self._urlset([18080752, 18080754])
            if "active-jobs-sitemap1" in url:
                return 200, self._urlset([18080752]) + "<urlset><url><loc>https://www.founditgulf.com/search/x</loc></url></urlset>"
            if "todays-jobs" in url:
                return 200, self._urlset(today_ids)
            if url == "https://www.founditgulf.com/":
                return 200, f"<html><body><h2>{slogan}</h2></body></html>"
            raise AssertionError("asked for " + url)
        return get

    def _sitemap(self, mod, get):
        import contextlib
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_sitemap(argparse.Namespace(limit=None, no_site_total=False))
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        return rows, err.getvalue()

    def test_two_active_files_are_deduplicated_and_todays_is_consistent(self):
        rows, err = self._sitemap(self._mod(), self._served([18080754]))
        self.assertEqual([r["id"] for r in rows], ["18080752", "18080754"])
        self.assertIn("2 active-jobs file(s) of 4 index children; 4 <loc>, 3 of the advertisement shape, 1 not; **2 distinct advertisement id(s)**", err)
        self.assertIn("today's sitemap lists 1, 1 of them among the 2 active — consistent.", err)
        self.assertIn("the root says «800,000+ jobs» — a slogan, not this board's count", err)

    def test_an_id_in_todays_and_not_among_the_active_is_said_so_with_the_count(self):
        rows, err = self._sitemap(self._mod(), self._served([18080754, 99999999]))
        self.assertIn("today's sitemap lists 2 and **1 of them are NOT among the 2 active**", err)
        self.assertNotIn("consistent", err)

    def test_the_hand_written_paths_are_refused_by_the_adapter_before_the_rules(self):
        import contextlib
        mod = self._mod()
        for u in ("https://www.founditgulf.com/jobs/", "https://www.founditgulf.com/search/it-jobs"):
            with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
                mod.gate(u)
            self.assertEqual(cm.exception.code, 7, u)

    def test_the_dates_are_emitted_as_published_and_as_iso_and_the_country_is_the_advertisements(self):
        import contextlib
        mod = self._mod()
        ld = json.dumps({"@context": "https://schema.org", "@type": "JobPosting", "title": "Technical Sales Engineer",
                         "identifier": {"@type": "PropertyValue", "name": "ATEC", "value": 66495664},
                         "datePosted": "10-09-2026", "validThrough": "25-10-2026", "employmentType": "Full time",
                         "hiringOrganization": {"@type": "Organization", "name": "ATEC", "sameAs": "ATEC"},
                         "jobLocation": {"@type": "Place", "address": {"@type": "PostalAddress", "addressLocality": "Egypt", "addressRegion": "Egypt", "addressCountry": "EG"}},
                         "experienceRequirements": {"@type": "OccupationalExperienceRequirements", "monthsOfExperience": 24},
                         "occupationalCategory": "Sales Engineering", "industry": ["Other"], "skills": ["water pumps"], "directApply": False,
                         "description": "Job Description<br/>Sales."})
        mod.get = lambda u, binary=False: (200, f'<html><head><script type="application/ld+json">{ld}</script></head><body></body></html>')
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_ad(argparse.Namespace(url="https://www.founditgulf.com/job/technical-sales-engineer-atec-egypt-66495664"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["country"], d["id"], d["posted"], d["posted_as_published"], d["valid_through"]), ("EG", "66495664", "2026-09-10", "10-09-2026", "2026-10-25"))
        self.assertEqual((d["months_of_experience"], d["industries"], d["skills"], d["employer"]), (24, ["Other"], ["water pumps"], "ATEC"))

    def test_the_philippine_host_is_a_second_host_with_its_own_key_and_the_same_never_read_paths(self):
        """**2026-09-13, #233 lot 8.** `www.foundit.com.ph` publishes the same
        stack and the same hand-written refusal; `--host` chooses it, the rows
        are keyed `foundit-ph:`, the slogan «100,000+ Jobs in Philippines» is
        named as one, and `gate()` exits 7 on its `/jobs/` too. Mutated: the
        `HOSTS` gate narrowed to the Gulf host → this case reddens."""
        import contextlib
        mod = self._mod()
        PH = "https://www.foundit.com.ph"
        index = "<sitemapindex><sitemap><loc>" + PH + "/xmlsitemap/active-jobs-sitemap0.xml.gz</loc></sitemap></sitemapindex>"
        def get(url, binary=False):
            if url == PH + "/xmlsitemap/sitemap-index.xml":
                return 200, index
            if "active-jobs-sitemap0" in url:
                return 200, f"<urlset><url><loc>{PH}/job/nurse-x-501</loc></url><url><loc>{PH}/job/nurse-y-502</loc></url></urlset>"
            if url == PH + "/xmlsitemap/todays-jobs-sitemap.xml":
                return 200, f"<urlset><url><loc>{PH}/job/nurse-x-501</loc></url></urlset>"
            if url == PH + "/":
                return 200, "<html><title>100,000+ Jobs in Philippines: Apply for September 2026 Hiring</title></html>"
            raise AssertionError("asked for " + url)
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_sitemap(argparse.Namespace(host="www.foundit.com.ph", limit=None, no_site_total=False))
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        self.assertEqual([(r["source"], r["ledger_id"]) for r in rows], [("foundit-ph", "foundit-ph:501"), ("foundit-ph", "foundit-ph:502")])
        self.assertIn("today's sitemap lists 1, 1 of them among the 2 active — consistent.", err.getvalue())
        self.assertIn("the root says «100,000+ jobs» — a slogan", err.getvalue())
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.gate(PH + "/jobs/")
        self.assertEqual(cm.exception.code, 7)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.gate(PH + "/search/it-jobs")
        self.assertEqual(cm.exception.code, 7)


class AHiddenFlagSplitsOneStoreIntoOwnAndMediated(unittest.TestCase):
    """**`cvonline.py`, 2026-09-12 (#233 lot 5 → adapter).** `cv.ee`'s search
    service counts 1 426 by default and 3 853 with `showHidden=true` — the
    flag the page's own bundle adds; the 2 427 hidden ones are Töötukassa's
    mediated advertisements, none in the job sitemap, which lists exactly the
    own 1 426. The adapter emits the visible set with `mediated_by` set on
    those rows (`--own` for the default set), resolves town / country ids
    through the `locations` table the search page inlines, prints «own N,
    sitemap lists M — equal / k short» and «total T = own N + hidden H», and
    on a vacancy page reads the state's `details` (text, file, url, styled)
    and never its `contacts`. `cv.lv` and `cvonline.lt` — same stack — answer
    a 403 today and are named on it. Mutated (`-B`, detached copy):
    `showHidden` dropped from the query → the visible case reddens (1 426);
    `MEDIATED` misspelt → the mediated case reddens; the dedup removed → 3 ≠
    2; «short» → «equal» → the gap case reddens; the countries lookup
    bypassed → the FI case reddens; `contacts` emitted → the ad case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_cvonline", os.path.join(SCRIPTS, "cvonline.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    LOC = {"countries": {"1": {"id": 1, "iso": "EE", "name": "Estonia"}, "157": {"id": 157, "iso": "FI", "name": "Finland"}},
           "counties": {"67": {"id": 67, "countryId": 1, "name": "Harjumaa"}}, "towns": [{"id": 312, "countyId": 67, "countryId": 1, "name": "Tallinn"}]}

    def _v(self, i, title, emp="Acme OÜ", country=1):
        return {"id": i, "positionTitle": title, "employerName": emp, "publishDate": "2026-09-11T14:55:30.652+00:00",
                "expirationDate": "2026-09-20T23:59:59.999+00:00", "salaryFrom": 1500, "salaryTo": None, "hourlySalary": False,
                "townId": 312, "countyId": 67, "countryId": country, "remoteWork": False, "workTimes": ["FULL_TIME"],
                "categories": ["SALES"], "quickApply": False, "positionContent": "Müük."}

    def _served(self, own, hidden, sitemap_ids):
        page = ('<html><body><script id="__NEXT_DATA__" type="application/json">'
                + json.dumps({"props": {"pageProps": {"initialReduxState": {"locations": self.LOC}}}}) + "</script></body></html>")
        sm = "<urlset>" + "".join(f"<url><loc>https://www.cv.ee/et/vacancy/{i}/x/y</loc></url>" for i in sitemap_ids) + "</urlset>"

        def get(url):
            if url.endswith("/et/search"):
                return 200, page
            if "jobs-sitemap" in url:
                return 200, sm
            if "vacancy-search-service/search?" in url:
                import urllib.parse
                q = dict(urllib.parse.parse_qsl(url.split("?", 1)[1]))
                rows = hidden if q.get("showHidden") == "true" else own
                off, lim = int(q["offset"]), int(q["limit"])
                # the stub states the DISTINCT count, as the service does; the duplicate row is the page repeating itself
                return 200, json.dumps({"total": len({r["id"] for r in rows}), "vacancies": rows[off:off + lim]})
            raise AssertionError(url)
        return get

    def _search(self, mod, get, own=False):
        import contextlib
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(argparse.Namespace(host="www.cv.ee", own=own, limit=None, no_site_total=False))
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue()

    def setUp(self):
        self.own = [self._v(1, "Data Engineer"), self._v(2, "Insinööri", country=157), self._v(1, "Data Engineer")]
        self.hidden = self.own + [self._v(3, "Müügijuht", emp="Töötukassa vahendatud pakkumised")]

    def test_the_visible_search_carries_the_hidden_flag_and_marks_the_mediated_rows(self):
        rows, err = self._search(self._mod(), self._served(self.own, self.hidden, [1, 2]))
        self.assertEqual([(r["id"], r["mediated_by"], r["country"], r["city"]) for r in rows],
                         [("1", None, "EE", "Tallinn"), ("2", None, "FI", "Tallinn"), ("3", "Töötukassa", "EE", "Tallinn")])
        self.assertIn("**3 distinct id(s)** of the 3 the service states for the visible (showHidden) search; 1 mediated by Töötukassa.", err)
        self.assertIn("own 2, sitemap lists 2 — equal.", err)
        self.assertIn("total 3 = own 2 + hidden 1", err)

    def test_the_own_search_is_the_default_set_and_a_longer_sitemap_is_named_short(self):
        rows, err = self._search(self._mod(), self._served(self.own, self.hidden, [1, 2, 9, 10]), own=True)
        self.assertEqual([r["id"] for r in rows], ["1", "2"])
        self.assertIn("own 2, sitemap lists 4 — 2 short.", err)
        self.assertNotIn("— equal.", err.split("total")[0])

    def test_the_ad_reads_the_details_and_never_the_contacts(self):
        import contextlib
        mod = self._mod()
        v = {"id": "1656067", "position": "Müügijuht", "employerName": "Töötukassa vahendatud pakkumised", "firstPublishDate": "2026-09-12",
             "dateModified": "2026-09-12T03:03:31Z", "status": "PUBLISHED", "languageIso": "et",
             "settings": {"dateStart": "2026-09-12", "dateTo": "2026-09-30", "categories": ["MARKETING_ADVERTISING"], "applyingUrl": None},
             "details": {"fileDetails": None, "standardDetails": [{"id": 1, "title": "Tööandja nimi", "content": "EstoraGroup OÜ"}], "urlDetails": None, "styleDetails": None},
             "highlights": {"location": {"townId": 312, "countyId": 67, "countryId": 1}, "salaryFrom": 1200, "salaryTo": None, "ratePer": "MONTHLY", "remoteWorkType": "ON_SITE"},
             "employer": {"about": "Ajutise tööjõu rent", "webpageUrl": None},
             "contacts": {"firstName": "X", "lastName": "Y", "email": "someone@example.ee", "phone": "+372 5000 0000"}}
        page = ('<html><body><script id="__NEXT_DATA__" type="application/json">'
                + json.dumps({"props": {"pageProps": {"vacancy": {"1656067": v}, "locations": self.LOC}}}) + "</script></body></html>")
        mod.get = lambda u: (200, page)
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_ad(argparse.Namespace(url="https://www.cv.ee/et/vacancy/1656067/x/y"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["mediated_by"], d["city"], d["details_kind"], d["salary_min"], d["description"]),
                         ("1656067", "Töötukassa", "Tallinn", "text", 1200, "Tööandja nimi: EstoraGroup OÜ"))
        self.assertNotIn("example.ee", out.getvalue())
        self.assertNotIn("5000 0000", out.getvalue())


class APagedFrontPageSumsToTheStatedCountAndTheSitemapIsNeverAsked(unittest.TestCase):
    """**`cvbankas.py`, 2026-09-12 (#233 lot 6 → adapter).** The front page is
    the listing (142 VIP on page 1, then 50 a page to page 181, 21 on the
    last — 9 113, exactly the «Rodoma 9 113 skelbimų» every page states). The
    adapter walks the pages, dedups on `job_ad_<id>`, reads the stated figure
    and prints «n emitted, site states N — equal / k short»; a bounded walk
    (`--pages`) says so and is not compared. `/sitemap.xml` answers a
    challenge and is never asked for (`gate()` exits 7 on it). The page's
    JobPosting is microdata; its salary digits are interleaved with U+200C
    and stripped; net/gross comes from the block's class, not the language
    (a page is Lithuanian or English per advertisement). Mutated (`-B`,
    detached copy): `NEVER` emptied → the gate case reddens; the dedup
    removed → 4 ≠ 3; «short» → «equal» → the gap case reddens; `STATED_RE`
    broken → «no second source» reddens the equal case; the U+200C strip
    removed → the ad salary reddens; the `salary_bl_net` test inverted →
    the net case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_cvbankas", os.path.join(SCRIPTS, "cvbankas.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _card(i, title, emp, sal="1300-1500", net=True, vip=False):
        cls = "salary_bl_net" if net else "salary_bl_gross"
        return (f'<article class="list_article{" jobadlist_article_vip" if vip else ""}" id="job_ad_{i}">'
                + ('<div class="jobadlist_article_vip_icon">VIP</div>' if vip else "")
                + f'<a class="list_a" href="https://www.cvbankas.lt/x-{i}/1-{i}"><h3 class="list_h3" lang="lt">{title}</h3>'
                f'<span class="heading_secondary"> <span class="dib">{emp}</span> </span>'
                f'<div class="list_cell"><span class="salary_c"><span class="salary_bl {cls}"><span class="salary_amount">{sal}</span> <span class="salary_period">€/mėn.</span></span></span> </div>'
                f'<span class="list_city">Kaune</span><span class="txt_list_2">prieš 1 d.</span></a></article>')

    def _page(self, cards, stated=3, last=2):
        return (f"<html><body><p>Rodoma {stated} skelbimų</p>" + "".join(cards)
                + "".join(f'<a href="https://www.cvbankas.lt/?page={p}">{p}</a>' for p in range(2, last + 1)) + "</body></html>")

    def _served(self, pages):
        def get(url):
            if url == "https://www.cvbankas.lt/":
                return 200, pages[0]
            m = re.search(r"\?page=(\d+)$", url)
            if m and int(m.group(1)) <= len(pages):
                return 200, pages[int(m.group(1)) - 1]
            raise AssertionError(url)
        return get

    def _list(self, mod, get, **kw):
        import contextlib
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(argparse.Namespace(pages=kw.get("pages"), limit=None, no_site_total=False))
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue()

    def test_the_pages_are_walked_deduplicated_and_compared_to_the_stated_count(self):
        p1 = self._page([self._card(1, "A", "UAB X", vip=True), self._card(2, "B", "UAB Y", sal="nuo 1850", net=False)], stated=3, last=2)
        p2 = self._page([self._card(1, "A", "UAB X", vip=True), self._card(3, "C", "UAB Z")], stated=3, last=2)
        rows, err = self._list(self._mod(), self._served([p1, p2]))
        self.assertEqual([(r["id"], r["vip"], r["salary_min"], r["salary_max"], r["salary_net"]) for r in rows],
                         [("1", True, 1300, 1500, True), ("2", False, 1850, None, False), ("3", False, 1300, 1500, True)])
        self.assertIn("2 page(s) read of 2; **3 distinct advertisement id(s)**.", err)
        self.assertIn("3 emitted, site states 3 — equal.", err)

    def test_a_stated_count_above_the_emitted_is_named_short_and_a_bounded_walk_is_not_compared(self):
        p1 = self._page([self._card(1, "A", "UAB X")], stated=9113, last=3)
        p2 = self._page([self._card(2, "B", "UAB Y")], stated=9113, last=3)
        p3 = self._page([], stated=9113, last=3)
        rows, err = self._list(self._mod(), self._served([p1, p2, p3]))
        self.assertIn("2 emitted, site states 9 113 — 9 111 short.", err)
        rows, err = self._list(self._mod(), self._served([p1, p2, p3]), pages=1)
        self.assertIn("the walk stopped at page 1, so the count is a lower bound", err)
        self.assertIn("site states 9 113; 1 emitted from a bounded walk — not compared.", err)

    def test_the_sitemap_is_refused_by_the_adapter_before_the_rules(self):
        import contextlib
        mod = self._mod()
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.gate("https://www.cvbankas.lt/sitemap.xml")
        self.assertEqual(cm.exception.code, 7)

    def test_the_ad_strips_the_zero_width_joiners_and_reads_net_from_the_class(self):
        import contextlib
        mod = self._mod()
        page = ('<html><body><div itemscope itemtype="http://schema.org/JobPosting"><h1 class="heading1" itemprop="title">DARBŲ VADOVO ASISTENTAS</h1>'
                '<div class="salary_component"><span><span><div class="data_tag_component_body salary_bl_net"><div class="label_component"><div class="label_component_body">'
                '<span class="data_tag_component_salary_amount">2&#8204;2&#8204;0&#8204;0&#8204;-3&#8204;0&#8204;0&#8204;0&#8204;</span> €/mon. net </div></div></div></span></span></div>'
                '<div class="job_ad_work_types"><span><span><div class="data_tag_component_body"><div class="label_component"><div class="label_component_body"> Visa darbo diena </div></div></div></span></span></div>'
                '<div itemprop="hiringOrganization" itemscope itemtype="http://schema.org/Organization"><meta itemprop="name" content="AGDB solutions APS" /></div>'
                '<div itemprop="jobLocation" itemscope id="jobad_location"><span itemprop="address" itemscope><a href="/x"><span itemprop="addressLocality">Užsienis</span></a>: <a href="/y">Danija</a> </span> - AGDB</div>'
                '<meta itemprop="datePosted" content="2026-09-11" /><time itemprop="validThrough" datetime="2026-10-11 23:59:59">Liko 29 dienos</time>'
                '<section><div itemprop="description">Ieškome asistento.</div></section>'
                '<section><h2>Reikalavimai darbuotojui</h2><div class="jobad_txt">Patirtis.<br />Kalba.</div></section>'
                '<a href="mailto:someone@example.lt">x</a></div></body></html>')
        mod.get = lambda u: (200, page)
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_ad(argparse.Namespace(url="https://www.cvbankas.lt/darbu-vadovo-asistentas-uzsienyje/1-14112398"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["title"], d["employer"], d["location"], d["posted"], d["valid_through"], d["work_type"]),
                         ("14112398", "DARBŲ VADOVO ASISTENTAS", "AGDB solutions APS", "Užsienis : Danija", "2026-09-11", "2026-10-11", "Visa darbo diena"))
        self.assertEqual((d["salary_min"], d["salary_max"], d["salary_period"], d["salary_net"]), (2200, 3000, "MONTH", True))
        self.assertEqual(d["sections"], {"Reikalavimai darbuotojui": "Patirtis.\nKalba."})
        self.assertNotIn("example.lt", out.getvalue())
        self.assertIn("interleaved with U+200C", err.getvalue())


class AMeasuredBrowserRouteIsDeclaredNotGuessedFromProse(unittest.TestCase):
    """**#264, 2026-09-12.** A browser route measured to a count is a coverage
    (decision of 2026-09-08) — and until today the pilot could only read it
    in prose («from a connected browser tab»), a pattern to test both ways.
    Now a card DECLARES it: `<!-- route: browser · <count> · YYYY-MM-DD -->`,
    or `route: none · <why>` when the route leads to nothing. This guard
    reddens in both directions, over `shared/boards/` itself: (a) a card
    whose `content:` says the reading came from a browser and carries no
    `route:` line; (b) a `route: browser` line without a count above zero,
    or with a kind other than browser / http / none. And
    `bin/country-boards.py` counts a `route: browser` card as «fait» with
    «navigateur» in the access column, a `route: none` card as «non faisable» since #404.
    Population asserted: at least 12 cards declare `route: browser` on
    2026-09-12. Mutated (`-B`, detached copy): the guard's prose pattern
    emptied → the undeclared fixture passes (the negative reddens); the count
    check dropped → a zero-count fixture passes (reddens); in the tool,
    `route_of` returning None → the browser fixture is no longer «fait»
    (reddens); the «navigateur» access branch removed → the access column
    of the browser fixture reddens. *A fifth, tried and recorded: the
    «none» branch of `route_of` removed leaves everything green — the branch
    is explicit, not load-bearing: a `none` line carries no digits and
    already fails the browser test.*"""

    BROWSER_PROSE = re.compile(r"browser tab|in a browser|from a (?:connected )?browser|a real browser, same path", re.I)
    ROUTE = re.compile(r"^\s*(browser|http|none)\s*(?:·\s*(.*?))?\s*$")

    @staticmethod
    def _headers(text):
        return {m.group(1): m.group(2) for m in re.finditer(r"^<!--\s*([a-z-]+):\s*(.*?)\s*-->\s*$", text, re.M)}

    def _complaints(self, name, text):
        """The guard, as a function of one card — so that fixtures exercise it
        in both directions and the walk over the repository uses the same code."""
        h = self._headers(text)
        bad = []
        content = h.get("content", "")
        if self.BROWSER_PROSE.search(content) and "route" not in h:
            bad.append(f"{name}: `content:` says the reading came from a browser and no `route:` line declares it")
        if "route" in h:
            m = self.ROUTE.match(h["route"])
            if not m:
                bad.append(f"{name}: `route:` is not browser / http / none — {h['route'][:60]!r}")
            elif m.group(1) == "browser":
                digits = re.sub(r"\D", "", (m.group(2) or "").split("·")[0])
                if not digits or int(digits) <= 0:
                    bad.append(f"{name}: `route: browser` without a count above zero — a route to nothing is not a coverage")
                if not re.search(r"20\d\d-\d\d-\d\d", m.group(2) or ""):
                    bad.append(f"{name}: `route: browser` without a date")
        return bad

    def test_the_repository_declares_every_browser_reading_and_no_route_to_nothing(self):
        d = pathlib.Path(SCRIPTS).parent.parent.parent / "shared" / "boards"
        bad, declared = [], 0
        for card in sorted(d.glob("*.md")):
            if card.name == "README.md":
                continue
            text = card.read_text(encoding="utf-8")
            bad += self._complaints(card.name, text)
            if re.search(r"^<!--\s*route:\s*browser\b", text, re.M):
                declared += 1
        self.assertGreaterEqual(declared, 12, f"{declared} cards declare `route: browser`; 12 did on 2026-09-12 — either lines were lost or the walk narrowed")
        self.assertEqual(bad, [], "\n".join(bad))

    def test_the_guard_reddens_in_both_directions_on_fixtures(self):
        undeclared = "# X\n\n<!-- script: none -->\n<!-- countries: XX -->\n<!-- content: measured · 12 rows read from a connected browser tab · 2026-09-12 -->\n"
        self.assertEqual(len(self._complaints("undeclared", undeclared)), 1)
        zero = undeclared + "<!-- route: browser · 0 · 2026-09-12 -->\n"
        self.assertTrue(any("above zero" in b for b in self._complaints("zero", zero)))
        nodate = undeclared + "<!-- route: browser · 12 -->\n"
        self.assertTrue(any("without a date" in b for b in self._complaints("nodate", nodate)))
        odd = undeclared + "<!-- route: carrier-pigeon · 12 · 2026-09-12 -->\n"
        self.assertTrue(any("not browser / http / none" in b for b in self._complaints("odd", odd)))
        good = undeclared + "<!-- route: browser · 12 · 2026-09-12 -->\n"
        self.assertEqual(self._complaints("good", good), [])
        none = undeclared + "<!-- route: none · the name is clientHold — a route to nothing · 2026-09-12 -->\n"
        self.assertEqual(self._complaints("none", none), [])

    def _tool(self):
        spec = importlib.util.spec_from_file_location("_country_boards", os.path.join(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "bin", "country-boards.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def test_the_tool_counts_a_declared_browser_route_as_done_and_a_route_to_nothing_as_before(self):
        import tempfile
        mod = self._tool()
        d = tempfile.mkdtemp()
        def card(name, body):
            with open(os.path.join(d, name + ".md"), "w", encoding="utf-8") as fh:
                fh.write(body)
        head = "<!-- script: none -->\n<!-- countries: XX -->\n<!-- content: measured · 262 rows read from a connected browser tab, the page states 262 · 2026-09-12 -->\n<!-- witness: the page · 2026-09-12 -->\n"
        card("walked", "# W\n\n" + head + "<!-- route: browser · 262 · 2026-09-12 -->\n")
        card("nothing", "# N\n\n" + head + "<!-- route: none · clientHold — a route to nothing · 2026-09-12 -->\n")
        card("silent", "# S\n\n<!-- script: none -->\n<!-- countries: XX -->\n<!-- content: measured · 5 rows · 2026-09-12 -->\n")
        cards = mod.read_cards(d)
        by = {c["name"]: c for c in cards}
        self.assertEqual(mod.route_of(by["walked"]), ("browser", 262, "2026-09-12"))
        self.assertIsNone(mod.route_of(by["nothing"]))
        self.assertEqual(mod.classify(by["walked"])[0], "fait")
        # #404 (2026-09-13): a declared `route: none` is «non faisable» — dated and motivated by its own
        # line — no longer «faisable»; until then this fixture was counted as feasible
        self.assertEqual(mod.classify(by["nothing"])[0], "infaisable")
        self.assertEqual(mod.classify(by["silent"])[0], "faisable")
        acc, basis = mod.access_of(by["walked"])
        self.assertTrue(acc.startswith("navigateur"), acc)
        self.assertEqual(basis, "`route: browser`")
        t = mod.table(cards, "XX")
        self.assertEqual((t["n"]["fait"], t["n"]["faisable"], t["n"]["infaisable"], t["total"], t["faisable"]), (1, 1, 1, 3, 2))
        self.assertIn("route navigateur — 262 annonce(s) au 2026-09-12", "\n".join(t["lines"]))


class APagedJobSitemapInTwoLanguagesAndTheEmployersIdIsNotTheAdvertisements(unittest.TestCase):
    """**`topdev.py`, 2026-09-13 (#233 lot 8 → adapter).** `/sitemap-jobs.xml`
    is an index of 249 `jobs_desc_en_page_<n>.xml` and 249 `_vi_` pages of
    20 `<loc>` each, the same ids in both languages; the adapter reads one
    language, takes the URL's trailing number as the id, dedups, and prints
    the distinct count beside the search page's «Tuyển dụng N việc làm» —
    «equal» / «k short»; a bounded walk (`--pages`) is a lower bound and is
    not compared. The JSON-LD's `identifier.value` is the EMPLOYER's id
    (94346 for MBBANK), kept apart from the advertisement's; the salary
    sentence «9.000.000 VND to 55.000.000 VND» is emitted as published beside
    the parsed min / max. Mutated (`-B`, detached copy): `PAGE_RE` for `en`
    made to match nothing → the walk dies (the equal case errors); the dedup
    removed → 3 ≠ 2; «short» → «equal» → the gap case reddens; `SITE_COUNT_RE`
    broken → «no second source» reddens the equal case; the `employer_id`
    taken as the advertisement's id → the ad case reddens; `bounded` forced
    False → the bounded case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_topdev", os.path.join(SCRIPTS, "topdev.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    INDEX = ("<sitemapindex>" + "".join(f"<sitemap><loc>https://topdev.vn/sitemap/jobs_desc_{l}_page_{n}.xml</loc></sitemap>"
                                       for l in ("en", "vi") for n in (1, 2)) + "<sitemap><loc>https://topdev.vn/sitemap-skills.xml</loc></sitemap></sitemapindex>")

    @staticmethod
    def _page(ids, lang="en"):
        seg = "detail-jobs" if lang == "en" else "viec-lam"
        return "<urlset>" + "".join(f"<url><loc>https://topdev.vn/{seg}/java-developer-x-{i}</loc><lastmod>2026-09-13</lastmod></url>" for i in ids) + "</urlset>"

    def _served(self, stated="4942"):
        pages = {1: [2125929, 2125916], 2: [2125916, 2128546]}
        def get(url):
            if url.endswith("/sitemap-jobs.xml"):
                return 200, self.INDEX
            m = re.search(r"jobs_desc_(en|vi)_page_(\d+)\.xml$", url)
            if m:
                return 200, self._page(pages[int(m.group(2))], m.group(1))
            if url.endswith("/viec-lam/tim-kiem"):
                return 200, f"<html><body><h1>Tuyển dụng {stated} việc làm lương cao [Update 13/9/2026]</h1></body></html>"
            raise AssertionError(url)
        return get

    def _sitemap(self, mod, get, pages=None, lang="en"):
        import contextlib
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_sitemap(argparse.Namespace(lang=lang, pages=pages, limit=None, no_site_total=False))
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue()

    def test_two_pages_are_deduplicated_and_compared_to_the_stated_count(self):
        rows, err = self._sitemap(self._mod(), self._served(stated="3"))
        self.assertEqual([r["id"] for r in rows], ["2125929", "2125916", "2128546"])
        self.assertIn("2 of 2 en sitemap page(s) read; 4 <loc>, 4 of the advertisement shape, 0 not; **3 distinct advertisement id(s)**.", err)
        self.assertIn("3 emitted, site states 3 on https://topdev.vn/viec-lam/tim-kiem — equal.", err)
        rows, err = self._sitemap(self._mod(), self._served(stated="3"), lang="vi")
        self.assertEqual([r["url"].split("/")[3] for r in rows], ["viec-lam"] * 3)

    def test_a_stated_count_above_the_distinct_is_named_short_and_a_bounded_walk_is_not_compared(self):
        rows, err = self._sitemap(self._mod(), self._served(stated="4942"))
        self.assertIn("3 emitted, site states 4 942 on https://topdev.vn/viec-lam/tim-kiem — 4 939 short", err)
        rows, err = self._sitemap(self._mod(), self._served(stated="4942"), pages=1)
        self.assertEqual(len(rows), 2)
        self.assertIn("the walk stopped at page 1, so the count is a lower bound", err)
        self.assertIn("site states 4 942 on https://topdev.vn/viec-lam/tim-kiem; 2 emitted from a bounded walk — not compared.", err)

    def test_the_employers_id_is_kept_apart_and_the_salary_sentence_is_emitted_as_published(self):
        import contextlib
        mod = self._mod()
        ld = json.dumps({"@context": "http://schema.org", "@type": "JobPosting", "title": "Chuyên viên KHCN", "datePosted": "2026-09-13",
                         "validThrough": "2026-09-16", "skills": "Risk Management, Leadership", "industry": "Information Technology",
                         "baseSalary": {"@type": "MonetaryAmount", "currency": "VND", "value": {"@type": "QuantitativeValue", "unitText": "MONTH",
                                        "minValue": "9000000", "maxValue": "55000000", "value": "9.000.000 VND to 55.000.000 VND"}},
                         "description": "<p>Địa điểm</p>", "identifier": {"@type": "PropertyValue", "name": "MBBANK", "value": 94346},
                         "hiringOrganization": {"@type": "Organization", "name": "MBBANK", "sameAs": "https://topdev.vn/companies/mbbank-94346"},
                         "employmentType": ["OTHER"], "directApply": "TRUE",
                         "jobLocation": {"@type": "Place", "address": {"@type": "PostalAddress", "addressLocality": "Tỉnh Ninh Bình", "addressRegion": "Tỉnh Ninh Bình", "addressCountry": "VN"}}}, ensure_ascii=False)
        mod.get = lambda u: (200, f'<html><head><script type="application/ld+json">{ld}</script></head><body></body></html>')
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_ad(argparse.Namespace(url="https://topdev.vn/detail-jobs/chuyen-vien-khcn-mbbank-2125929"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["employer_id"], d["employer"], d["country"], d["page_language"]), ("2125929", "94346", "MBBANK", "VN", "en"))
        self.assertEqual((d["salary_min"], d["salary_max"], d["salary_unit"], d["salary_currency"], d["salary_as_published"]),
                         (9000000, 55000000, "MONTH", "VND", "9.000.000 VND to 55.000.000 VND"))
        self.assertEqual((d["skills"], d["employment_type"], d["city"]), (["Risk Management", "Leadership"], "OTHER", "Tỉnh Ninh Bình"))


class SixAnthropicNamesRefusedAndNotThisOneAndASpanishThousandsDot(unittest.TestCase):
    """**`tecnoempleo.py`, 2026-09-13 (#233 lot 8 → adapter).** The rules
    refuse the whole site to six Anthropic names and not to `Claude-User`;
    the adapter reads under that token, records the six on the card, and
    asks for nothing under the `*` refusals. One sitemap of 30 891 `<loc>`
    holds 2 145 offers keyed by the `rf-` hash, with real `<lastmod>`; the
    listing states «2.592 Ofertas» with a Spanish thousands dot, parsed to
    2 592 and printed beside the count («447 short» on the day). The
    JSON-LD's `identifier.value` is the employer's id, kept apart. Mutated
    (`-B`, detached copy): the dedup removed → 3 ≠ 2; «short» → «equal» →
    the gap case reddens; `SITE_COUNT_RE` broken → «no second source»
    reddens the equal case; the thousands-dot strip removed → 2 592 parses
    as 2 (the gap case reddens); the employer id taken as the offer's →
    the ad case reddens; the lastmod set left empty → the «real dates»
    sentence reddens."""

