class TwentyThreeSectorFilesOneIdAndARefusedLanguageNeverRead(unittest.TestCase):
    """**`profession.py`, 2026-09-13 (#359).** Profession.hu lists its
    advertisements in 23 sector sitemaps; an advertisement can sit in two
    (ten did on 2026-09-13), so the adapter dedups on the id and keeps the
    sectors; the same files list `/en/advertisement/…` twins that the rules
    refuse (`Disallow: /en/`) — counted apart, never read, never emitted,
    and `ad --url` on one is refused before any request. The witness is
    the listing page's own title «… - 19329 db - …», printed beside the
    count and never merged. The advertisement's `JobPosting` carries the
    EMPLOYER's number in `hiringOrganization.@id` (kept apart), no
    `jobLocation` — the place is the page's `addressLocality` microdata,
    with the mode («Hibrid») before the separator — and a `validThrough`
    that is the read time plus thirty days: kept as published, never
    offered as an expiry. Mutated (`-B`, detached copy): the `/en/` branch
    dropped → 0 set aside, reddens; the dedup removed → 4 ≠ 3; the stated
    figure replaced by the row count → «equal», reddens; `employer_id`
    taken from the advertisement's id → reddens; `valid_through` passed
    through → reddens; `AD_RE` widened to `/en/advertisement/` → the
    refusal case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_profession", os.path.join(SCRIPTS, "profession.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _urlset(urls):
        return ('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
                + "".join(f"<url><loc>{u}</loc><lastmod>2026-09-13T02:50:54+02:00</lastmod></url>" for u in urls) + "</urlset>")

    INDEX = ('<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
             '<sitemap><loc>https://www.profession.hu/sitemap-listings-admin-hu.xml</loc></sitemap>'
             '<sitemap><loc>https://www.profession.hu/sitemap-listings-sales-hu.xml</loc></sitemap></sitemapindex>')

    def _list(self, mod, pages, limit=None, no_total=False):
        import contextlib
        asked = []
        def get(url):
            asked.append(url)
            if url in pages:
                return 200, pages[url]
            raise AssertionError(url)
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(argparse.Namespace(limit=limit, no_site_total=no_total))
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), asked

    def test_the_sectors_are_merged_on_the_id_the_english_twins_set_aside_and_the_title_count_printed_apart(self):
        mod = self._mod()
        admin = self._urlset(["https://www.profession.hu/allas/sales-business-development-specialist-mint-consulting-kft-2999723",
                              "https://www.profession.hu/en/advertisement/brand-communication-manager-intersnack-2999926",
                              "https://www.profession.hu/allas/office-manager-loranger-2999930"])
        sales = self._urlset(["https://www.profession.hu/allas/sales-business-development-specialist-mint-consulting-kft-2999723",
                              "https://www.profession.hu/allas/shop-eladot-keresunk-2999940"])
        listing = "<html><head><title>Állások, munkák és állásajánlatok - 19329 db - 2026 Szeptember | Profession.hu</title></head><body>19329 állás</body></html>"
        rows, err, asked = self._list(mod, {mod.INDEX: self.INDEX, "https://www.profession.hu/sitemap-listings-admin-hu.xml": admin,
                                            "https://www.profession.hu/sitemap-listings-sales-hu.xml": sales, mod.LISTING: listing})
        self.assertEqual([r["id"] for r in rows], ["2999723", "2999930", "2999940"])
        self.assertEqual(rows[0]["sectors"], ["admin", "sales"])
        self.assertEqual((rows[0]["ledger_id"], rows[0]["country"], rows[1]["slug"]), ("profession:2999723", "HU", "office-manager-loranger"))
        self.assertFalse(any("/en/" in u for u in asked))
        self.assertIn("2 sector file(s), 5 <loc>; **3 distinct advertisement id(s)** (1 listed in two sectors), 1 `/en/` URL(s) set aside — `Disallow: /en/` is written, so they are neither read nor emitted.", err)
        self.assertIn("3 emitted, site states 19 329 — 19 326 short; the sitemaps and the listing's own title are two witnesses, and neither corrects the other", err)
        self.assertNotIn("equal", err)
        with self.assertRaises(SystemExit) as cm:
            self._list(mod, {mod.INDEX: self.INDEX, "https://www.profession.hu/sitemap-listings-admin-hu.xml": admin.replace("</url>", "</url><url></url>", 1)}, no_total=True)
        self.assertEqual(cm.exception.code, mod.EXIT_PARTIAL)

    def test_the_advertisement_keeps_the_employers_number_apart_reads_the_place_from_the_page_and_never_offers_the_formula_as_an_expiry(self):
        import contextlib
        mod = self._mod()
        ld = {"@context": "https://schema.org", "@type": "JobPosting", "@id": "https://www.profession.hu/#/schema/JobPosting/2999723",
              "title": "Sales & Business Development Specialist", "description": "<p>Főbb feladatok</p><ul><li>Coordination</li></ul>", "datePosted": "2026-09-12",
              "validThrough": "2026-10-13T19:23:12", "employmentType": "Alkalmazotti jogviszony", "jobLocationType": "TELECOMMUTE",
              "hiringOrganization": {"@id": "https://www.profession.hu/#/schema/Organization/123493", "@type": "Organization", "name": "Mint Consulting Kft."},
              "occupationalCategory": "Üzleti támogató központok - Értékesítés támogatás", "applicantLocationRequirements": [{"@type": "Country", "name": "Magyarország"}]}
        body = (f'<html><head><script type="application/ld+json">{json.dumps(ld, ensure_ascii=False)}</script></head><body><h1>Sales &amp; Business Development Specialist</h1>'
                '<h3 class="sr-only">Munkavégzés helye </h3><div class="my-auto font-size-16 address-data">\nHibrid\n<span class="location-separator">•</span>\n'
                '<span itemprop="jobLocation" itemscope itemtype="https://schema.org/Place"><span itemprop="addressLocality">\nBudapest\n</span></span></div>'
                '<a href="mailto:hr@example.hu">Jelentkezem</a></body></html>')
        mod.get = lambda url: (200, body)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.profession.hu/allas/sales-business-development-specialist-mint-consulting-kft-2999723"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["employer_id"], d["employer"], d["ledger_id"]), ("2999723", "123493", "Mint Consulting Kft.", "profession:2999723"))
        self.assertEqual((d["place"], d["work_mode"], d["remote"], d["employment_type"], d["posted"]), ("Budapest", "Hibrid", True, "Alkalmazotti jogviszony", "2026-09-12"))
        self.assertIsNone(d["valid_through"])
        self.assertEqual(d["valid_through_as_published"], "2026-10-13T19:23:12")
        self.assertEqual(d["description"], "Főbb feladatok Coordination")
        self.assertNotIn("hr@example.hu", out.getvalue())
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.profession.hu/en/advertisement/brand-communication-manager-intersnack-2999926"))
        self.assertEqual(cm.exception.code, mod.EXIT_BROKEN)


class TwoStoresInTwoSitemapsKeyedApartAndTheContactPersonNeverRead(unittest.TestCase):
    """**`easyprace.py`, 2026-09-13 (#352).** easy-prace.cz publishes its own
    advertisements (`/nabidka/<slug>/<id>`, `easyprace-aktivni-easy.xml`) and
    the Úřad práce ČR's republication (`/volne-misto/<slug>/<id>`,
    `easyprace-aktivni-up.xml`) in two sitemaps whose id spaces collide: the
    adapter keys every row by store (`easyprace:easy:<id>` /
    `easyprace:up:<id>`), sets aside a URL of the other store's shape in a
    file named for one, and prints the listing's own «N výsledků» beside
    the total — only when both stores were read. The advertisement page has
    no JSON-LD: the `<h1>`, the employer block, the salary block,
    label/value pairs, content rows read as fields («Směnnost») or joined
    as the description («Popis pracovní nabídky»); the contact person the
    page names is never read. Mutated (`-B`, detached copy): the store key
    dropped from `ledger_id` → the colliding ids merge, reddens; the store
    check in `entry` dropped → the foreign URL is emitted, 4 ≠ 3; the
    single-store comparison allowed → «short» printed, reddens; the stated
    figure replaced by the row count → «equal», reddens; the content-row
    field mapping dropped → `shifts` None, reddens; the description joined
    from every row including the fields → «Směnnost» leaks in, reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_easyprace", os.path.join(SCRIPTS, "easyprace.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _urlset(urls):
        return ('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
                + "".join(f"<url><loc>{u}</loc><lastmod>2026-09-11</lastmod><priority>0.7</priority></url>" for u in urls) + "</urlset>")

    def _list(self, mod, pages, store="both", limit=None, no_total=False):
        import contextlib
        def get(url):
            if url in pages:
                return 200, pages[url]
            raise AssertionError(url)
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(argparse.Namespace(store=store, limit=limit, no_site_total=no_total))
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue()

    def test_the_two_stores_are_keyed_apart_a_foreign_shape_is_set_aside_and_the_listing_is_compared_only_to_both(self):
        mod = self._mod()
        easy = self._urlset(["https://www.easy-prace.cz/nabidka/stevard-ka/620969", "https://www.easy-prace.cz/volne-misto/kuchar/620969", "https://www.easy-prace.cz/nabidka/ridic/1469963"])
        up = self._urlset(["https://www.easy-prace.cz/volne-misto/zdravotni-sestra/1469963"])
        listing = "<html><body><p>Nabídka zaměstnání z celé České republiky</p><strong>34 578 výsledků</strong></body></html>"
        pages = {mod.STORES["easy"][0]: easy, mod.STORES["up"][0]: up, mod.LISTING: listing}
        rows, err = self._list(mod, pages)
        self.assertEqual([r["ledger_id"] for r in rows], ["easyprace:easy:620969", "easyprace:easy:1469963", "easyprace:up:1469963"])
        self.assertEqual(len({r["ledger_id"] for r in rows}), 3)
        self.assertEqual((rows[0]["store"], rows[2]["store"], rows[2]["slug"], rows[0]["country"]), ("easy", "up", "zdravotni-sestra", "CZ"))
        self.assertIn("4 <loc> over 2 store file(s); **3 row(s)** keyed by store — easy (the board's own): 2 distinct id(s) of 3 <loc>, 1 of another shape set aside; up (Úřad práce ČR, republished): 1 distinct id(s) of 1 <loc>.", err)
        self.assertIn("3 emitted, site states 34 578 — 34 575 short; the two sitemaps and the listing's own count are two witnesses, and neither corrects the other.", err)
        rows, err = self._list(mod, pages, store="up")
        self.assertEqual([r["ledger_id"] for r in rows], ["easyprace:up:1469963"])
        self.assertIn("site total not compared: one store read (--store up), and the listing counts both.", err)
        self.assertNotIn("short", err)
        with self.assertRaises(SystemExit) as cm:
            self._list(mod, dict(pages, **{mod.STORES["up"][0]: up.replace("</url>", "</url><url></url>", 1)}), no_total=True)
        self.assertEqual(cm.exception.code, mod.EXIT_PARTIAL)

    def test_the_advertisement_is_read_by_its_blocks_the_rows_are_fields_or_description_and_the_person_is_never_emitted(self):
        import contextlib
        mod = self._mod()
        body = ('<html><body><h1><span class="">ZDRAVOTNÍ SESTRA</span></h1><div class="NabidkaDetail-company"><span class="NabidkaDetail-companyName">DentLive s.r.o.</span></div>'
                '<div class="NabidkaDetail-salary">40 000 - 46 000 Kč</div>'
                '<div class="NabidkaDetail-infoItem"><p class="NabidkaDetail-infoLabel">Lokalita</p><div class="NabidkaDetail-infoValue"><strong>Na Brně 370, Hradec Králové</strong> a další</div></div>'
                '<div class="NabidkaDetail-infoItem"><p class="NabidkaDetail-infoLabel">Úvazek</p><div class="NabidkaDetail-infoValue">Plný úvazek</div></div>'
                '<div class="NabidkaDetail-infoItem"><p class="NabidkaDetail-infoLabel">Vzdělání</p><div class="NabidkaDetail-infoValue">minimálně SŠ s maturitou</div></div>'
                '<div class="NabidkaDetail-content"><div class="NabidkaDetail-contentRow"><h2>Popis pracovní nabídky</h2>Ošetřovatelská péče.</div>'
                '<div class="NabidkaDetail-contentRow"><h2>Směnnost</h2>Jednosměnný provoz</div><div class="NabidkaDetail-contentRow"><h2>Pracovní období</h2>od 1.4.2026</div>'
                '<div class="NabidkaDetail-contactPerson"><h3>Kontaktní osoba</h3><div class="NabidkaDetail-contactPersonItem">Jana Mertlíková</div></div></div></body></html>')
        mod.get = lambda url: (200, body)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.easy-prace.cz/volne-misto/zdravotni-sestra/1469963"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["store"], d["ledger_id"], d["title"], d["employer"], d["salary"]), ("up", "easyprace:up:1469963", "ZDRAVOTNÍ SESTRA", "DentLive s.r.o.", "40 000 - 46 000 Kč"))
        self.assertEqual((d["place"], d["employment_type"], d["education"], d["shifts"], d["period"]), ("Na Brně 370, Hradec Králové a další", "Plný úvazek", "minimálně SŠ s maturitou", "Jednosměnný provoz", "od 1.4.2026"))
        self.assertEqual(d["description"], "Popis pracovní nabídky: Ošetřovatelská péče.")
        self.assertNotIn("Mertlíková", out.getvalue())
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.easy-prace.cz/nabidka-zamestnani/strana/2"))
        self.assertEqual(cm.exception.code, mod.EXIT_BROKEN)


class TwoJobDetailSitemapsAgainstTheRootsOwnCountAndAPageThatIsReportedNotRead(unittest.TestCase):
    """**`isinolsun.py`, 2026-09-13 (#382).** İşin Olsun lists 87 504 keys
    `/is-ilani/<slug>-0ioj<32 hex>` in two job-detail sitemaps (eight slugs
    carry a literal tab; the key behind them is sound); the adapter dedups
    on the hex key, sets aside a URL of another shape, and prints the root's
    own «87.394 İş İlanı» beside its count, never merged. The advertisement
    page stalled without a byte for every plain client on 2026-09-13, so
    `ad --url` REPORTS: stalled → exit 6 with the dated fact; served → exit
    6 naming the status, the size and the JobPosting count, because no reader
    was ever written against a page never served. Mutated (`-B`, detached
    copy): the dedup removed → 4 ≠ 3; the thousands dot kept → the stated
    figure cannot be read, reddens; the key taken from the slug → reddens;
    the tab-tolerant slug narrowed to `[a-z0-9-]` → the tab URL is set
    aside, 2 ≠ 3; the stall branch dropped → exit 2 instead of 6, reddens;
    the served report's JobPosting count zeroed → reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_isinolsun", os.path.join(SCRIPTS, "isinolsun.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _urlset(urls):
        return ('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
                + "".join(f"<url><loc>{u}</loc><lastmod>2026-09-13T02:10:10.3840802+03:00</lastmod></url>" for u in urls) + "</urlset>")

    INDEX = ('<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
             '<sitemap><loc>https://isinolsun.com/sitemaps/jobdetailsitemap1.xml</loc></sitemap><sitemap><loc>https://isinolsun.com/sitemaps/positionlistsitemap.xml</loc></sitemap>'
             '<sitemap><loc>https://isinolsun.com/sitemaps/jobdetailsitemap2.xml</loc></sitemap></sitemapindex>')
    K1, K2, K3 = "898A255D98D1435E9AFB8E145D933CEF", "D48726A154CF4A618AE9CAA5431712C3", "4D6E7EDEA9DE4BA9852AFB27739407BA"

    def _list(self, mod, pages, limit=None, no_total=False):
        import contextlib
        def get(url, timeout=120):
            if url in pages:
                return 200, pages[url]
            raise AssertionError(url)
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(argparse.Namespace(limit=limit, no_site_total=no_total))
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue()

    def test_the_keys_are_deduped_the_tab_slug_kept_the_other_shape_set_aside_and_the_root_count_printed_apart(self):
        mod = self._mod()
        f1 = self._urlset([f"https://isinolsun.com/is-ilani/tatli-ustasi-carmen-tatlicilik-0ioj{self.K1}", "https://isinolsun.com/is-ilanlari/istanbul",
                           f"https://isinolsun.com/is-ilani/kalite-kontrol-elemani-bandido-cosmetics-\tbandido-cosmetics-0ioj{self.K3}"])
        f2 = self._urlset([f"https://isinolsun.com/is-ilani/guvenlik-gorevlisi-dad89-0ioj{self.K2}", f"https://isinolsun.com/is-ilani/tatli-ustasi-carmen-tatlicilik-0ioj{self.K1}"])
        root = "<html><body><div>16.155.987 İndirme</div><div>87.394 İş İlanı</div></body></html>"
        rows, err = self._list(mod, {mod.INDEX: self.INDEX, "https://isinolsun.com/sitemaps/jobdetailsitemap1.xml": f1, "https://isinolsun.com/sitemaps/jobdetailsitemap2.xml": f2, mod.BASE + "/": root})
        self.assertEqual([r["id"] for r in rows], [self.K1, self.K3, self.K2])
        self.assertEqual((rows[0]["ledger_id"], rows[0]["slug"], rows[0]["country"]), (f"isinolsun:{self.K1}", "tatli-ustasi-carmen-tatlicilik", "TR"))
        self.assertIn("2 job-detail file(s), 5 <loc>; **3 distinct advertisement key(s)** of the shape /is-ilani/<slug>-0ioj<hex>, 1 of another shape set aside.", err)
        self.assertIn("3 emitted, site states 87 394 — 87 391 short; the sitemaps and the root's own count are two witnesses, and neither corrects the other.", err)
        self.assertNotIn("16 155 987", err)

    def test_the_page_is_reported_stalled_or_served_and_never_pretended_read(self):
        import contextlib
        mod = self._mod()
        url = f"https://isinolsun.com/is-ilani/tatli-ustasi-carmen-tatlicilik-0ioj{self.K1}"
        mod.get = lambda u, timeout=120: (None, f"stalled: no answer in {timeout} s (TimeoutError)")
        err = io.StringIO()
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(err):
            mod.cmd_ad(argparse.Namespace(url=url, timeout=30))
        self.assertEqual(cm.exception.code, mod.EXIT_PARTIAL)
        self.assertIn("stalled: no answer in 30 s", err.getvalue())
        self.assertIn("no reader is written against a page never served", err.getvalue())
        ld = '<script type="application/ld+json">{"@context":"https://schema.org","@type":"JobPosting","title":"Tatlı Ustası","description":"x","datePosted":"2026-09-13","hiringOrganization":{"@type":"Organization","name":"Carmen"}}</script>'
        mod.get = lambda u, timeout=120: (200, f"<html><head>{ld}</head><body>Tatlı Ustası <a href='mailto:ik@example.com.tr'>başvur</a></body></html>")
        out, err = io.StringIO(), io.StringIO()
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_ad(argparse.Namespace(url=url, timeout=30))
        self.assertEqual(cm.exception.code, mod.EXIT_PARTIAL)
        self.assertIn("SERVED — HTTP 200", err.getvalue())
        self.assertIn("1 JobPosting in JSON-LD", err.getvalue())
        self.assertEqual(out.getvalue(), "")
        self.assertNotIn("ik@example.com.tr", err.getvalue())
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://isinolsun.com/is-ilanlari/istanbul", timeout=30))
        self.assertEqual(cm.exception.code, mod.EXIT_BROKEN)


class NamedAsClaudeUserWhereEveryoneElseIsRefusedAndTheAddressInTheProseWithheld(unittest.TestCase):
    """**`duunitori.py`, 2026-09-13 (#374).** Duunitori's rules refuse `*`
    and name `Claude-User` to let it in; the advertisements are 92 pages
    of `sitemap-jobentry.xml?p=N` (200 a page) whose URL stem ends in a
    source token of no fixed shape and the id — the id is the key, the
    stem the slug; a bounded walk is a lower bound and is not compared; the
    witness is the listing's own «Löysimme N työpaikkaa», and the second
    figure of that sentence (published in the last week) is never read.
    The advertisement's JSON-LD `title` is the normalised occupation, so
    the title is the page's `<h1>` and the JSON-LD's goes to `occupation`;
    an e-mail address in the description's prose is withheld. Mutated
    (`-B`, detached copy): the dedup removed → 4 ≠ 3; the key taken from
    the stem → reddens; the bounded walk compared → «short», reddens; the
    stated regex loosened to the second figure → 5 993 read, reddens; the
    title taken from the JSON-LD → «harjoittelija», reddens; the redaction
    dropped → the address leaks, reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_duunitori", os.path.join(SCRIPTS, "duunitori.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _urlset(urls):
        return ('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
                + "".join(f"<url><loc>{u}</loc><lastmod>2026-09-13</lastmod><changefreq>always</changefreq></url>" for u in urls) + "</urlset>")

    INDEX = ('<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
             '<sitemap><loc>https://duunitori.fi/sitemap-company.xml</loc></sitemap><sitemap><loc>https://duunitori.fi/sitemap-jobentry.xml</loc></sitemap>'
             '<sitemap><loc>https://duunitori.fi/sitemap-jobentry.xml?p=2</loc></sitemap><sitemap><loc>https://duunitori.fi/sitemap-jobentry.xml?p=3</loc></sitemap></sitemapindex>')
    LISTING = "<html><body><h1>Työpaikat yhdellä haulla</h1><p>Löysimme 18 302 työpaikkaa, joista 5 993 on julkaistu viimeisen viikon aikana.</p></body></html>"

    def _list(self, mod, pages, n=None, limit=None, no_total=False):
        import contextlib
        def get(url):
            if url in pages:
                return 200, pages[url]
            raise AssertionError(url)
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(argparse.Namespace(pages=n, limit=limit, no_site_total=no_total))
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue()

    def test_the_pages_are_walked_the_id_is_the_key_whatever_the_token_and_the_first_figure_is_the_witness(self):
        mod = self._mod()
        p1 = self._urlset(["https://duunitori.fi/tyopaikat/tyo/eta-capital-oy-sahkoasentaja-sdsuu-20568574", "https://duunitori.fi/tyopaikat/tyo/myyja-pori-satasairaala-sairaalantie-3-srs-k-20566891", "https://duunitori.fi/yritys/ey"])
        p2 = self._urlset(["https://duunitori.fi/tyopaikat/tyo/eta-capital-oy-sahkoasentaja-sdsuu-20568574"])
        p3 = self._urlset(["https://duunitori.fi/tyopaikat/tyo/senior-consultant-mainframe-modernization-scsom-18062313"])
        pages = {mod.INDEX: self.INDEX, "https://duunitori.fi/sitemap-jobentry.xml": p1, "https://duunitori.fi/sitemap-jobentry.xml?p=2": p2, "https://duunitori.fi/sitemap-jobentry.xml?p=3": p3, mod.LISTING: self.LISTING}
        rows, err = self._list(mod, pages)
        self.assertEqual([r["id"] for r in rows], ["20568574", "20566891", "18062313"])
        self.assertEqual((rows[1]["slug"], rows[1]["ledger_id"], rows[0]["country"]), ("myyja-pori-satasairaala-sairaalantie-3-srs-k", "duunitori:20566891", "FI"))
        self.assertIn("3 of 3 jobentry page(s) read, 5 <loc>; **3 distinct advertisement id(s)**, 1 repeated across pages — the paging is not a partition, so as many may be missing at the page boundaries, 1 of another shape set aside.", err)
        self.assertIn("3 emitted, site states 18 302 — 18 299 short; the sitemap and the listing's own count are two witnesses, and neither corrects the other.", err)
        self.assertNotIn("5 993", err)
        rows, err = self._list(mod, pages, n=1)
        self.assertEqual(len(rows), 2)
        self.assertIn("the walk stopped at page 1 of 3, so the count is a lower bound", err)
        self.assertIn("site states 18 302; 2 emitted from a bounded walk, not compared.", err)
        self.assertNotIn("short", err)

    def test_the_title_is_the_h1_the_occupation_is_the_json_lds_and_the_address_in_the_prose_is_withheld(self):
        import contextlib
        mod = self._mod()
        ld = {"@context": "https://schema.org", "@type": "JobPosting", "title": "harjoittelija", "datePosted": "2026-08-24T21:00:00+00:00", "validThrough": "2026-09-20T20:59:00+00:00",
              "employmentType": "INTERN", "hiringOrganization": {"@type": "Organization", "name": "ernst & young", "sameAs": "http://www.ey.com/fi"},
              "jobLocation": {"@type": "Place", "address": {"@type": "PostalAddress", "addressLocality": "Helsinki", "addressCountry": "FI"}},
              "description": "<p>Join us.</p><p>If you have any questions, you can contact EY’s recruitment team at rekrytointi@fi.ey.com or +358 40 123 4567.</p>"}
        body = f'<html><head><script type="application/ld+json">{json.dumps(ld, ensure_ascii=False)}</script></head><body><h1>EY Trainee Program</h1><a href="mailto:rekrytointi@fi.ey.com">rekrytointi@fi.ey.com</a></body></html>'
        mod.get = lambda url: (200, body)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://duunitori.fi/tyopaikat/tyo/ernst-young-ey-trainee-program-sdsuu-20512921"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["title"], d["occupation"], d["employer"], d["city"], d["country"], d["employment_type"]), ("20512921", "EY Trainee Program", "harjoittelija", "ernst & young", "Helsinki", "FI", "INTERN"))
        self.assertEqual(d["valid_through"], "2026-09-20T20:59:00+00:00")
        self.assertIn("recruitment team at [e-mail withheld]", d["description"])
        self.assertNotIn("fi.ey.com", out.getvalue())
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://duunitori.fi/yritys/ey"))
        self.assertEqual(cm.exception.code, mod.EXIT_BROKEN)


class TheStatesOwnStoreByDefaultTheRepublishedOnRequestAndTheContactSectionNeverRead(unittest.TestCase):
    """**`sluzbyzamestnanosti.py`, 2026-09-13 (#342).** The Slovak public
    employment service's board answers a JSON search (`/search/ponuky`,
    `pageNr`/`pageSize`, `zdrojPonuky=VPM` for the state's own store) whose
    answer carries the site's own `countVPM` beside the rows: the adapter
    reads the state's store by default, keys every row by `uuid`, links an
    external row to the portal that holds it and an own row to its page
    here, prints «n emitted, site states N» from the answer's count and
    never compares a bounded walk, nor the positions figure. The
    advertisement page is a `<dl>`; everything at or after «Kontaktná
    osoba» is cut before reading. Mutated (`-B`, detached copy): the
    `zdrojPonuky=VPM` parameter dropped → the default reads all sources,
    reddens; the dedup removed → 4 ≠ 3; the external row linked to the
    page here instead of its portal → reddens; the positions figure
    compared instead of `countVPM` → reddens; the contact cut dropped →
    the contact's «Internetová adresa» fills `employer_site`, reddens (a
    first fixture had no label of the adapter's in that section and left
    the cut unexercised — the fixture, not the guard); the place's «location_on» tail
    kept → reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_sluzbyzamestnanosti", os.path.join(SCRIPTS, "sluzbyzamestnanosti.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _answer(items, count, page, size=100):
        return json.dumps({"countVPM": count, "countZamestnavatelia": 5324, "countPocetVolnychMiest": 128448, "pageNr": page, "pageSize": size, "pracovnePonuky": items}, ensure_ascii=False)

    @staticmethod
    def _item(uuid, title, src=1, portal=None, url=None, salary=1200.0):
        return {"uuid": uuid, "nazovPracovnehoMiesta": title, "zamestnavatelObchodneMeno": "Mikádo", "miestoVykonuPrace": "Skalica - Skalica", "zakladnaMzda": salary,
                "zakladnaMzdaZaObdobie": "MESIAC", "naposledyZmenene": "2026-09-13T12:42:27", "priznakZdroj": src, "zdrojVytvorenia": "EXT" if src == 3 else "VPM", "externyPortal": portal, "urlExternyPortal": url}

    def _list(self, mod, answers, source="VPM", pages=None, limit=None, no_total=False):
        import contextlib, urllib.parse
        asked = []
        def get(url, accept=None):
            asked.append(url)
            q = dict(urllib.parse.parse_qsl(urllib.parse.urlsplit(url).query))
            key = (q.get("zdrojPonuky", "all"), int(q.get("pageNr", 1)))
            if key in answers:
                return 200, answers[key]
            raise AssertionError(url)
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(argparse.Namespace(source=source, pages=pages, limit=limit, no_site_total=no_total))
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), asked

    def test_the_states_store_is_read_by_default_keyed_by_uuid_and_compared_to_the_answers_own_count(self):
        mod = self._mod()
        a1 = self._answer([self._item("7f97c15a-d87d-42ce-9c07-9cb986ef87e9", "Layouter"), self._item("b4e15b7a-46ab-4d98-9079-6fd773217515", "Pomocný pracovník", src=3, portal="profesia.sk", url="https://www.profesia.sk/O5354102")], 3, 1, size=2)
        a2 = self._answer([self._item("7f97c15a-d87d-42ce-9c07-9cb986ef87e9", "Layouter"), self._item("960b5dd5-85db-422b-a962-39691615bcfb", "Sociálny pracovník", src=2)], 3, 2, size=2)
        answers = {("VPM", 1): a1, ("VPM", 2): a2, ("all", 1): self._answer([self._item("x1", "A", src=3, portal="worki.sk", url="https://www.worki.sk/1")], 25563, 1, size=100)}
        rows, err, asked = self._list(mod, answers)
        self.assertTrue(all("zdrojPonuky=VPM" in u for u in asked), asked)
        self.assertEqual([r["id"] for r in rows], ["7f97c15a-d87d-42ce-9c07-9cb986ef87e9", "b4e15b7a-46ab-4d98-9079-6fd773217515", "960b5dd5-85db-422b-a962-39691615bcfb"])
        self.assertEqual((rows[0]["store"], rows[0]["entered_via"], rows[0]["url"], rows[0]["salary"], rows[0]["ledger_id"]),
                         ("own", "úrad PSVR", "https://www.sluzbyzamestnanosti.gov.sk/pracovne-ponuky/7f97c15a-d87d-42ce-9c07-9cb986ef87e9", "1200 € / mesiac", "sz:7f97c15a-d87d-42ce-9c07-9cb986ef87e9"))
        self.assertEqual((rows[1]["store"], rows[1]["external_portal"], rows[1]["url"]), ("external", "profesia.sk", "https://www.profesia.sk/O5354102"))
        self.assertEqual(rows[2]["entered_via"], "Portál SZ")
        self.assertIn("2 page(s) of 2 read (the state's own store, zdrojPonuky=VPM); **3 distinct advertisement(s)** — 2 the state's own, 1 republished from external portals.", err)
        self.assertIn("3 emitted, site states 3 — equal (site also states 5 324 employers and 128 448 positions — positions, not advertisements, never compared).", err)
        rows, err, asked = self._list(mod, answers, source="all", pages=1)
        self.assertFalse(any("zdrojPonuky" in u for u in asked))
        self.assertIn("the walk stopped at page 1 of 256, so the count is a lower bound", err)
        self.assertIn("site states 25 563", err)
        self.assertIn("1 emitted from a bounded walk, not compared.", err)
        self.assertNotIn("short", err)

    def test_the_advertisement_page_is_a_dl_cut_before_the_contact_section(self):
        import contextlib
        mod = self._mod()
        body = ('<html><body><h1>Layouter/ka elektronických systémov PCB/ASIC (muž/žena)</h1><h2>Údaje o pracovnej pozícii</h2><dl>'
                '<dt>Miesto výkonu práce, Ďalšie miesto výkonu práce</dt><dd>Einsteinova 11 , 85101 Bratislava-Petržalka - Bratislava V Slovensko <span>location_on</span> Google maps</dd>'
                '<dt>Základná zložka mzdy v eurách (v hrubom)</dt><dd>4 500 € mesačne</dd><dt>Id VPM</dt><dd>2677107</dd><dt>Zdroj</dt><dd>úrad PSVR</dd>'
                '<dt>Názov pracovnej pozície</dt><dd>Layouter/ka elektronických systémov PCB/ASIC (muž/žena)</dd><dt>Počet voľných miest</dt><dd>1</dd>'
                '<dt>Náplň práce</dt><dd>• Návrh layoutu elektronických obvodov</dd><dt>Pracovný a mimopracovný pomer</dt><dd>Pracovný pomer na určitú dobu</dd>'
                '<dt>Názov spoločnosti</dt><dd>Continium Technologies s.r.o.</dd><dt>IČO</dt><dd>53614836</dd></dl>'
                '<h2>Kontaktná osoba</h2><dl><dt>Meno</dt><dd>Jana Nováková</dd><dt>Telefón</dt><dd>+421 900 123 456</dd><dt>Internetová adresa</dt><dd>jana.novakova@example.sk</dd></dl></body></html>')
        mod.get = lambda url, accept=None: (200, body)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.sluzbyzamestnanosti.gov.sk/pracovne-ponuky/7f97c15a-d87d-42ce-9c07-9cb986ef87e9?pageNr=1"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["title"], d["place"], d["salary"], d["vpm_id"], d["source_label"], d["employer"], d["employer_ico"], d["positions"]),
                         ("7f97c15a-d87d-42ce-9c07-9cb986ef87e9", "Layouter/ka elektronických systémov PCB/ASIC (muž/žena)", "Einsteinova 11 , 85101 Bratislava-Petržalka - Bratislava V Slovensko", "4 500 € mesačne", "2677107", "úrad PSVR", "Continium Technologies s.r.o.", "53614836", "1"))
        self.assertEqual(d["description"], "• Návrh layoutu elektronických obvodov")
        self.assertIsNone(d["employer_site"])   # the contact section's «Internetová adresa» would fill it if the cut were dropped
        self.assertNotIn("Nováková", out.getvalue())
        self.assertNotIn("+421", out.getvalue())
        self.assertNotIn("example.sk", out.getvalue())
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.profesia.sk/O5354102"))
        self.assertEqual(cm.exception.code, mod.EXIT_BROKEN)


class AStateApiWalkedToTheCountItStatesWithContactsWithheld(unittest.TestCase):
    """**`uruguayconcursa.py`, 2026-09-13 (#435).** Uruguay's ONSC lists its
    llamados through the JSON API its page posts to; `list` walks
    `find` 50 a page to the `cntTotal` the API states, prints «N emitted,
    site states N — equal» and exits 6 on a gap; a bounded walk says so
    and is not compared. The employer is the state body and is public; an
    e-mail address or a phone number in the prose is a contact and is
    withheld. `ad` reads `get/?Llaid=` and exits 3 on an empty list.
    Mutated (`-B`, detached copy): `cntTotal` ignored → the walk case
    reddens (the «(N)» fallback disagrees by construction); the dedup
    dropped → the walk case reddens (page 2 repeats one id); EMAIL_RE
    neutralised → the redaction case reddens; the `positions` sum stopped
    → the record case reddens; the gap exit removed → the short case
    reddens; the empty-list exit removed → the ad case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_uruguayconcursa", os.path.join(SCRIPTS, "uruguayconcursa.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _rec(i, **kw):
        r = {"LlaId": str(i), "LlaNum": f"{i:04d}/2026", "LlaTit": f"Puesto {i}", "CarNom": f"Cargo {i}", "Inciso": "Universidad de la República",
             "UnidadEjecutora": "Facultad de Ingeniería", "LlaLugDes": "Montevideo", "LlaFchApeIns": "2026-09-01", "LlaFchCieIns": "2026-09-30",
             "LlaEstWeb": "Abierto", "TipVinDsc": "Contratado", "TipTarDsc": "Docencia", "LlaRet": "", "LlaCarHor": "20 horas",
             "listaOrganismoCantPuestos": [{"LlaOrgCntPue": 2, "OrgDsc": "A"}, {"LlaOrgCntPue": 3, "OrgDsc": "B"}], "listaEtapaProceso": [" 1- Méritos "],
             "LlaReqExc": "Título habilitante.", "LlaConTra": "", "LlaTieCon": "", "LlaRegInc": "", "LlaMedPos": "www.uruguayconcursa.gub.uy",
             "LlaAfro": False, "LlaTrans": True, "LlaDisc": False, "LlaVicDelVio": False}
        r.update(kw)
        return r

    def _page(self, recs, total, resultado_n, pages):
        return json.dumps({"ListaLlamados": recs, "Resultado": f"Mostrando TODOS los Llamados Abiertos ({resultado_n})", "cntPaginas": str(pages), "cntTotal": str(total)})

    def _run(self, mod, fn, served, **kw):
        import contextlib
        it = iter(served)
        asked = []

        def request(url, payload=None):
            asked.append((url, payload))
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(status=None, q=None, pages=None, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            fn(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), asked

    def test_the_walk_reaches_the_stated_count_and_a_repeated_id_is_not_counted_twice(self):
        mod = self._mod()
        p1 = self._page([self._rec(100 + i) for i in range(50)], total=52, resultado_n=99, pages=2)
        p2 = self._page([self._rec(149), self._rec(150), self._rec(151)], total=52, resultado_n=99, pages=2)
        rows, err, asked = self._run(mod, mod.cmd_list, [(200, p1), (200, p2)])
        self.assertEqual(len(rows), 52)
        self.assertIn("52 emitted over 2 page(s), site states 52 (status Abierto) — equal.", err)
        self.assertEqual(asked[0][1], {"llamadosFiltros": {"PaginaActual": 1, "CntPorPagina": 50, "ListaLlaEstWeb": ["Abierto"]}})
        self.assertEqual(asked[1][1]["llamadosFiltros"]["PaginaActual"], 2)

    def test_a_walk_short_of_the_stated_count_exits_partial_and_says_how_short(self):
        import contextlib
        mod = self._mod()
        p1 = self._page([self._rec(1), self._rec(2), self._rec(3)], total=5, resultado_n=5, pages=1)
        it = iter([(200, p1)])
        mod.request = lambda url, payload=None: next(it)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()) as err:
            mod.cmd_list(argparse.Namespace(status=None, q=None, pages=None, limit=None))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("3 emitted over 1 page(s), site states 5 (status Abierto) — 2 short.", err.getvalue())

    def test_a_bounded_walk_is_said_to_be_bounded_and_not_compared(self):
        mod = self._mod()
        p1 = self._page([self._rec(100 + i) for i in range(50)], total=363, resultado_n=363, pages=8)
        rows, err, asked = self._run(mod, mod.cmd_list, [(200, p1)], pages=1)
        self.assertEqual(len(rows), 50)
        self.assertIn("walk bounded by request", err)
        self.assertNotIn("short", err)

    def test_the_record_names_the_state_body_sums_the_posts_and_withholds_contacts(self):
        mod = self._mod()
        rec = self._rec(7, LlaReqExc="Enviar CV a concursos@fing.edu.uy o llamar al 099 123 456.", LlaRet="$60.610 nominales", LlaLugDes="Salto — consultas: salto@udelar.edu.uy")
