    def test_the_ad_reads_get_and_an_empty_list_is_gone(self):
        import contextlib
        mod = self._mod()
        served = iter([(200, json.dumps({"ListaLlamados": [self._rec(42528)]})), (200, json.dumps({"ListaLlamados": []}))])
        asked = []

