class AWebFormsSearchTurnsItsPagesByPostbackAndTheEmployerStaysBehindTheLogin(unittest.TestCase):
    """**`iskur.py`, 2026-09-13 (#381).** Türkiye's public agency is an
    ASP.NET WebForms page: a search is the form re-posted with one
    `__EVENTTARGET`, and every next page is the RESULTS form re-posted with
    `btnNext` (the pager echoes the page in `txtCurrentPage`). The rows are
    the share buttons' data attributes; «Toplam Kayıt: N» is printed beside
    every walk. The employer's name is behind a login and `employer` is
    null with the reason. Mutated (`-B`, detached copy): the event pair not
    stripped before re-posting → the walk case reddens (two targets on one
    request); `btnNext` swapped for `btnLast` → the walk case reddens (the
    pager check); the total regex broken → the walk case reddens (exit 6);
    the employer filled from the type → the login case reddens; `--il` not
    overriding the select → the province case reddens; the `__VIEWSTATE`
    check dropped → the firewall case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_iskur", os.path.join(SCRIPTS, "iskur.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _form(self, total=None, pages=None, cur=None, rows=()):
        head = ('<html><form><input type="hidden" name="__VIEWSTATE" value="vs"><input type="hidden" name="__EVENTVALIDATION" value="ev">'
                '<input type="hidden" name="__EVENTTARGET" value=""><input type="hidden" name="__EVENTARGUMENT" value="">'
                '<input type="text" name="ctl04$ctlArananMetin2" value=""><select name="ctl04$ctlIl"><option value="">--Tüm İller--</option><option value="1">ADANA</option><option value="34">İSTANBUL</option></select>'
                '<select name="ctl04$ctlCalismaYeri"><option value=""></option><option selected="selected" value="1">Yurtiçi</option></select>')
        body = ""
        if total is not None:
            body += f'<div>Sonraki Sayfa &gt; Son Sayfa &gt;&gt; <input type="text" name="ctl04$ctlDataPagerDetay$txtCurrentPage" value="{cur}"> / {pages} Sayfaya Git - Toplam Kayıt: {total}</div>'
        for ident, occ, il in rows:
            body += (f'<tr><td><a href="javascript:__doPostBack(\'x\',\'\')">{occ}</a><span>İşyeri adını görmek için Sisteme Üye Girişi yapmanız gerekmektedir.</span><span>Özel</span> / <span>Daimi</span> / <span>Tam Zamanlı</span></td>'
                     f'<td><a class="dropdown-toggle share-toggle" data-url=\'http://esube.iskur.gov.tr/Istihdam/AcikIsIlanDetay.aspx?uiID={ident}\' data-ilanno=\'{ident}\' data-sontarih=\'15.09.2026\' data-il=\'İl Geneli Başvuru ({il}) \' data-acikissayi=\'1\' data-isverentur=\'Özel\' data-calismasekli=\'Tam Zamanlı\' data-meslekler=\'{occ}\'></a></td></tr>')
        return head + body + "</form></html>"

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(url, data=None):
            sent.append((url, data))
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(il=None, pages=10, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_the_walk_posts_one_target_at_a_time_and_prints_the_stated_total(self):
        mod = self._mod()
        p1 = self._form(34049, 2270, 1, [(f"000098066{i:02d}", f"Meslek {i}", "ÇANKIRI / ŞABANÖZÜ") for i in range(15)])
        p2 = self._form(34049, 2270, 2, [(f"000098065{i:02d}", f"Meslek B{i}", "ANKARA / ÇANKAYA") for i in range(15)])
        rows, err, sent = self._run(mod, [(200, self._form()), (200, p1), (200, p2)], pages=2)
        self.assertEqual(len(rows), 30)
        self.assertEqual((rows[0]["id"], rows[0]["title"], rows[0]["employer"], rows[0]["employer_type"], rows[0]["work_type"], rows[0]["workplace"], rows[0]["positions"], rows[0]["application_deadline"]),
                         ("00009806600", "Meslek 0", None, "Özel", "Tam Zamanlı", "İl Geneli Başvuru (ÇANKIRI / ŞABANÖZÜ)", 1, "15.09.2026"))
        self.assertIn("login required", rows[0]["employer_hidden"])
        self.assertIn("30 emitted of the 34 049 the site states (all provinces), 2 270 page(s) of 15 — 2 walked by request", err)
        search, nxt = sent[1][1], sent[2][1]
        self.assertEqual([v for k, v in search if k == "__EVENTTARGET"], ["ctl04$ctlAcikIsPageCommand$CommandItem_Search"])
        self.assertEqual([v for k, v in nxt if k == "__EVENTTARGET"], ["ctl04$ctlDataPagerDetay$btnNext"])
        self.assertIn(("__VIEWSTATE", "vs"), nxt)
        self.assertIn(("ctl04$ctlDataPagerDetay$txtCurrentPage", "1"), nxt)

    def test_a_province_overrides_the_select_and_a_firewall_page_stops_the_run(self):
        import contextlib
        mod = self._mod()
        p1 = self._form(3847, 257, 1, [("00009806673", "Tekniker", "İSTANBUL / ÜSKÜDAR")])
        rows, err, sent = self._run(mod, [(200, self._form()), (200, p1)], il="34", pages=1)
        self.assertEqual([v for k, v in sent[1][1] if k == "ctl04$ctlIl"], ["34"])
        self.assertIn("(il 34)", err)
        # the form is served, then the search POST is answered by the firewall — the postback's own check catches it
        it = iter([(200, self._form()), (200, "<html><body>Request Rejected</body></html>")])
        mod.request = lambda url, data=None: next(it)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_search(argparse.Namespace(il=None, pages=1, limit=None))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("no __VIEWSTATE", e2.getvalue())

    def test_a_page_that_did_not_turn_is_a_fault(self):
        import contextlib
        mod = self._mod()
        p1 = self._form(34049, 2270, 1, [(f"000098066{i:02d}", f"M{i}", "X") for i in range(15)])
        same = self._form(34049, 2270, 1, [(f"000098067{i:02d}", f"N{i}", "X") for i in range(15)])   # new rows, but the pager still says 1
        it = iter([(200, self._form()), (200, p1), (200, same)])
        mod.request = lambda url, data=None: next(it)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_search(argparse.Namespace(il=None, pages=3, limit=None))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("the page did not turn", e2.getvalue())

    def test_the_detail_reads_what_is_public_and_names_what_is_behind_the_login(self):
        import contextlib
        mod = self._mod()
        page = ("<html><title>Türkiye İş Kurumu - İşgücü İstemi Detayı</title><div>İşgücü İstemi</div><p>İlan detaylarını görmek ve iş başvurusu yapmak için sisteme giriş yapınız.</p>"
                "<div>Meslek Bilgileri</div><table><tr><th>Meslek</th><th>Deneyim</th></tr><tr><td>Beden İşçisi (Genel)</td><td>Yıl</td></tr></table>"
                "<div>En Az Öğrenim Seviyesi</div><div>:</div><div>Okur Yazar Olmayan</div><div>En Fazla Öğrenim Seviyesi</div><div>:</div><div>×</div></html>")
        mod.request = lambda url, data=None: (200, page)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://esube.iskur.gov.tr/Istihdam/AcikIsIlanDetay.aspx?uiID=00009806651"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["title"], d["education_min"], d["education_max"], d["login_required_for"]),
                         ("00009806651", "Beden İşçisi (Genel)", "Okur Yazar Olmayan", None, ["employer", "description", "application"]))


class ASiteThatStatesItsCountWhenItRefusesToListAndHidesTheEmployerBehindALogin(unittest.TestCase):
    """**`vmp.py`, 2026-09-13 (#358).** Hungary's public service lists a
    search only when it is small enough; too large, it answers «A lista
    túl sok elemet tartalmaz (N)» — and that N is the board's own count,
    printed and exited on (6), never guessed around. A listed search is
    walked against «(N találat)», 50 a page. The employer is «Bejelentkezés
    után látható» on every row and stays null. `categories` sums the 25
    categories' counts, listed or refused, and calls the sum a bound. The
    detail states the salary as monthly gross HUF — the one unit stated on
    a card in this batch. Mutated (`-B`, detached copy): the refusal regex
    broken → the refusal case reddens (exit 6 for the wrong reason); the
    employer taken from the cell → the login case reddens; «(N találat)»
    regex broken → the walk case reddens; the dedup dropped → the walk case
    reddens; the category sum not counting refused ones → the categories
    case reddens; the salary unit set to null → the ad case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_vmp", os.path.join(SCRIPTS, "vmp.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @staticmethod
    def _row(ident, occ, edu="főiskola", place="Budapest 11. ker.", emp="<i>Bejelentkezés után látható</i>"):
        return f'<tr> <td><a href="/allas/reszletek/{ident}">{occ}</a></td> <td><a href="/allas/reszletek/{ident}">{edu}</a></td> <td><a href="/allas/reszletek/{ident}">{place}</a></td> <td> {emp} </td> </tr>'

    def _listed(self, n, rows):
        return f"<html><body><td>Találatok listája ({n} találat)</td><tbody>" + "".join(rows) + "</tbody></body></html>"

    REFUSED = "<html><body><li>A lista túl sok elemet tartalmaz (1806), kérjük, szűkítse az eredményt keresési feltételek meghatározásával!</li></body></html>"

    def _run(self, mod, fn, served, **kw):
        import contextlib
        it = iter(served)
        asked = []

        def get(url):
            asked.append(url)
            return next(it)
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(kulcsszo=None, helyseg=None, kategoria=None, isk=None, pages=None, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            fn(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), asked

    def test_a_listed_search_is_walked_against_its_count_and_the_employer_stays_null(self):
        mod = self._mod()
        p1 = self._listed(52, [self._row(600000 + i, f"{1000 + i} - Foglalkozás {i}") for i in range(50)])
        p2 = self._listed(52, [self._row(600049, "1049 - Foglalkozás 49"), self._row(600050, "1050 - Foglalkozás 50"), self._row(600051, "1051 - Foglalkozás 51")])
        rows, err, asked = self._run(mod, mod.cmd_search, [(200, p1), (200, p2)], helyseg="Budapest")
        self.assertEqual(len(rows), 52)
        self.assertEqual((rows[0]["id"], rows[0]["title"], rows[0]["feor"], rows[0]["employer"], rows[0]["education"], rows[0]["workplace"]), ("600000", "Foglalkozás 0", "1000", None, "főiskola", "Budapest 11. ker."))
        self.assertIn("login required", rows[0]["employer_hidden"])
        self.assertIn("52 emitted over 2 page(s), site states 52 (helyseg=Budapest) — equal.", err)
        self.assertIn("oldal=2", asked[1])

    def test_a_refused_search_prints_the_sites_count_and_stops(self):
        import contextlib
        mod = self._mod()
        mod.get = lambda url: (200, self.REFUSED)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as err:
            mod.cmd_search(argparse.Namespace(kulcsszo=None, helyseg=None, kategoria=None, isk=None, pages=None, limit=None))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("the site states 1 806 for this search and refuses to list it", err.getvalue())
        self.assertIn("narrow", err.getvalue())

    def test_categories_sum_listed_and_refused_counts_and_call_it_a_bound(self):
        mod = self._mod()
        served = [(200, self.REFUSED)] + [(200, self._listed(4, [self._row(1, "1 - a")])) if k % 2 else (200, "<html><li>A lista túl sok elemet tartalmaz (100), kérjük</li></html>") for k in range(1, 26)]
        rows, err, asked = self._run(mod, mod.cmd_categories, served)
        self.assertEqual(len(rows), 25)
        self.assertEqual(sum(r["count"] for r in rows), 13 * 4 + 12 * 100)
        self.assertIn("1 252 summed over 25 categories (13 listed, 12 refused with their count) — a sum of categories, an upper bound; the site states 1 806 unfiltered.", err)

    def test_the_detail_states_its_salary_unit_and_cuts_the_address_to_the_city(self):
        import contextlib
        mod = self._mod()
        lines = ["Általános irodai adminisztrátor - ügyintéző (8015711)", "Alapadatok", "A foglalkoztató részletes adatainak megjelenítéséhez kérjük jelentkezzen be!",
                 "Munkakör (FEOR)", "Általános irodai adminisztrátor", "Gyakorlati idő", "nincs", "Munkakör kiegészítése", "ügyintéző",
                 "Felajánlott havi bruttó kereset (Ft)", "373 200 - 0", "Munkavégzés helye", "1139 Budapest 13. ker. Teve út 4-6",
                 "Elvárt iskolai végzettség", "főiskola", "Megjegyzés", "Végzendő tevékenység:", "- adatok rögzítése", "Érvényesség időtartama", "2026.01.20 - 2026.09.25",
                 "Alkalmazni kívánt létszám", "40 fő", "Teljes/rész munkaidő (óra)", "8 / 0", "Munkarend", "kötött nappali munkavégzés"]
        page = "<html><body>" + "".join(f"<div>{l}</div>" for l in lines) + "</body></html>"
        mod.get = lambda url: (200, page)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://vmp.munka.hu/allas/reszletek/590506"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["title"], d["reference"], d["employer"], d["workplace"], d["salary_currency"], d["salary_min"], d["salary_max"], d["salary_unit"], d["salary_gross"], d["salary_unit_stated"], d["headcount"], d["valid_through"], d["hours"]),
                         ("Általános irodai adminisztrátor - ügyintéző", "8015711", None, "Budapest 13. ker.", "HUF", 373200, None, "MONTH", True, True, 40, "2026.09.25", "8 / 0"))
        self.assertEqual(d["description"], "Végzendő tevékenység:\n- adatok rögzítése")
        self.assertNotIn("Teve út", json.dumps(d))


class ARouteToNothingPrimesOverALivingScript(unittest.TestCase):
    """**#404, owner's decision of 2026-09-13: «un script qui ne rend rien ne
    compte pas et est classé comme infaisable».** `isinolsun.py` enumerates
    87 504 keys and no advertisement page answers on two clients; its card
    carries a living `script:` AND `route: none · <reason> · date`. In
    `bin/country-boards.py` the `route: none` line is read FIRST: such a
    card is «infaisable» — dated and motivated by its own line — never
    «fait», out of «faisable», named in the summary. Both directions: a
    living script WITHOUT a route line stays «fait». Mutated (`-B`, detached
    copy): the `route_none_of` check moved after the script check → the
    primed fixture is «fait» (reddens); `faisable` no longer subtracting the
    class → the ratio case reddens; the reason regex broken → the access
    label loses the reason (reddens)."""

    def _tool(self):
        spec = importlib.util.spec_from_file_location("_country_boards_404", os.path.join(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "bin", "country-boards.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def test_a_script_with_route_none_is_not_feasible_and_a_script_without_it_is_done(self):
        import tempfile
        mod = self._tool()
        d = tempfile.mkdtemp()

        def card(name, body):
            with open(os.path.join(d, name + ".md"), "w", encoding="utf-8") as fh:
                fh.write(body)
        head = "<!-- countries: XX -->\n<!-- content: measured · 87 504 keys enumerated, no page answers · 2026-09-13 -->\n<!-- witness: the sitemap · 2026-09-13 -->\n"
        card("primed", "# P\n\n<!-- script: primed.py -->\n" + head + "<!-- route: none · every advertisement page stalls without a byte on two clients · 2026-09-13 -->\n")
        card("living", "# L\n\n<!-- script: living.py -->\n" + head)
        card("walked", "# W\n\n<!-- script: none -->\n" + head + "<!-- route: browser · 12 · 2026-09-13 -->\n")
        cards = mod.read_cards(d)
        by = {c["name"]: c for c in cards}
        self.assertEqual(mod.route_none_of(by["primed"]), ("every advertisement page stalls without a byte on two clients", "2026-09-13"))
        self.assertIsNone(mod.route_none_of(by["living"]))
        self.assertIsNone(mod.route_none_of(by["walked"]))
        self.assertEqual(mod.classify(by["primed"]), ("infaisable", "2026-09-13"))
        self.assertEqual(mod.classify(by["living"])[0], "fait")
        self.assertEqual(mod.classify(by["walked"])[0], "fait")
        acc, basis = mod.access_of(by["primed"])
        self.assertIn("stalls without a byte", acc)
        self.assertIn("prime sur `script:`", basis)
        self.assertIn("NON FAISABLE", mod.status_of(by["primed"], "infaisable", "2026-09-13"))
        t = mod.table(cards, "XX")
        self.assertEqual((t["n"]["fait"], t["n"]["infaisable"], t["total"], t["faisable"]), (2, 1, 3, 2))
        self.assertEqual(t["named_inf"], ["primed"])
        self.assertIn("NON FAISABLES     1", mod.render_md("XX", t, cards))

    def test_the_repository_has_the_one_card_the_decision_was_taken_on(self):
        mod = self._tool()
        cards = mod.read_cards(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "shared", "boards"))
        by = {c["name"]: c for c in cards}
        self.assertEqual(mod.classify(by["isinolsun"])[0], "infaisable")
        self.assertEqual(by["isinolsun"]["h"].get("script"), "isinolsun.py")


class TheUsersOwnOverrideKeyIsReadForEveryBoardAndSaidOutLoud(unittest.TestCase):
    """**#403, owner's decision of 2026-09-13: «oui, l'utilisateur doit
    pouvoir émettre une dérogation en son âme et conscience».** The
    mechanism is general: `_robots.allowed()` flips a written «no» — and
    only a «no» — when the user's own `boards.<board>.override_robots: true`
    is set for the running adapter (`board_key()` from `sys.argv[0]`, or an
    explicit `board=`); it names the rule it crossed, and it prints the
    banner once per host and run, what is crossed before what it costs.
    Without the key the refusal stands and the result names the key as
    available. A test runner has no key. Mutated (`-B`, detached copy): the
    `is not False` test loosened to `if out["allowed"]` → the unreadable
    case reddens (a None is flipped); `on` ignored → the no-key case reddens
    (flipped without consent); the banner's per-host memory dropped → the
    once case reddens; `board_key()` returning the stem under a test runner →
    the runner case reddens."""

    def _refusing(self, host):
        return {"host": host, "requested_host": host, "sweep": False, "state": "read", "allow": [], "disallow": ["/api/"],
                "group": "*", "certain": True, "reason": "refused in writing"}

    def _with(self, verdict, enabled, argv0="tyomarkkinatori.py"):
        import contextlib
        real_v, real_e, real_argv = _robots.verdict, None, sys.argv[:]
        import _override
        real_e = _override.enabled
        _robots.verdict = verdict
        _override.enabled = enabled
        _robots._BANNERED.clear()
        sys.argv = [argv0]

        def restore():
            _robots.verdict = real_v
            _override.enabled = real_e
            sys.argv[:] = real_argv
            _robots._BANNERED.clear()
        return restore

    def test_without_the_key_the_refusal_stands_and_names_the_key(self):
        import contextlib
        restore = self._with(lambda h, agents=None: self._refusing(h), lambda board: (False, f"no boards.{board}.override_robots: true in /w/config.yml"))
        try:
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                a = _robots.allowed("tyomarkkinatori.fi", "/api/x")
            self.assertIs(a["allowed"], False)
            self.assertIn("boards.tyomarkkinatori.override_robots — absent", a["override_available"])
            self.assertEqual(err.getvalue(), "")
        finally:
            restore()

    def test_with_the_key_the_refusal_is_crossed_named_and_said_once_per_host(self):
        import contextlib
        restore = self._with(lambda h, agents=None: self._refusing(h), lambda board: (True, f"boards.{board}.override_robots: true in /w/config.yml"))
        try:
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                a = _robots.allowed("tyomarkkinatori.fi", "/api/x")
                b = _robots.allowed("tyomarkkinatori.fi", "/api/y")
                c = _robots.allowed("other.example", "/api/z")
            self.assertEqual((a["allowed"], a["kind"], a["overrode"]), (True, "override", "/"))
            self.assertTrue(b["allowed"])
            banner = err.getvalue()
            self.assertEqual(banner.count("ROBOTS REFUSAL CROSSED"), 2, banner)
            self.assertLess(banner.index("disallows"), banner.index("What it costs you"), "what is crossed comes before what it costs (#192)")
            self.assertIn("boards.tyomarkkinatori.override_robots: true in /w/config.yml", banner)
            self.assertIn("other.example", banner)
        finally:
            restore()

    def test_an_unreadable_file_is_not_a_refusal_to_cross_and_a_runner_has_no_key(self):
        import contextlib
        unknown = {"host": "h.example", "requested_host": "h.example", "sweep": None, "state": "unreachable", "certain": False, "reason": "could not be read"}
        restore = self._with(lambda h, agents=None: unknown, lambda board: (True, "boards.x.override_robots: true in /w/config.yml"))
        try:
            with contextlib.redirect_stderr(io.StringIO()):
                a = _robots.allowed("h.example", "/x")
            self.assertIsNone(a["allowed"])
            self.assertNotEqual(a.get("kind"), "override")
        finally:
            restore()
        real = sys.argv[:]
        try:
            sys.argv = ["hiringcafe.py"]
            self.assertEqual(_robots.board_key(), "hiringcafe")
            sys.argv = ["/usr/lib/python3/unittest/__main__.py"]
            self.assertIsNone(_robots.board_key())
            sys.argv = ["python3", "-m", "unittest"]
            self.assertIsNone(_robots.board_key())
            os.environ["JOB_HUNT_BOARD"] = "explicit"
            self.assertEqual(_robots.board_key(), "explicit")
        finally:
            sys.argv[:] = real
            os.environ.pop("JOB_HUNT_BOARD", None)


class ARouteRefusedInWritingIsTakenOnlyUnderTheUsersOwnKey(unittest.TestCase):
    """**`tyomarkkinatori.py`, 2026-09-13 (#371, on #403).** Every data route
    of Finland's public service is under `/api/`, refused in writing to `*`.
    Without `boards.tyomarkkinatori.override_robots: true` the adapter
    requests NOTHING and exits 7 naming the rule and the key; with it the
    guard (`allowed(..., board=)`) crosses, the banner is printed, and the
    widget's own POST is walked against `totalElements`. Exercised on a stub
    of the widget's schemas — no request was made under `/api/`; the key was
    absent on this machine by design. Mutated (`-B`, detached copy): the
    gate's `board=` dropped → the keyed case reddens (the guard never sees
    the key); the exit on refusal turned into a note → the no-key case
    reddens (a request goes out); the «equal» branch made unconditional →
    the short case reddens (inert on an equal-only fixture, so the walk case
    carries a 35-against-33 run too); the street address emitted → the ad case
    reddens; the 403/429 stop dropped → the block case reddens (exit 6, not
    7); the dedup dropped → the walk case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_tyomarkkinatori", os.path.join(SCRIPTS, "tyomarkkinatori.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _hit(self, u, title="Kirvesmies", muni="Helsinki", region="Uusimaa"):
        return {"id": u, "title": {"fi": title, "en": "Carpenter"}, "publishDate": "2026-09-13T06:00:00Z", "applicationPeriodEndDate": "2026-10-01T21:00:00Z",
                "employer": {"name": "Rakennus Oy", "businessId": ["1234567-8"]}, "employerType": "Organization",
                "location": {"address": {"streetAddress": "Mannerheimintie 1", "postalCode": "00100", "postOffice": "HELSINKI"},
                             "municipalities": [{"value": "091", "region": "01", "label": {"fi": muni}}], "regions": [{"value": "01", "label": {"fi": region}}]},
                "employmentRelationships": "Toistaiseksi voimassa oleva", "continuityOfWork": ["Vakituinen"], "workTime": "Kokoaikatyö", "tags": ["rakennus"],
                "applicationUrl": {"value": "https://example.fi/apply"}}

    def _resp(self, total, hits, pn):
        return json.dumps({"content": hits, "pageSize": 30, "totalElements": total, "pageNumber": pn, "totalPages": (total + 29) // 30})

    def _refuse(self, host, path, agents=None, board=None):
        out = {"host": host, "path": path, "allowed": False, "rule": "/api/", "kind": "path", "certain": True, "reason": "refused"}
        if board == "tyomarkkinatori" and getattr(self, "_key", False):
            out.update(allowed=True, kind="override", overrode="/api/")
        else:
            out["override_available"] = f"boards.{board or '?'}.override_robots — absent (no key in /w/config.yml)"
        return out

    def test_without_the_key_nothing_is_requested_and_the_exit_names_the_key(self):
        import contextlib
        mod = self._mod()
        self._key = False
        mod.robots_allowed = self._refuse
        sent = []
        mod.urllib.request.urlopen = lambda *a, **k: sent.append(a) or (_ for _ in ()).throw(AssertionError("a request left"))
        try:
            with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as err:
                mod.cmd_search(argparse.Namespace(q=None, pages=1, limit=None))
        finally:
            mod.urllib.request.urlopen = urllib_request_urlopen_original
        self.assertEqual(cm.exception.code, 7)
        self.assertIn("Disallow: /api/", err.getvalue())
        self.assertIn("boards.tyomarkkinatori.override_robots", err.getvalue())
        self.assertEqual(sent, [])

    def test_with_the_key_the_guard_is_asked_with_the_board_and_the_walk_meets_the_total(self):
        import contextlib
        mod = self._mod()
        self._key = True
        asked = []

        def guard(host, path, agents=None, board=None):
            asked.append(board)
            return self._refuse(host, path, agents, board)
        mod.robots_allowed = guard
        served = iter([(200, self._resp(33, [self._hit(f"0000000{i:d}-0000-4000-8000-000000000000".replace("0000000" + str(i), f"{i:08d}")) for i in range(30)], 0)),
                       (200, self._resp(33, [self._hit(f"{i:08d}-0000-4000-8000-000000000000") for i in range(29, 33)], 1))])
        mod.request = lambda url, payload=None: (mod.gate(url), next(served))[1]     # the guard is asked, as request() asks it
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(argparse.Namespace(q=None, pages=None, limit=None))
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        self.assertEqual(len(rows), 33)
        self.assertEqual((rows[0]["title"], rows[0]["title_language"], rows[0]["employer"], rows[0]["municipality"], rows[0]["region"], rows[0]["post_office"], rows[0]["employment"], rows[0]["application_url"]),
                         ("Kirvesmies", "fi", "Rakennus Oy", "Helsinki", "Uusimaa", "HELSINKI", "Toistaiseksi voimassa oleva", "https://example.fi/apply"))
        self.assertNotIn("Mannerheimintie", out.getvalue())
        self.assertIn("33 emitted over 2 page(s), site states 33 (no filter) — equal.", err.getvalue())
        self.assertEqual(set(asked), {"tyomarkkinatori"})
        # the same walk against a total of 35 is «2 short» — never «equal» (an equal-only fixture leaves the branch untested)
        served = iter([(200, self._resp(35, [self._hit(f"{i:08d}-0000-4000-8000-000000000000") for i in range(30)], 0)),
                       (200, self._resp(35, [self._hit(f"{i:08d}-0000-4000-8000-000000000000") for i in range(30, 33)], 1)),
                       (200, self._resp(35, [], 2))])
        mod.request = lambda url, payload=None: (mod.gate(url), next(served))[1]
        err2 = io.StringIO()
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err2):
            mod.cmd_search(argparse.Namespace(q=None, pages=None, limit=None))
        self.assertIn("site states 35 (no filter) — 2 short.", err2.getvalue())

    def test_a_block_stops_the_run_as_a_refusal_and_the_ad_drops_contacts(self):
        import contextlib
        mod = self._mod()
        self._key = True
        mod.robots_allowed = self._refuse
        mod.request = lambda url, payload=None: (429, "")
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_search(argparse.Namespace(q=None, pages=1, limit=None))
        self.assertEqual(cm.exception.code, 7)
        posting = dict(self._hit("0f0f0f0f-0000-4000-8000-000000000000"))
        posting.update({"description": {"fi": "Teemme puutöitä."}, "contactPersons": [{"name": "Matti", "phone": "040"}], "yhteystiedot": "x"})
        mod.request = lambda url, payload=None: (200, json.dumps(posting))
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(id="0f0f0f0f-0000-4000-8000-000000000000"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["description"], d["description_language"], sorted(d["contact_dropped"])), ("Teemme puutöitä.", "fi", ["contactPersons", "yhteystiedot"]))
        for secret in ("Matti", "040", "Mannerheimintie"):
            self.assertNotIn(secret, out.getvalue())


class AnApiThatAsksWhoIsCallingGetsTheUsersOwnAddressAndNothingElseEverSeesIt(unittest.TestCase):
    """**`hh.py`, 2026-09-13 (#337).** `api.hh.ru` requires a contact address
    on every request; the plugin never fabricates one. The adapter reads
    `boards.hh.contact` from the user's own config, sends it in
    `HH-User-Agent: claude-job-hunt/<v> (<contact>)` beside our UA, and
    prints it NOWHERE — not in the refusal, not in a row, not in a note.
    Without it: nothing requested, exit 7 saying what to write. `found` is
    the witness; the window ends at 2 000; a vacancy's `contacts` are
    dropped and listed. Measured 2026-09-13 18:52 UTC with the owner's key:
    403 `{"errors":[{"type":"forbidden"}]}` on all four areas, with the
    contact in either header — the API refuses this address, and the
    adapter stops. Mutated (`-B`, detached copy): the contact check moved
    after the guard → the no-key case reddens (a request leaves); the
    contact echoed in the 403 message → the secrecy case reddens; the
    header name changed → the header case reddens; `found` compared to the
    page count → the walk case reddens; `contacts` kept → the ad case
    reddens; the window check dropped → the window case reddens."""

    SECRET = "someone.private@example.org"

    def _mod(self, contact=None):
        spec = importlib.util.spec_from_file_location("_hh", os.path.join(SCRIPTS, "hh.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        mod.contact = (lambda: (contact, "boards.hh.contact in /w/config.yml")) if contact else (lambda: (None, "no boards.hh.contact in /w/config.yml"))
        mod.robots_allowed = lambda host, path, agents=None, board=None: {"allowed": True, "certain": True, "reason": "absent"}
        return mod

    def _item(self, i):
        return {"id": str(100000 + i), "name": f"Инженер {i}", "employer": {"id": "7", "name": "ООО Ромашка"}, "area": {"id": "16", "name": "Минск"},
                "salary": {"from": 2000, "to": 3000, "currency": "BYR", "gross": True}, "published_at": "2026-09-13T10:00:00+0300",
                "schedule": {"name": "Полный день"}, "experience": {"name": "1–3 года"}, "employment": {"name": "Полная занятость"},
                "snippet": {"requirement": "Опыт <highlighttext>Python</highlighttext>", "responsibility": "Разработка"},
                "alternate_url": f"https://rabota.by/vacancy/{100000 + i}", "professional_roles": [{"name": "Программист"}]}

    def test_without_the_contact_nothing_is_requested_and_the_exit_says_what_to_write(self):
        import contextlib
        mod = self._mod(None)
        sent = []
        # the guard's own rules fetch is a request too: without the contact, not even that leaves
        mod.robots_allowed = lambda host, path, agents=None, board=None: sent.append(("guard", host)) or {"allowed": True, "certain": True}
        mod.urllib.request.urlopen = lambda *a, **k: sent.append(a) or (_ for _ in ()).throw(AssertionError("a request left"))
        try:
            with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as err:
                mod.cmd_search(argparse.Namespace(area="16", text=None, pages=1, limit=None))
        finally:
            mod.urllib.request.urlopen = urllib_request_urlopen_original
        self.assertEqual(cm.exception.code, 7)
        self.assertIn("boards:", err.getvalue())
        self.assertIn("contact:", err.getvalue())
        self.assertEqual(sent, [])

    def test_the_contact_travels_in_the_header_and_appears_in_no_text(self):
        import contextlib
        mod = self._mod(self.SECRET)
        seen = []

        class R:
            def __init__(self, code, body): self.code, self.body, self.headers = code, body, {}
            def getcode(self): return self.code
            def read(self): return self.body
            def __enter__(self): return self
            def __exit__(self, *a): return False

        def urlopen(req, timeout=None):
            seen.append(dict(req.header_items()))
            return R(200, json.dumps({"found": 2, "pages": 1, "per_page": 100, "page": 0, "items": [self._item(1), self._item(2)]}).encode())
        mod.urllib.request.urlopen = urlopen
        mod.decode_body = lambda raw, headers: (raw.decode("utf-8"), "utf-8")
        out, err = io.StringIO(), io.StringIO()
        try:
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                mod.cmd_search(argparse.Namespace(area="16", text=None, pages=None, limit=None))
        finally:
            mod.urllib.request.urlopen = urllib_request_urlopen_original
        hdr = {k.lower(): v for k, v in seen[0].items()}
        self.assertEqual(hdr["hh-user-agent"], f"claude-job-hunt/{mod.version()} ({self.SECRET})")
        self.assertIn("Claude-User", hdr["user-agent"])
        self.assertNotIn(self.SECRET, out.getvalue() + err.getvalue(), "the contact left the adapter in a text")
        rows = [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")]
        self.assertEqual((rows[0]["country"], rows[0]["front"], rows[0]["employer"], rows[0]["salary_currency"], rows[0]["salary_gross"], rows[0]["salary_unit_stated"], rows[0]["requirement"]),
                         ("BY", "rabota.by", "ООО Ромашка", "BYR", True, False, "Опыт Python"))
        self.assertIn("2 emitted over 1 page(s), site states 2 (area 16 BY, rabota.by) — equal.", err.getvalue())
        # the same two items against a stated 3 are «1 short» — never «equal»
        mod.urllib.request.urlopen = lambda req, timeout=None: R(200, json.dumps({"found": 3, "pages": 1, "per_page": 100, "page": 0, "items": [self._item(1), self._item(2)]}).encode())
        err3 = io.StringIO()
        try:
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(err3):
                mod.cmd_search(argparse.Namespace(area="16", text=None, pages=None, limit=None))
        finally:
            mod.urllib.request.urlopen = urllib_request_urlopen_original
        self.assertIn("site states 3 (area 16 BY, rabota.by) — 1 short.", err3.getvalue())
        # a 403 names no address either
        mod.urllib.request.urlopen = lambda req, timeout=None: (_ for _ in ()).throw(mod.urllib.error.HTTPError(req.full_url, 403, "Forbidden", {}, io.BytesIO(b'{"errors":[{"type":"forbidden"}]}')))
        try:
            with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as e2:
                mod.cmd_search(argparse.Namespace(area="16", text=None, pages=1, limit=None))
        finally:
            mod.urllib.request.urlopen = urllib_request_urlopen_original
        self.assertEqual(cm.exception.code, 7)
        self.assertNotIn(self.SECRET, e2.getvalue())

    def test_the_window_ends_at_two_thousand_and_the_ad_drops_contacts(self):
        import contextlib
        mod = self._mod(self.SECRET)
        served = []

        def api(url):
            served.append(url)
            p = int(re.search(r"[?&]page=(\d+)", url).group(1))     # not `per_page=`
            return 200, {"found": 5000, "pages": 50, "per_page": 100, "page": p, "items": [self._item(p * 100 + i) for i in range(100)]}
        mod.api = api
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(argparse.Namespace(area="113", text=None, pages=None, limit=None))
        self.assertEqual(len(served), 20)
        self.assertNotIn("page=20", " ".join(served))
        self.assertIn("the API's window ends at 2 000 results", err.getvalue())
        vac = dict(self._item(5)); vac.update({"description": "<p>Мы ищем</p>", "key_skills": [{"name": "Python"}], "contacts": {"name": "Иван", "email": "ivan@x.by", "phones": [{"number": "123"}]}, "contact_person": "x"})
        mod.api = lambda url: (200, vac)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(id="100005"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["description"], d["key_skills"], d["contact_dropped"]), ("Мы ищем", ["Python"], ["contact_person", "contacts"]))
        for secret in ("Иван", "ivan@", "123"):
            self.assertNotIn(secret, out.getvalue())


class APublicBoardPagedByTheFormItsOwnPageSubmitsAndAnEmployerThatIsOnNeitherPage(unittest.TestCase):
    """**`jobseekers_bs.py`, 2026-09-13 (#447).** The Bahamas' Department of
    Labour runs a PCRecruiter board: the list is one GET, every next page is
    the page's own `googlePage` form re-posted with `morecount` set to
    `(p-1)*24 + "$$" + (p-1)` (the page's `goToPage` does exactly that), and
    the «a-b of N» heading is read back after every turn. The token `pcr-id`
    travels from the list to the detail address; a detail served without it
    is an empty shell. The employer is on neither page, `employer` is null
    with the reason; «$0.00 — $0.00» is the board's blank, never a salary.
    Mutated (`-B`, detached copy): `morecount` not rewritten → the turn case
    reddens (the heading did not move); the heading check dropped → the turn
    case reddens; the count regex broken → the walk case reddens (exit 6);
    the employer filled from the title → the walk case reddens; the blank
    salary emitted as 0.0 → the detail case reddens; the shell not refused
    → the shell case reddens."""

    TOKEN = "fHR4dC4Uvg0O%2Bx%3D"

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_jobseekers_bs", os.path.join(SCRIPTS, "jobseekers_bs.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _list(self, first, total, rows, morecount="24$$1"):
        head = ('<html><form name="returntoresults" id="returntoresults" method="POST" action="/pcrbin/jobboard.aspx"><input type="hidden" name="unifiedsearch" value=""></form>'
                f'<h1 class="litejobtitle" id="resultcount">{first}-{min(first + 23, total)} of {total}</h1>'
                '<form id="searchForm" action="/pcrbin/jobboard.aspx" method="post"><input class="form-control" type="text" id="Keyword" name="Keyword" value=""><select name="Island/State"><option value="">Island/State</option><option value="Exuma">Exuma</option></select>'
                '<input type="hidden" name="action" value="search"><input type="hidden" name="pcr-id" value="tok"><input type="hidden" name="locale" value=""></form><table>'
                '<tr><th>POSITION</th><th>LOCATION</th><th>TYPE</th><th>DATE POSTED</th></tr>')
        body = "".join(f'<tr><td><a href="/pcrbin/jobboard.aspx?action=detail&recordid={i}&pcr-id={self.TOKEN}">{t}</a></td><td>{isl}</td><td>Full-Time Regular</td><td>9/13/2026</td></tr>' for i, t, isl in rows)
        pager = ('</table><form name="googlePage" id="googlePage" action="/pcrbin/jobboard.aspx" method="post"><input type="hidden" name="action" value=""><input type="hidden" name="showjobs" value="Y">'
                 f'<input type="hidden" name="pcr-id" value="tok"><input name="morecount" type="hidden" value="{morecount}"><input name="sortorder" type="hidden" value=""><input name="unifiedsearch" type="hidden" value="||RC||key"></form></html>')
        return head + body + pager

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(url, data=None):
            sent.append((url, data))
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(island=None, keyword=None, pages=10, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_the_walk_turns_pages_by_the_pager_form_and_prints_the_stated_total(self):
        mod = self._mod()
        p1 = self._list(1, 50, [(f"1000{i:02d}", f"Cook {i}", "New Providence") for i in range(24)])
        p2 = self._list(25, 50, [(f"2000{i:02d}", f"Clerk {i}", "Grand Bahama") for i in range(24)])
        p3 = self._list(49, 50, [("300000", "Nurse", ""), ("300001", "Driver", "Exuma")])
        rows, err, sent = self._run(mod, [(200, p1), (200, p2), (200, p3)])
        self.assertEqual(len(rows), 50)
        self.assertEqual((rows[0]["id"], rows[0]["title"], rows[0]["employer"], rows[0]["island"], rows[0]["job_type"], rows[0]["posted"]),
                         ("100000", "Cook 0", None, "New Providence", "Full-Time Regular", "9/13/2026"))
        self.assertIn("Department of Labour mediates", rows[0]["employer_hidden"])
        self.assertEqual(rows[0]["url"], f"https://jobseekers.bahamas.gov.bs/pcrbin/jobboard.aspx?action=detail&recordid=100000&pcr-id={self.TOKEN}")
        self.assertIsNone(rows[48]["island"])   # an empty cell is null, not ""
        self.assertIn("50 emitted over 3 page(s), site states 50 (the whole board) — equal.", err)
        self.assertIn("`employer` is null on all 50", err)
        self.assertIsNone(sent[0][1])
        self.assertEqual([v for k, v in sent[1][1] if k == "morecount"], ["24$$1"])
        self.assertEqual([v for k, v in sent[2][1] if k == "morecount"], ["48$$2"])
        self.assertIn(("unifiedsearch", "||RC||key"), sent[1][1])
        self.assertIn(("showjobs", "Y"), sent[1][1])
        # bounded by request: the note says so
        rows, err, sent = self._run(mod, [(200, p1), (200, p2)], pages=2)
        self.assertEqual(len(rows), 48)
        self.assertIn("48 emitted of the 50 the site states (the whole board) — 2 page(s) of 24 walked by request", err)

    def test_a_page_that_did_not_turn_is_a_fault_and_a_missing_heading_too(self):
        import contextlib
        mod = self._mod()
        p1 = self._list(1, 50, [(f"1000{i:02d}", f"Cook {i}", "X") for i in range(24)])
        same = self._list(1, 50, [(f"2000{i:02d}", f"Clerk {i}", "X") for i in range(24)])   # new rows, the heading still says 1-24
        it = iter([(200, p1), (200, same)])
