class AWebflowRegisterWalkedPageByPageWhereWhatTheSiteHidesIsNotRead(unittest.TestCase):
    """**`empleos_pr.py`, 2026-09-13 (#441).** Puerto Rico's central register
    of public-service calls is a Webflow CMS site: every page is a GET, the
    list's query key is read off the page's own «Next Page» link, and the
    «Page N of M» pager is the witness (the site states no total). A block
    whose class carries `w-condition-invisible` is what the site hides —
    the closing date when the call is «Hasta Nuevo Aviso», the maximum
    salary when none is set — and it is not read as shown. The entity is
    the employer; the OATRH's footer address is never emitted. Mutated
    (`-B`, detached copy): the visibility check inverted → the hidden
    case reddens; the pager check dropped → the turn case reddens; the key
    assumed instead of read → the walk case reddens; the salary period not
    stated → the walk case reddens; the bound-empty section read → the
    detail case reddens; the footer not excluded (a contact regex added to
    the record) → the contact case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_empleos_pr", os.path.join(SCRIPTS, "empleos_pr.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _item(self, slug, title, agency="Universidad de Puerto Rico  (UPR)", region="San Juan", num="UPR-SEA-26-01AE", closing="September 30, 2026", ctype="", smin="1300.00", piloto=False):
        date_cls = "item-data fecha-cierre" if closing else "item-data fecha-cierre w-condition-invisible"
        hna_cls = "item-data fecha-cierre w-condition-invisible" if closing else "item-data fecha-cierre"
        type_cls = "item-data" if ctype else "item-data w-dyn-bind-empty"
        pil_cls = "div-block-27" if piloto else "div-block-27 w-condition-invisible"
        return (f'<div id="w-node-x" role="listitem" class="conv-collection-item w-dyn-item"><div><div con-item="titulo-puesto" fs-cmsfilter-field="titulo" class="item-title">{title}</div></div>'
                f'<div class="line-block data-agency"><div class="item-label">Entidad o Municipio</div><div con-item="agency-name" class="item-data agency-name">{agency}</div></div>'
                f'<div class="line-block data-agency"><div class="item-label">Región:</div><div con-item="region-name" class="item-data agency-name">{region}</div></div>'
                f'<div con-item="plan-piloto" class="{pil_cls}"><div>Convocatoria parte del Plan Piloto</div></div>'
                f'<div class="line-block"><div class="item-label numconvocatoria">Número de la Convocatoria</div><div con-item="jobNumber" class="item-data num-convocatoria-2">{num}</div></div>'
                f'<div class="line-block fecha-cierre right-side"><div class="item-label">Fecha de Cierre: </div><div data-filter="closing-date" class="{date_cls}">{closing}</div><div class="{hna_cls}">Hasta Nuevo Aviso</div></div>'
                f'<div class="line-block"><div class="item-label">Tipo de Convocatoria:</div><div con-item="external-internal" class="{type_cls}">{ctype}</div></div>'
                f'<div class="line-block btn-wrapper"><a href="/convocatorias/{slug}" class="link-block-3 w-inline-block"><div class="detail-btn"><div class="text-block-23">Ver detalles</div></div></a></div>'
                f'<div id="hiddein-fields" class="hiddein-fields"><div fs-cmsfilter-field="salario" class="salario-minimo">{smin}</div><div fs-cmsfilter-field="salario" class="salario-minimo w-dyn-bind-empty"></div></div></div>')

    def _page(self, page, pages, items, key="7a1b2c3d"):   # not the live key — a key assumed instead of read would post the wrong one
        nxt = f'<a href="?{key}_page={page + 1}" aria-label="Next Page" class="w-pagination-next next">Next</a>' if page < pages else ""
        return ('<html><body><div role="list" class="conv-collection-list w-dyn-items">' + "".join(items) + "</div>"
                f'<div role="navigation" aria-label="List" class="w-pagination-wrapper pagination">{nxt}<div aria-label="Page {page} of {pages}" role="heading" class="w-page-count page-count">{page} / {pages}</div></div>'
                '<div class="w-pagination-wrapper"><a href="?5c02fa81_page=2" aria-label="Next Page" class="w-pagination-next">Next</a></div>'   # the agency select's own pager — a second key on the same page
                '<div class="footer">Dirección Postal P.O Box 8476 San Juan, PR 00910-8476 Contáctenos Tel: (787) 274-4300 email: convocatorias@oatrh.pr.gov</div></body></html>')

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(url):
            sent.append(url)
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(pages=20, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_the_walk_reads_the_key_off_the_next_link_and_the_pager_is_the_witness(self):
        mod = self._mod()
        p1 = self._page(1, 3, [self._item(f"a-{i}", f"Puesto {i}", ctype="Externa" if i == 0 else "") for i in range(12)])
        p2 = self._page(2, 3, [self._item(f"b-{i}", f"Puesto B{i}", agency="Municipio de Corozal", smin="") for i in range(12)])
        p3 = self._page(3, 3, [self._item("c-0", "Head Start", closing="", num="Head Start 2020-21-004", piloto=True)])
        rows, err, sent = self._run(mod, [(200, p1), (200, p2), (200, p3)])
        self.assertEqual(len(rows), 25)
        self.assertEqual((rows[0]["id"], rows[0]["title"], rows[0]["employer"], rows[0]["region"], rows[0]["call_number"], rows[0]["call_type"], rows[0]["closing"], rows[0]["pilot_plan"]),
                         ("a-0", "Puesto 0", "Universidad de Puerto Rico (UPR)", "San Juan", "UPR-SEA-26-01AE", "Externa", "September 30, 2026", False))
        self.assertEqual((rows[0]["salary_min"], rows[0]["salary_currency"], rows[0]["salary_period"], rows[0]["salary_unit_stated"]), (1300.0, "USD", "MONTH", True))
        self.assertIsNone(rows[1]["call_type"])
        self.assertEqual((rows[12]["salary_min"], rows[12]["salary_unit_stated"]), (None, False))
        self.assertEqual((rows[24]["closing"], rows[24]["pilot_plan"]), ("Hasta Nuevo Aviso", True))   # the date block is hidden, the «Hasta Nuevo Aviso» block shown
        self.assertEqual(sent, ["https://www.empleos.pr.gov/", "https://www.empleos.pr.gov/?7a1b2c3d_page=2", "https://www.empleos.pr.gov/?7a1b2c3d_page=3"])
        self.assertIn("25 emitted over 3 page(s), site states 3 page(s) — every page walked", err)
        for r in rows:
            self.assertNotIn("oatrh.pr.gov", json.dumps(r))
            self.assertNotIn("787", json.dumps(r))
        rows, err, sent = self._run(mod, [(200, p1), (200, p2)], pages=2)
        self.assertEqual(len(rows), 24)
        self.assertIn("24 emitted over 2 of the 3 page(s) the site states — walked by request", err)

    def test_a_page_that_did_not_turn_is_a_fault(self):
        import contextlib
        mod = self._mod()
        p1 = self._page(1, 3, [self._item("a-0", "Puesto")])
        same = self._page(1, 3, [self._item("a-1", "Otro")])
        it = iter([(200, p1), (200, same)])
        mod.request = lambda url: next(it)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_list(argparse.Namespace(pages=20, limit=None))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("the page did not turn", e2.getvalue())

    def _detail(self, title="Secretaria Administrativa III", smax="", special_empty=True):
        smax_cls = 'class="data-block escala-salarial-2"' if smax else 'class="data-block escala-salarial-2 w-condition-invisible"'
        special = ('<div class="inner-section-title">Requisitos Especiales</div><div id="data-other-req" class="w-dyn-bind-empty w-richtext"></div>' if special_empty
                   else '<div class="inner-section-title">Requisitos Especiales</div><div id="data-other-req" class="w-richtext"><p>Licencia de conducir.</p></div>')
        return ('<html><body>'
                f'<div fs-cmsfilter-field="titulo" class="conv-title">{title}</div>'
                '<div class="line-block"><div class="item-label">Entidad o Municipio</div><div fs-cmsfilter-field="entidad-gubernamental" class="item-data">Universidad de Puerto Rico  (UPR)</div></div>'
                '<div fs-cmsfilter-field="region-pueblo" class="item-data">San Juan</div><div fs-cmsfilter-field="numero-convocatoria" class="item-data">UPR-SEA-26-01AE</div>'
                '<div fs-cmsfilter-field="tipo-convocatoria" class="item-data w-dyn-bind-empty"></div><div fs-cmsfilter-field="grupo-ocupacional" class="item-data">Profesional y Administrativo</div>'
                '<div class="line-block fecha-cierre"><div data-filter="closing-date" class="item-data fecha-cierre">September 30, 2026</div><div class="item-data fecha-cierre w-condition-invisible">Hasta Nuevo Aviso</div></div>'
                '<div class="data-block escala-salarial-2"><div class="data-jobopportunity-number">Salario Mínimo Mensual:  </div><div wfu-format="usd">1300.00</div><div class="text-block-43"> $ </div></div>'
                f'<div {smax_cls}><div class="data-jobopportunity-number">Salario Máximo Mensual:  </div><div wfu-format="usd">{smax}</div></div>'
                '<div class="data-block escala-salarial-2 w-condition-invisible"><div class="data-jobopportunity-number">Salario Mínimo Anual:  </div><div wfu-format="usd" class="w-dyn-bind-empty"></div></div>'
                '<div class="data-block escala-salarial-2"><div class="data-jobopportunity-number">Salario Autorizado para Reclutar:  </div><div wfu-format="usd">1706.50</div></div>'
                '<a href="#" class="external-request-btn-piloto w-condition-invisible w-button">Solicite a través de Eightfold.ai ❯</a>'
                '<div class="inner-section-title">Naturaleza del Trabajo:</div><div class="data-job-description w-richtext"><p>Trabajo secretarial de responsabilidad.</p><p>El empleado realizará las tareas.</p></div>'
                '<div class="inner-section-title">Condiciones de Trabajo:</div><div class="data-job-description w-richtext"><p>TIPO DE NOMBRAMIENTO</p></div>'
                '<div class="inner-section-title">Requisitos Mínimos</div><div class="data-minimun-req w-richtext"><p>Grado Asociado en Ciencias Secretariales.</p></div>'
                + special +
                '<div class="inner-section-title">Naturaleza del Examen</div><div class="w-dyn-bind-empty w-richtext"><p>This is some text inside of a div block.</p></div>'   # Webflow's placeholder in an unbound block — the site shows it, it is not the call's
                '<div class="inner-section-title">Notas Importantes</div><div class="rich-text-block-7 w-condition-invisible w-dyn-bind-empty w-richtext"></div>'
                '<div class="footer">Dirección Postal P.O Box 8476 San Juan, PR 00910-8476 Contáctenos Tel: (787) 274-4300 email: convocatorias@oatrh.pr.gov</div></body></html>')

    def test_the_detail_reads_what_is_shown_and_states_the_salary_period(self):
        import contextlib
        mod = self._mod()
        mod.request = lambda url: (200, self._detail())
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.empleos.pr.gov/convocatorias/upr-sea-26-01ae"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["title"], d["employer"], d["region"], d["call_number"], d["call_type"], d["occupational_group"], d["closing"]),
                         ("upr-sea-26-01ae", "Secretaria Administrativa III", "Universidad de Puerto Rico (UPR)", "San Juan", "UPR-SEA-26-01AE", None, "Profesional y Administrativo", "September 30, 2026"))
        self.assertEqual((d["salary_min"], d["salary_max"], d["salary_currency"], d["salary_period"], d["salary_unit_stated"], d["salary_authorised"]), (1300.0, None, "USD", "MONTH", True, 1706.5))
        self.assertEqual(d["nature_of_work"], "Trabajo secretarial de responsabilidad.\nEl empleado realizará las tareas.")
        self.assertEqual(d["minimum_requirements"], "Grado Asociado en Ciencias Secretariales.")
        self.assertEqual((d["special_requirements"], d["examination"], d["notes"]), (None, None, None))   # bound empty, or hidden — not read
        self.assertNotIn("oatrh.pr.gov", out.getvalue())
        self.assertNotIn("787", out.getvalue())
        # a maximum the site shows, and a special section with text
        mod.request = lambda url: (200, self._detail(smax="1900.00", special_empty=False))
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.empleos.pr.gov/convocatorias/upr-sea-26-01ae"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["salary_max"], d["special_requirements"]), (1900.0, "Licencia de conducir."))

    def test_what_the_site_hides_is_not_read_as_shown(self):
        mod = self._mod()
        # a maximum salary block the site hides, carrying a stale value — must not be read
        body = self._detail(smax="")
        body = body.replace('<div class="data-block escala-salarial-2 w-condition-invisible"><div class="data-jobopportunity-number">Salario Máximo Mensual:  </div><div wfu-format="usd"></div></div>',
                            '<div class="data-block escala-salarial-2 w-condition-invisible"><div class="data-jobopportunity-number">Salario Máximo Mensual:  </div><div wfu-format="usd">9999.00</div></div>')
        self.assertIn("9999.00", body)
        self.assertIsNone(mod.salary_block(body, "Salario Máximo Mensual:"))
        self.assertEqual(mod.salary_block(body, "Salario Mínimo Mensual:"), 1300.0)
        # the closing date: a hidden date block and a shown «Hasta Nuevo Aviso»
        card = self._item("c-0", "Head Start", closing="")
        self.assertEqual(mod.rows(self._page(1, 1, [card]))[0]["closing"], "Hasta Nuevo Aviso")
        self.assertEqual(mod.shown('<div class="x">yes</div>', "class", "x"), "yes")
        self.assertIsNone(mod.shown('<div class="x w-condition-invisible">no</div>', "class", "x w-condition-invisible"))   # a hidden block is never read, even when asked for by its full class

    def test_a_page_that_is_not_a_convocatoria_is_refused(self):
        import contextlib
        mod = self._mod()
        mod.request = lambda url: (200, "<html><body><h1>Page Not Found</h1></body></html>")
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_ad(argparse.Namespace(url="https://www.empleos.pr.gov/convocatorias/nope"))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("not a convocatoria page", e2.getvalue())
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.empleos.pr.gov/piloto-destrezas"))
        self.assertEqual(cm.exception.code, 2)


class AStateListReadAtTheMinuteTheHostAsksWhereTheCardIsThePostingAndTheDetailIsBare(unittest.TestCase):
    """**`govsr.py`, 2026-09-13 (#443).** Suriname's government site asks
    `crawl-delay: 60` and the adapter obeys (`_pace`); its WordPress REST
    route counts the register (`X-WP-Total`) but exposes no deadline, so the
    LIST CARDS are read — «Categorie», a summary, «Locatie», «Gepubliceerd»,
    «Inleverdatum tot», the «Meer info» PDF — and the posting's own page,
    which is bare, says so. The ministry is the employer; an e-mail inside
    a card's text is withheld. Mutated (`-B`, detached copy): the
    `X-WP-Total` header not read → the walk case reddens (no witness);
    the deadline label misread → the walk case reddens; the e-mail not
    withheld → the contact case reddens; the 404-past-the-end not treated
    as the end → the end case reddens (exit 6); the page-size stop dropped
    → the short-page case reddens; the ministry read from the slug instead
    of the menu → the detail case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_govsr", os.path.join(SCRIPTS, "govsr.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _card(self, pid, title, ministry="Ministerie van Natuurlijke Hulpbronnen", summary="Het Ministerie zoekt een consultant.", loc="Mr. Dr. J. C. de Mirandastraat 13-15 Paramaribo, Suriname", pub="07/09/2026", deadline="30/09/2026", pdf="https://gov.sr/wp-content/uploads/2026/09/TOR.pdf"):
        def li(t):
            return f'<li class="elementor-icon-list-item"><span class="elementor-icon-list-text">{t}</span></li>'
        lines = li(f"Categorie: {ministry}") + (li(summary) if summary else "") + (li(f"Locatie:   {loc}") if loc else "") + li("Locatie:  ") + li(f"Gepubliceerd: {pub}") + (li(f"Inleverdatum tot:  {deadline}") if deadline else "")
        return (f'<div data-elementor-type="loop" data-elementor-id="15459" class="elementor elementor-15459 post-{pid} vacature type-vacature status-publish hentry category-natuurlijke-hulpbronnen">'
                f'<h1 class="elementor-heading-title elementor-size-default">{title}</h1><ul class="elementor-icon-list-items">{lines}</ul>'
                + (f'<a class="elementor-button" href="{pdf}"><span>Meer info</span></a>' if pdf else "") + "</div>")

    def _page(self, cards, last=False):
        nav = "" if last else '<nav class="elementor-pagination"><a class="page-numbers" href="https://gov.sr/vacatures/2/">2</a></nav>'
        return "<html><body><header>menu</header>" + "".join(cards) + nav + "</body></html>"

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(url):
            sent.append(url)
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(pages=5, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_the_walk_reads_the_cards_and_the_register_count_is_the_witness(self):
        mod = self._mod()
        api = (200, "[]", {"X-WP-Total": "13", "X-WP-TotalPages": "3"})   # the two headers differ on purpose — a reader of the wrong one would still see a number
        p1 = self._page([self._card(100 + i, f"Vacature {i}") for i in range(6)])
        p2 = self._page([self._card(200 + i, f"Post {i}", deadline="", pdf="") for i in range(6)])
        p3 = self._page([self._card(300, "Laatste", summary="Stuur uw cv naar hr@gov.sr voor 1 oktober.")], last=True)
        rows, err, sent = self._run(mod, [api, (200, p1, {}), (200, p2, {}), (200, p3, {})])
        self.assertEqual(len(rows), 13)
        r = rows[0]
        self.assertEqual((r["id"], r["title"], r["employer"], r["workplace"], r["published"], r["application_deadline"], r["terms_of_reference"], r["url"]),
                         ("100", "Vacature 0", "Ministerie van Natuurlijke Hulpbronnen", "Mr. Dr. J. C. de Mirandastraat 13-15 Paramaribo, Suriname", "07/09/2026", "30/09/2026", "https://gov.sr/wp-content/uploads/2026/09/TOR.pdf", "https://gov.sr/?p=100"))
        self.assertEqual(r["summary"], "Het Ministerie zoekt een consultant.")
        self.assertEqual((rows[6]["application_deadline"], rows[6]["terms_of_reference"]), (None, None))
        self.assertEqual(rows[12]["summary"], "Stuur uw cv naar [e-mail withheld] voor 1 oktober.")   # a mailbox in a card's text never leaves
        self.assertNotIn("hr@gov.sr", json.dumps(rows))
        self.assertEqual(sent, ["https://gov.sr/wp-json/wp/v2/vacature?per_page=1", "https://gov.sr/vacatures/", "https://gov.sr/vacatures/2/", "https://gov.sr/vacatures/3/"])
        self.assertIn("13 emitted over 3 page(s), register states 13 — equal.", err)
        # bounded by request: the note says so and names the whole register's page count
        rows, err, sent = self._run(mod, [api, (200, p1, {})], pages=1)
        self.assertEqual(len(rows), 6)
        self.assertIn("6 emitted of the 13 the register states — 1 page(s) of 6 walked by request", err)
        self.assertIn("the whole register is --pages 3", err)

    def test_a_404_past_the_last_page_is_the_end_and_a_short_page_stops_the_walk(self):
        mod = self._mod()
        api = (200, "[]", {"X-WP-Total": "7", "X-WP-TotalPages": "2"})
        p1 = self._page([self._card(100 + i, f"V{i}") for i in range(6)])
        p2 = self._page([self._card(200, "Zeven")])
        rows, err, sent = self._run(mod, [api, (200, p1, {}), (200, p2, {})])
        self.assertEqual(len(rows), 7)
        self.assertEqual(len(sent), 3)   # the short page ended the walk — no page 3 asked
        # the register counts one more than the pages list (a posting the loop does not render): page 3 is the site's 404, and that is the end, not a fault
        api13 = (200, "[]", {"X-WP-Total": "13", "X-WP-TotalPages": "3"})
        p2full = self._page([self._card(200 + i, f"P{i}") for i in range(6)])
        rows, err, sent = self._run(mod, [api13, (200, p1, {}), (200, p2full, {}), (404, "", {})])
        self.assertEqual(len(rows), 12)
        self.assertEqual(len(sent), 4)
        self.assertIn("12 emitted over 2 page(s), register states 13 — 1 short.", err)
        # the count not readable: the walk goes on and says it has no witness
        rows, err, sent = self._run(mod, [(503, "", {}), (200, p1, {}), (200, p2, {})])
        self.assertEqual(len(rows), 7)
        self.assertIn("no count from the register", err)

    def test_the_detail_is_bare_and_says_so_and_the_ministry_comes_from_the_menu(self):
        import contextlib
        mod = self._mod()
        page = ('<html><body><div data-elementor-type="header" class="elementor elementor-9786 post-308 elementor-location-header">'   # the template wrapper's own post-N — not the posting's
                '<nav><ul><li><a href="https://gov.sr/ministeries/ministerie-van-landbouw-veeteelt-en-visserij/">Ministerie van Landbouw, Veeteelt en Visserij</a></li>'
                '<li><a href="https://gov.sr/ministeries/ministerie-van-natuurlijke-hulpbronnen/" class="elementor-sub-item">Ministerie van Natuurlijke Hulpbronnen</a></li></ul></nav>'
                '<div data-elementor-type="single-post" class="elementor post-161900 vacature type-vacature status-publish category-natuurlijke-hulpbronnen">'
                '<p>Ministerie van Natuurlijke Hulpbronnen</p><h1 class="elementor-heading-title elementor-size-default">Energy Awareness Consultant</h1>'
                '<div class="elementor-widget-theme-post-content"><div class="elementor-widget-container"></div></div></div></body></html>')
        mod.request = lambda url: (200, page, {})
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://gov.sr/vacature/energy-consultant/"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["title"], d["employer"], d["employer_slug"], d["detail_is_bare"]),
                         ("161900", "Energy Awareness Consultant", "Ministerie van Natuurlijke Hulpbronnen", "natuurlijke-hulpbronnen", True))
        mod.request = lambda url: (200, "<html><body><h1 class='x'>Pagina niet gevonden</h1></body></html>", {})
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_ad(argparse.Namespace(url="https://gov.sr/vacature/nope/"))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("not a vacature page", e2.getvalue())
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://gov.sr/vacatures/2/"))
        self.assertEqual(cm.exception.code, 2)

    def test_the_pace_is_the_hosts_sixty_seconds(self):
        """The adapter's own spacing is 3 s; the host writes 60 — the longer wins, and it is not this test's to shorten."""
        mod = self._mod()
        self.assertEqual(mod._PACE.own, 3.0)
        # the rules are cut from the network in this suite: the declared delay resolves to what `_robots` cached or nothing —
        # the assertion here is on the adapter's side of the contract: it hands the host to `Pace` and never sleeps on its own
        with open(os.path.join(SCRIPTS, "govsr.py"), encoding="utf-8") as fh:
            src = fh.read()
        self.assertIn('Pace(HOST, own=3.0)', src)
        self.assertNotIn("time.sleep", src)


def htmlmod_escape(t):
    import html as _h
    return _h.escape(t)


class AMunicipalBoardWhoseCardsAreRenderedByTheServerAndWhoseContactPersonNeverLeaves(unittest.TestCase):
    """**`kuntarekry.py`, 2026-09-13 (#373).** Finland's municipal recruitment
    service renders its job cards on the server (`<job-card …>` attributes)
    and marks its four promoted cards itself (`is-promoted="true"`, repeated
    on every page); the site's own counter (`?view=count&format=json`) is
    the witness and the `<ip-pagination current total>` is checked after
    every turn. The ad carries a JobPosting and a contact person — name,
    e-mail, telephone — in a block and often in the text: the block is not
    read and the text is scrubbed. Mutated (`-B`, detached copy): the
    promoted cards not skipped → the walk case reddens (28 not 24, a
    duplicate); the pager check dropped → the turn case reddens; the counter
    read from `total` instead of `count` → the walk case reddens (no
    witness); the e-mail scrub dropped → the contact case reddens; the phone
    scrub dropped → the contact case reddens; the filter not put on the
    counter's path → the filter case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_kuntarekry", os.path.join(SCRIPTS, "kuntarekry.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _card(self, jid, key, title, pc="Espoon kaupunki", promoted=False, end="28.9.2026", end_t="15:45"):
        flag = 'is-promoted="true" extended ' if promoted else ""   # built outside the f-string: Python 3.9 refuses a backslash inside one
        return (f'<li role="listitem"><job-card {flag}profit-center="{pc}" title="{title}" publication-date="14.9.2026" publication-time="00:01" '
                f'publication-end="{end}" publication-end-time="{end_t}" ext-id="{key}" url="/fi/tyopaikat/{title.lower().replace(" ", "-").replace(",", "")}-{key.lower()}/" job-id="{jid}" job-key="{key}"></job-card></li>')

    def _page(self, cur, total, cards, promoted=()):
        return ('<html><body><ip-section><ip-header>Tulokset<job-counter slot="aside" tags="[]"></job-counter></ip-header></ip-section>'
                '<ip-section odd><ip-header level="2">Mainostetut työpaikat</ip-header><job-list variant="col-2">' + "".join(promoted) + '</job-list></ip-section>'
                '<main><job-list variant="grid" ariaLabel="avointa työpaikkaa">' + "".join(cards) + '</job-list>'
                f'<ip-pagination prev="" next="/fi/tyopaikat/sivu{cur + 1}/" current="{cur}" total="{total}"></ip-pagination></main></body></html>')

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(url, accept=None):
            sent.append(url)
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(host=None, filter=None, pages=10, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_the_walk_skips_the_promoted_cards_and_the_counter_is_the_witness(self):
        mod = self._mod()
        promo = [self._card(9000 + i, f"PROMO-{i}", f"Mainos {i}", promoted=True) for i in range(4)]
        p1 = self._page(1, 3, [self._card(1000 + i, f"ESPOO-03-13{i:02d}-26", f"Opettaja {i}") for i in range(24)], promo)
        p2 = self._page(2, 3, [self._card(2000 + i, f"HKI-{i:02d}", f"Hoitaja {i}", pc="Helsingin kaupunki") for i in range(24)], promo)
        p3 = self._page(3, 3, [self._card(3000, "OULU-1", "Kirjastonhoitaja", pc="Oulun kaupunki", end="", end_t="")], promo)
        counter = (200, '{"count": 49, "total": 57}')   # a second number beside the count — a reader of the wrong key would still see one
        rows, err, sent = self._run(mod, [counter, (200, p1), (200, p2), (200, p3)])
        self.assertEqual(len(rows), 49)
        self.assertEqual((rows[0]["id"], rows[0]["key"], rows[0]["title"], rows[0]["employer"], rows[0]["posted"], rows[0]["application_deadline"], rows[0]["url"]),
                         ("1000", "ESPOO-03-1300-26", "Opettaja 0", "Espoon kaupunki", "14.9.2026", "28.9.2026 15:45", "https://kuntarekry.fi/fi/tyopaikat/opettaja-0-espoo-03-1300-26/"))
        self.assertIsNone(rows[48]["application_deadline"])
        self.assertFalse(any(r["title"].startswith("Mainos") for r in rows))
        self.assertEqual(sent[0], "https://kuntarekry.fi/fi/tyopaikat/?view=count&format=json")
        self.assertEqual(sent[1:], ["https://kuntarekry.fi/fi/tyopaikat/", "https://kuntarekry.fi/fi/tyopaikat/sivu2/", "https://kuntarekry.fi/fi/tyopaikat/sivu3/"])
        self.assertIn("49 emitted over 3 page(s), site counts 49 (kuntarekry.fi) — equal.", err)   # the host is named since #372 (Valtiolle by --host)
        rows, err, sent = self._run(mod, [counter, (200, p1), (200, p2)], pages=2)
        self.assertEqual(len(rows), 48)
        self.assertIn("48 emitted of the 49 the site counts (kuntarekry.fi) — 2 of 3 page(s) walked by request", err)

    def test_a_filter_is_a_path_segment_on_the_walk_and_on_the_counter(self):
        mod = self._mod()
        p1 = self._page(1, 1, [self._card(1000, "ESPOO-1", "Opettaja")])
        rows, err, sent = self._run(mod, [(200, '{"count": 1}'), (200, p1)], filter="espoo")
        self.assertEqual(len(rows), 1)
        self.assertEqual(sent, ["https://kuntarekry.fi/fi/tyopaikat/espoo/?view=count&format=json", "https://kuntarekry.fi/fi/tyopaikat/espoo/"])
        self.assertIn("(kuntarekry.fi, espoo)", err)

    def test_a_page_that_did_not_turn_is_a_fault_and_a_dead_counter_is_said(self):
        import contextlib
        mod = self._mod()
        p1 = self._page(1, 3, [self._card(1000 + i, f"K-{i}", f"T {i}") for i in range(24)])
        same = self._page(1, 3, [self._card(2000 + i, f"L-{i}", f"U {i}") for i in range(24)])
        it = iter([(200, '{"count": 48}'), (200, p1), (200, same)])
        mod.request = lambda url, accept=None: next(it)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_search(argparse.Namespace(host=None, filter=None, pages=10, limit=None))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("the page did not turn", e2.getvalue())
        rows, err, sent = self._run(mod, [(503, ""), (200, self._page(1, 1, [self._card(1, "A-1", "X")]))])
        self.assertEqual(len(rows), 1)
        self.assertIn("without a witness", err)

    def _ad(self, desc):
        ld = {"@context": "http://schema.org", "@type": "JobPosting", "title": "JOPO-luokan ohjaaja", "hiringOrganization": "Kristiinanseudun koulu",
              "jobLocation": {"@type": "Place", "address": {"@type": "PostalAddress", "addressRegion": "Pohjanmaa", "addressLocality": "Kristiinankaupunki", "postalCode": 64100, "streetAddress": "Asemakatu 4-6"}},
              "datePosted": "2026-09-11T16:00:00+03:00", "validThrough": "2026-09-28T23:59:00+03:00", "employmentType": "Osa-aikatyö, Määräaikainen",
              "baseSalary": {"@type": "MonetaryAmount", "currency": "EUR", "value": "Palkkaus määräytyy KVTES 5KOU62A1 mukaan, 2 312,36 e. Lisätiedot eeva@krs.fi"},
              "description": desc}
        return ('<html><head><script type="application/ld+json">' + json.dumps(ld, ensure_ascii=False) + '</script></head><body>'
                '<job-view job-ext-id="742318" job-title="JOPO-luokan ohjaaja"></job-view><main><p>' + htmlmod_escape(desc) + '</p>'
                '<section class="contact"><p>Eeva Kumpulainen eeva.kumpulainen@krs.fi, 0401598071</p></section></main></body></html>')

    def test_the_ad_reads_the_job_posting_and_no_contact_leaves_in_any_field(self):
        import contextlib
        mod = self._mod()
        desc = "Tervetuloa tiimiimme! Sijoituspaikka Kristiinanseudun koulu ajalle 1.10.2026-5.6.2027. Lisätietoja antaa rehtori Eeva Kumpulainen, eeva.kumpulainen@krs.fi, puh. 040 159 8071 tai +358 40 1598071. Hakuaika päättyy 28.9.2026 klo 23:59."
        mod.request = lambda url, accept=None: (200, self._ad(desc))
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://kuntarekry.fi/fi/tyopaikat/jopo-luokan-ohjaaja-742318/"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["key"], d["title"], d["employer"], d["workplace"], d["postal_code"], d["posted"], d["application_deadline"], d["employment_type"], d["salary_currency"], d["salary_unit_stated"], d["contacts_withheld"]),
                         ("742318", "JOPO-luokan ohjaaja", "Kristiinanseudun koulu", "Kristiinankaupunki, Pohjanmaa", "64100", "2026-09-11T16:00:00+03:00", "2026-09-28T23:59:00+03:00", "Osa-aikatyö, Määräaikainen", "EUR", False, True))
        raw = out.getvalue()
        for secret in ("krs.fi", "0401598071", "040 159 8071", "+358 40 1598071", "Kumpulainen eeva"):
            self.assertNotIn(secret, raw)
        self.assertIn("[e-mail withheld]", d["description"])
        self.assertIn("[telephone withheld]", d["description"])
        self.assertIn("1.10.2026-5.6.2027", d["description"])      # dates are not telephone numbers
        self.assertIn("28.9.2026 klo 23:59", d["description"])
        self.assertIn("[e-mail withheld]", d["salary_text"])
        self.assertIn("2 312,36 e", d["salary_text"])
        mod.request = lambda url, accept=None: (200, "<html><body>Sivua ei löytynyt</body></html>")
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://kuntarekry.fi/fi/tyopaikat/nope-1/"))
        self.assertEqual(cm.exception.code, 6)


class AnIndexThePageQueriesItselfWhereTheAppointedNameAndTheRefusingHostNeverLeave(unittest.TestCase):
    """**`trabajaenelestado.py`, 2026-09-13 (#302).** Chile's public-service
    calls are read from the Elasticsearch route the page posts to itself —
    the same `term` filters and page size, a plain sort in place of the
    page's Painless script, `hits.total` the witness. Records without the
    site's `ID Conv` (28 of 349 on the day) take the index's `_id` and say
    so. `Ganador` — the appointed person — is never emitted; the detail
    addresses on `www.empleospublicos.cl` (Disallow: /) are emitted as data
    and never fetched — there is no `ad` command. Mutated (`-B`, detached
    copy): the script sort restored → the query case reddens; the `_id`
    fallback dropped → the walk case reddens (short); `Ganador` emitted →
    the personal-data case reddens; `hits.total` read as the hit count →
    the walk case reddens; the window stop dropped → the window case
    reddens; the refusing-host note dropped → the address case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_trabajaenelestado", os.path.join(SCRIPTS, "trabajaenelestado.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _hit(self, esid, conv, cargo="Técnico en Enfermería", inst="Servicio de Salud Metropolitano Oriente", url=None, estado="postulacion", ganador=""):
        return {"_id": esid, "_source": {"ID Conv": conv, "Datesum": 753861, "Ministerio": "Ministerio de Salud", "Cargo": cargo, "Area de Trabajo": "Salud",
                                          "Fecha inicio Convocatoria": "27/05/2026 0:00:00", "Fecha cierre Convocatoria": "03/06/2026 23:59:00",
                                          "URL": url if url is not None else f"https://www.empleospublicos.cl/pub/convocatorias/convpostularavisoTrabajo.aspx?i={conv}&c=0&j=0",
                                          "Region": "Región Metropolitana de Santiago", "Ciudad": "Providencia", "Institucion/Entidad": inst, "Tipo Convocatoria": "EEPP",
                                          "Estado": estado, "Tipo Postulacion": "Postulacion en linea", "Cargo Profesional": "Técnicos", "Codigo Region": "region13", "Ganador": ganador}}

    def _page(self, hits, total):
        return (200, json.dumps({"took": 2, "hits": {"total": total, "hits": hits}}, ensure_ascii=False))

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(body):
            sent.append(body)
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(estado="postulacion", region=None, pages=10, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_the_walk_sends_the_pages_own_filters_with_a_plain_sort_and_the_total_is_the_witness(self):
        mod = self._mod()
        p1 = self._page([self._hit(f"es{i}", str(139000 + i)) for i in range(36)], 40)
        # four records without the site's id (the JUNJI feed), on another host — the index's own _id stands in
        p2 = self._page([self._hit(f"jj{i}", "", cargo=f"Ranking de Reemplazo {i}", inst="Junta Nacional de Jardines Infantiles", url=f"https://junji.myfront.cl/oferta-de-empleo/{19900 + i}/") for i in range(4)], 40)
        rows, err, sent = self._run(mod, [p1, p2])
        self.assertEqual(len(rows), 40)
        r = rows[0]
        self.assertEqual((r["id"], r["id_is_index_id"], r["title"], r["employer"], r["ministry"], r["region"], r["region_code"], r["city"], r["call_type"], r["opens"], r["closes"], r["status"]),
                         ("139000", False, "Técnico en Enfermería", "Servicio de Salud Metropolitano Oriente", "Ministerio de Salud", "Región Metropolitana de Santiago", "region13", "Providencia", "EEPP", "27/05/2026 0:00:00", "03/06/2026 23:59:00", "postulacion"))
        self.assertIn("Disallow: /", r["url_not_fetched"])
        self.assertEqual((rows[36]["id"], rows[36]["id_is_index_id"], rows[36]["url_not_fetched"]), ("jj0", True, None))
        self.assertIn("40 emitted over 2 page(s), index states 40 (Estado postulacion) — equal.", err)
        self.assertIn("36 of the 40 addresses are on www.empleospublicos.cl", err)
        q = sent[0]
        self.assertEqual((q["from"], q["size"], q["track_total_hits"]), (0, 36, True))
        self.assertEqual(q["query"], {"bool": {"must": [{"term": {"Estado": "postulacion"}}]}})
        self.assertNotIn("_script", json.dumps(q))      # a client does not send scripts to someone else's cluster
        self.assertEqual(q["sort"][0], {"Datesum": "asc"})
        self.assertEqual(sent[1]["from"], 36)
        rows, err, sent = self._run(mod, [self._page([self._hit("a", "1")], 1)], estado="finalizadas", region="region13")
        self.assertEqual(sent[0]["query"]["bool"]["must"], [{"term": {"Estado": "finalizadas"}}, {"term": {"Codigo Region": "region13"}}])
        rows, err, sent = self._run(mod, [self._page([self._hit("a", "1")], 1)], estado="todos")
        self.assertEqual(sent[0]["query"], {"match_all": {}})

    def test_the_appointed_person_never_leaves_and_a_bad_state_is_refused(self):
        import contextlib
        mod = self._mod()
        rows, err, sent = self._run(mod, [self._page([self._hit("a", "45483", estado="finalizadas", ganador="María José Pérez Soto")], 1)], estado="finalizadas")
        self.assertEqual(len(rows), 1)
        self.assertNotIn("Pérez", json.dumps(rows, ensure_ascii=False))
        self.assertNotIn("Ganador", json.dumps(rows))
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_list(argparse.Namespace(estado="abiertas", region=None, pages=10, limit=None))
        self.assertEqual(cm.exception.code, 2)
        self.assertFalse(hasattr(mod, "cmd_ad"))       # there is no detail command: the addresses are on a host that says no

    def test_the_window_stops_the_walk_and_a_total_in_es7_shape_is_read(self):
        mod = self._mod()
        mod.PAGE_SIZE = 2
        mod.WINDOW = 4
        pages = [self._page([self._hit(f"e{p}{i}", str(p * 10 + i)) for i in range(2)], 9) for p in range(3)]
        rows, err, sent = self._run(mod, pages, pages=50)
        self.assertEqual(len(rows), 4)                 # two pages of two, then the window
        self.assertEqual(len(sent), 2)
        self.assertIn("window ends at 4", err)
        self.assertIn("9 stated", err)
        mod.PAGE_SIZE, mod.WINDOW = 36, 10000
        es7 = (200, json.dumps({"hits": {"total": {"value": 1, "relation": "eq"}, "hits": [self._hit("z", "9")]}}))
        rows, err, sent = self._run(mod, [es7])
        self.assertEqual(len(rows), 1)
        self.assertIn("index states 1", err)


class AListingWhosePlaceAndDateAreTheIconsSpansAndWhoseHostIsOneOfTwentyOne(unittest.TestCase):
    """**`jobslin.py`, 2026-09-14 (#299).** One operator, one sub-host per
    country (`ph.` by default, `--host my` …): the listing states «a - b of
    N Job Vacancies» and turns by `?page=N`; the card's place and date are
    the spans its own icons label (a guess from the text once took a
    summary for a place); the salary is read with its sign and its period,
    and the period is stated only when printed; «Premium» is the operator's
    paid placement, kept and flagged. The ad is a JobPosting. Mutated (`-B`,
    detached copy): the place read from the first comma line → the place
    case reddens; the heading check dropped → the turn case reddens; the
    period stated without a printed one → the salary case reddens; the sign
    not mapped → the salary case reddens; `--host` ignored → the host case
    reddens; the premium flag dropped → the walk case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_jobslin", os.path.join(SCRIPTS, "jobslin.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _card(self, ident, title, emp="Cyberbacker", premium=False, place="Manila, National Capital Region", date="11/09/2026", sal="₱17,000.00", period="Monthly", tag="Full Time"):
        summ = "At Cyberbacker, we believe every career should have purpose, direction and a place in Makati, Metro Manila..."
        badge = '<span class="badge badge_premium mb-2 text-white font_4 px-3 rounded-2 py-1 fw-bold"><svg class="bi bi-award-fill"></svg>Premium</span>' if premium else ""
        salary = (f'<div class="col-12 col-md"><span class="font_1 fw-bold texto_celeste">{sal}</span>&nbsp; / {period}</div>' if period else
                  f'<div class="col-12 col-md"><span class="font_1 fw-bold texto_celeste">{sal}</span></div>') if sal else ""
        return (f'<div class="card"><div class="card-body"><a href="/job/{ident}/{title.lower().replace(" ", "-")}-in-ncr" data-enlace-oferta="1" class="text-decoration-none text-dark">{badge}'
                f'<div class="d-flex"><h5 class="fw-bold text-primary mb-0 font_2">{title}</h5><p class="text-secondary opacity-75 mb-0 small">{emp}</p></div>'
                f'<p class="pt-1 pb-xl-0 mb-0 mb-xl-1 text-dark fw-lighter font_4">{summ}</p>'
                f'<div class="d-flex gap-2 mb-2 mt-0"><span class="badge">{tag}</span><span class="badge">No Experience</span></div>'
                f'<div class="row"><div class="col"><svg class="bi bi-geo-alt me-2" viewBox="0 0 16 16"><path d="M8"/></svg><span class="text-dark">{place}</span></div><p>•</p>'
                f'<div class="col"><svg class="bi bi-calendar me-2" viewBox="0 0 16 16"><path d="M3"/></svg><span class="text-dark"> {date} </span></div>{salary}</div></a></div></div>')

    def _page(self, first, total, cards):
        last = min(first + 11, total)
        return (f'<html><body><h1>{first:,} - {last:,} of {total:,} Job Vacancies</h1>' + "".join(cards)
                + f'<nav><a href="/job-offers?t={total}&amp;page=2" rel="next">Next</a></nav></body></html>')

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(url):
            sent.append(url)
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(host="ph", pages=10, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_the_walk_reads_the_cards_by_their_icons_and_prints_the_stated_total(self):
        mod = self._mod()
        p1 = self._page(1, 25, [self._card(525944, "Financial Advisor", emp="Pru Life UK", premium=True, place="Quezon City, National Capital Region", date="12/09/2026", sal="₱10,000.00", period="Weekly", tag="Remote")]
                        + [self._card(528000 + i, f"Agent {i}") for i in range(11)])
        p2 = self._page(13, 25, [self._card(529000 + i, f"Clerk {i}", sal="", period="") for i in range(12)])
        p3 = self._page(25, 25, [self._card(530000, "Nurse", sal="₱30,000.00", period="")])
        rows, err, sent = self._run(mod, [(200, p1), (200, p2), (200, p3)])
        self.assertEqual(len(rows), 25)
        r = rows[0]
        self.assertEqual((r["id"], r["url"], r["title"], r["employer"], r["premium"], r["workplace"], r["posted"], r["tags"], r["salary"], r["salary_currency"], r["salary_period"], r["salary_unit_stated"]),
                         ("525944", "https://ph.jobslin.com/job/525944/financial-advisor-in-ncr", "Financial Advisor", "Pru Life UK", True, "Quezon City, National Capital Region", "12/09/2026", ["Remote", "No Experience"], 10000.0, "PHP", "WEEK", True))
        self.assertEqual((rows[1]["premium"], rows[1]["workplace"], rows[1]["salary_period"]), (False, "Manila, National Capital Region", "MONTH"))   # not the summary's «Makati, Metro Manila»
        self.assertEqual((rows[12]["salary"], rows[12]["salary_currency"], rows[12]["salary_unit_stated"]), (None, None, False))
        self.assertEqual((rows[24]["salary"], rows[24]["salary_period"], rows[24]["salary_unit_stated"]), (30000.0, None, False))   # an amount without a printed period
        self.assertEqual(sent, ["https://ph.jobslin.com/job-offers", "https://ph.jobslin.com/job-offers?page=2", "https://ph.jobslin.com/job-offers?page=3"])
        self.assertIn("25 emitted over 3 page(s), ph.jobslin.com states 25 — equal.", err)
        rows, err, sent = self._run(mod, [(200, p1), (200, p2)], pages=2)
        self.assertEqual(len(rows), 24)
        self.assertIn("24 emitted of the 25 ph.jobslin.com states — 2 page(s) of 12 walked by request", err)

    def test_the_host_is_the_operators_country_code_and_a_page_that_did_not_turn_is_a_fault(self):
        import contextlib
        mod = self._mod()
        p1 = self._page(1, 1, [self._card(1, "Cook", sal="RM2,500.00")])
        rows, err, sent = self._run(mod, [(200, p1)], host="my")
        self.assertEqual(sent, ["https://my.jobslin.com/job-offers"])
        self.assertEqual((rows[0]["country"], rows[0]["ledger_id"], rows[0]["url"], rows[0]["salary_currency"]), ("MY", "jobslin:my:1", "https://my.jobslin.com/job/1/cook-in-ncr", "MYR"))
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_search(argparse.Namespace(host="www", pages=1, limit=None))
        self.assertEqual(cm.exception.code, 2)
        p1 = self._page(1, 30, [self._card(100 + i, f"A {i}") for i in range(12)])
        same = self._page(1, 30, [self._card(200 + i, f"B {i}") for i in range(12)])
        it = iter([(200, p1), (200, same)])
        mod.request = lambda url: next(it)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_search(argparse.Namespace(host="ph", pages=10, limit=None))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("the page did not turn", e2.getvalue())

    def test_the_ad_is_its_job_posting(self):
        import contextlib
        mod = self._mod()
        ld = {"@context": "https://schema.org", "@graph": [{"@type": "WebPage", "name": "x"}, {"@type": "JobPosting", "title": "Technical Engineer", "description": "<p>Provides technical support. Write to hr@oceangoing.example for details.</p>", "datePosted": "2026-07-18", "validThrough": "2026-09-16", "employmentType": "FULL_TIME",
                                                          "hiringOrganization": {"@type": "Organization", "name": "Oceangoing"}, "totalJobOpenings": 1, "jobLocation": {"@type": "Place", "address": {"@type": "PostalAddress", "addressLocality": "Cagayan de Oro", "addressRegion": "Misamis Oriental", "addressCountry": "PH"}}}]}
        mod.request = lambda url: (200, '<html><head><script type="application/ld+json">' + json.dumps(ld) + '</script></head><body>x</body></html>')
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://ph.jobslin.com/job/508626/technical-engineer-in-misamis-oriental"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["country"], d["title"], d["employer"], d["workplace"], d["posted"], d["application_deadline"], d["employment_type"], d["openings"]),
                         ("508626", "PH", "Technical Engineer", "Oceangoing", "Cagayan de Oro, Misamis Oriental", "2026-07-18", "2026-09-16", "FULL_TIME", 1))
        self.assertIn("[e-mail withheld]", d["description"])
        self.assertNotIn("oceangoing.example", out.getvalue())
        mod.request = lambda url: (200, "<html><body>gone</body></html>")
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://ph.jobslin.com/job/1/x"))
        self.assertEqual(cm.exception.code, 6)


class AnEntryPageTheServerRendersEmptyAndACardWhoseFigureSitsInAStrong(unittest.TestCase):
    """**`jobscz.py`, 2026-09-14 (#351).** Jobs.cz renders its search cards
    on the server — except the country-wide page 1, which is the client-
    rendered entry page: the walk without a locality starts at page 2 and
    says so; with `--locality` every page is served from the first. The
    count «Našli jsme N nabídek» sits in a `<strong>` with a no-break
    space in the figure, so it is read from the page's text; a card's
    salary tag «45 000 – 60 000 Kč» is a range in CZK with no period. The
    ad's contact block (a person's name, an address, a telephone) is not
    read and the text is scrubbed. Mutated (`-B`, detached copy): the
    country walk started at page 1 → the country case reddens; the count
    read from the raw markup → the walk case reddens (no witness); the
    no-break space not stripped from figures → the salary case reddens;
    the search token kept on the address → the walk case reddens; the
    contact block read as the employer → the contact case reddens; the
    phone scrub dropped → the contact case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_jobscz", os.path.join(SCRIPTS, "jobscz.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _card(self, ident, title, emp="Fokus Labe, z.ú.", loc="Ústecký kraj + 3 další lokality", status="Přidáno včera", sal="45 000 &zwj;–&zwj; 60 000 Kč", tag="Odpovězte teď a budete mezi prvními"):
        tags = (f'<span   class="Tag Tag--success Tag--small Tag--subtle"\n>   {sal}  </span>' if sal else "") + (f'<span class="Tag Tag--neutral Tag--small Tag--subtle" >{tag}</span>' if tag else "")
        return (f'<article\n    class="SearchResultCard"\n\n><header class="SearchResultCard__header" ><h2 data-test-ad-title="{title}" class="SearchResultCard__title" >'
                f'<a data-jobad-id="{ident}" data-link="jd-detail" href="https://www.jobs.cz/rpd/{ident}/?searchId=d7d9260e-a342&amp;rps=233" class="link-primary SearchResultCard__titleLink" > {title} </a></h2>'
                f'<div data-test-ad-status="default" class="SearchResultCard__status" > {status} </div></header><div class="SearchResultCard__body" >{tags}</div>'
                f'<footer class="SearchResultCard__footer" ><ul class="SearchResultCard__footerList"><li class="SearchResultCard__footerItem" > <svg></svg> <span translate="no">{emp}</span> </li>'
                f'<li data-test="serp-locality" class="SearchResultCard__footerItem" > <svg></svg> {loc} </li></ul></footer></article>')

    def _page(self, total, cards, entry=False):
        if entry:
            return '<html><body><div class="SearchNoUserInputEntry">Nabídky práce</div></body></html>'
        return f'<html><body><p>Našli jsme <strong>{total:,}</strong> nabídek</p>'.replace(",", " ") + "".join(cards) + '<nav><ul class="Pagination"><li><a href="/prace/?page=2">2</a></li></ul></nav></body></html>'

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(url):
            sent.append(url)
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(locality=None, pages=10, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_a_locality_is_walked_from_page_one_and_the_count_is_read_from_the_text(self):
        mod = self._mod()
        p1 = self._page(35, [self._card(2001424000 + i, f"Sestra {i}") for i in range(30)])
        p2 = self._page(35, [self._card(2001425000 + i, f"Lékař {i}", sal="", tag="") for i in range(5)])
        rows, err, sent = self._run(mod, [(200, p1), (200, p2)], locality="praha")
        self.assertEqual(len(rows), 35)
        r = rows[0]
        self.assertEqual((r["id"], r["url"], r["title"], r["employer"], r["workplace"], r["status"], r["tags"], r["salary_min"], r["salary_max"], r["salary_currency"], r["salary_unit_stated"]),
                         ("2001424000", "https://www.jobs.cz/rpd/2001424000/", "Sestra 0", "Fokus Labe, z.ú.", "Ústecký kraj + 3 další lokality", "Přidáno včera", ["Odpovězte teď a budete mezi prvními"], 45000, 60000, "CZK", False))
        self.assertNotIn("searchId", r["url"])
        self.assertEqual((rows[30]["salary_min"], rows[30]["tags"]), (None, []))
        self.assertEqual(sent, ["https://www.jobs.cz/prace/praha/", "https://www.jobs.cz/prace/praha/?page=2"])
        self.assertIn("35 emitted over 2 page(s), site states 35 (praha) — equal.", err)
        rows, err, sent = self._run(mod, [(200, p1)], locality="praha", pages=1)
        self.assertIn("30 emitted of the 35 the site states (praha) — 1 page(s) of 30 walked by request", err)

    def test_the_country_walk_starts_at_page_two_because_page_one_is_the_clients(self):
        mod = self._mod()
        p2 = self._page(16019, [self._card(1000 + i, f"A {i}") for i in range(30)])
        p3 = self._page(16019, [self._card(2000 + i, f"B {i}") for i in range(30)])
        rows, err, sent = self._run(mod, [(200, p2), (200, p3)], pages=2)
        self.assertEqual(len(rows), 60)
        self.assertEqual(sent, ["https://www.jobs.cz/prace/?page=2", "https://www.jobs.cz/prace/?page=3"])
        self.assertIn("rendered on the client", err)
        self.assertIn("60 emitted of the 16 019 the site states (the whole country) — 2 page(s) of 30 walked by request", err)
        # the entry page served where a list was expected: no count, no card — the walk says the site lists nothing rather than inventing
        rows, err, sent = self._run(mod, [(200, self._page(0, [], entry=True))], locality="nowhere")
        self.assertEqual(rows, [])
        self.assertIn("the site lists nothing", err)

    def _ad(self):
        return ('<html><body><h1 class="typography-heading-large-text">Všeobecná / psychiatrická sestra</h1>'
                '<a data-test="jd-info-location" href="https://www.mapy.cz/?q=x" class="link-secondary" >Ústecký kraj</a>'
                '<div data-test="jd-salary" class="IconWithText" ><svg></svg><span class="accessibility-hidden" > Plat </span><p>45 000 &zwj;–&zwj; 60 000 Kč</p></div>'
                '<div data-test="jd-info-item" class="IconWithText" ><svg></svg><span class="accessibility-hidden" > Společnost </span><p>Fokus Labe, z.ú.</p></div>'
                '<div data-test="jd-info-item" class="IconWithText" ><svg></svg><p class="text-secondary"> Typ pracovního poměru </p><p>Práce na plný úvazek</p></div>'
                '<div data-test="jd-benefits" class="IconWithText mb-600" ><svg></svg><p>Mobilní telefon</p></div>'
                '<div data-jobad="body" data-test="jd-body-richtext" class="RichContent mb-1400" ><p>Pracovní nabídka</p><p>Hledáme sestru. Volejte 777 245 947 nebo pište na jana@fokuslabe.cz, případně +420 601 234 567.</p></div>'
                '<div class="mb-1400"><p>Kontaktní údaje</p><a data-test="jd-contact-company" href="/jof/1/" > Martina Vojtíšková </a>'
                '<span itemprop="address" data-test="jd-contact-address">Soumarská 1541/8, 14000 Praha 10</span><p data-test="jd-contact-phone" > 777 245 947 </p></div></body></html>')

    def test_the_ad_reads_the_page_and_the_contact_block_never_leaves(self):
        import contextlib
        mod = self._mod()
        mod.request = lambda url: (200, self._ad())
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.jobs.cz/rpd/2001424002/?searchId=abc&rps=233"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["url"], d["title"], d["employer"], d["workplace"], d["salary_text"], d["salary_min"], d["salary_max"], d["salary_currency"], d["benefits"], d["contacts_withheld"]),
                         ("2001424002", "https://www.jobs.cz/rpd/2001424002/", "Všeobecná / psychiatrická sestra", "Fokus Labe, z.ú.", "Ústecký kraj", "45 000 – 60 000 Kč", 45000, 60000, "CZK", ["Mobilní telefon"], True))
        self.assertEqual(d["info"], ["Typ pracovního poměru\nPráce na plný úvazek"])
        self.assertEqual(d["description"], "Hledáme sestru. Volejte [telephone withheld] nebo pište na [e-mail withheld], případně [telephone withheld].")
        raw = out.getvalue()
        for secret in ("Vojtíšková", "Soumarská", "777 245 947", "fokuslabe.cz", "601 234 567"):
            self.assertNotIn(secret, raw)
        mod.request = lambda url: (200, "<html><body><h1>Stránka nenalezena</h1></body></html>")
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.jobs.cz/rpd/1/"))
        self.assertEqual(cm.exception.code, 6)


class ACardThatNamesItsOwnFieldsAndAnAdThatMayLiveOnTheEmployersHost(unittest.TestCase):
    """**`pracecz.py`, 2026-09-14 (#353).** Prace.cz renders its listing from
    page 1 with cards that label their own fields (hidden «Lokalita:»,
    «Název firmy:», «Typ úvazku:», «Plat:» — the salary printed with its
    period, «Kč/měsíc»); a card's link is one of three shapes and the UUID
    is the id in all of them; an employer-hosted ad's site address
    redirects to the employer's own host, which `ad` refuses to read. The
    JobPosting's `QuantitativeValue` carries the unit. The contact block
    never leaves. Mutated (`-B`, detached copy): the UUID read from the
    site's shape only → the walk case reddens (13 cards lost); the period
    stated without a printed one → the salary case reddens; the redirect
    to another host followed → the redirect case reddens; the unit taken
    from the QuantitativeValue dropped → the ad case reddens; the e-mail
    scrub dropped → the ad case reddens; the count read from the raw
    markup → the walk case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_pracecz", os.path.join(SCRIPTS, "pracecz.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _card(self, uuid, title, emp="LAMPS, a.s.", loc="Praha-Horní Počernice", typ="Plný úvazek", plat="35&nbsp;000 – 45&nbsp;000 Kč/měsíc", shape="site"):
        href = {"site": f"/nabidka/{uuid}/?rps=2078", "firm": f"/firma/3gxr37-fast-cr-a-s/nabidka/{uuid}/?rps=2077", "employer": f"https://o2.jobs.cz/pd/2000555295?originJobAdUuid={uuid}&amp;rps=2078"}[shape]
        li = '<li class="Flex"><span class="accessibility-hidden">{}<!-- -->:</span><span class="typography-body-medium-regular text-wrap-pretty">{}<span class="JobCardDescription__delimiter" aria-hidden="true"></span></span></li>'
        plat_li = f'<li class="Flex"><svg></svg><span class="typography-body-medium-semibold text-primary"><span class="accessibility-hidden">Plat<!-- -->:</span>{plat}</span></li>' if plat else ""
        return (f'<article class="JobCard-module-scss-module__ki5xOq__JobCard"><header><h2 data-testid="job-card-title" class="JobCardTitle"><a data-testid="advert-link" class="link-primary" href="{href}">{title}</a></h2></header>'
                f'<div class="JobCardBody"><ul>{li.format("Lokalita", loc)}{li.format("Název firmy", emp)}{li.format("Typ úvazku", typ)}</ul><ul>{plat_li}</ul></div></article>')

    def _page(self, total, cards):
        return f'<html><body><h1>Našli jsme <strong>{total:,}</strong> nabídek</h1>'.replace(",", "&nbsp;") + '<article class="Card">not a job</article>' + "".join(cards) + '<nav><a href="?page=2">2</a></nav></body></html>'

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(url):
            sent.append(url)
            code, body = next(it)
            return code, body, url
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(pages=10, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_the_walk_reads_every_link_shape_and_the_labelled_fields(self):
        mod = self._mod()
        u = lambda i: f"{i:08x}-5c6b-43ad-9aeb-eeca4f63bc0e"
        p1 = self._page(45, [self._card(u(i), f"Skladník {i}") for i in range(20)] + [self._card(u(100 + i), f"Asistent {i}", emp="O2 Czech Republic a.s.", shape="employer", plat="") for i in range(13)] + [self._card(u(200 + i), f"Prodavač {i}", emp="FAST ČR, a.s.", shape="firm", plat="26&nbsp;000 Kč") for i in range(7)])
        p2 = self._page(45, [self._card(u(300 + i), f"Řidič {i}", plat="180 Kč/hod") for i in range(5)])
        rows, err, sent = self._run(mod, [(200, p1), (200, p2)])
        self.assertEqual(len(rows), 45)
        r = rows[0]
        self.assertEqual((r["id"], r["url"], r["hosted_by_employer"], r["title"], r["employer"], r["workplace"], r["employment"], r["salary_text"], r["salary_min"], r["salary_max"], r["salary_currency"], r["salary_period"], r["salary_unit_stated"]),
                         (u(0), f"https://www.prace.cz/nabidka/{u(0)}/", None, "Skladník 0", "LAMPS, a.s.", "Praha-Horní Počernice", "Plný úvazek", "35 000 – 45 000 Kč/měsíc", 35000, 45000, "CZK", "MONTH", True))
        self.assertEqual((rows[20]["id"], rows[20]["hosted_by_employer"], rows[20]["url"], rows[20]["salary_min"]), (u(100), "o2.jobs.cz", f"https://www.prace.cz/nabidka/{u(100)}/", None))
        self.assertEqual((rows[33]["id"], rows[33]["salary_min"], rows[33]["salary_max"], rows[33]["salary_period"], rows[33]["salary_unit_stated"]), (u(200), 26000, 26000, None, False))
        self.assertEqual((rows[40]["salary_min"], rows[40]["salary_period"]), (180, "HOUR"))
        self.assertEqual(sent, ["https://www.prace.cz/nabidky/", "https://www.prace.cz/nabidky/?page=2"])
        self.assertIn("45 emitted over 2 page(s), site states 45 — equal.", err)
        rows, err, sent = self._run(mod, [(200, p1)], pages=1)
        self.assertIn("40 emitted of the 45 the site states — 1 page(s) of 40 walked by request", err)

    def _ad(self):
        ld = {"@context": "https://schema.org", "@type": "JobPosting", "title": "Práce ve skladu", "description": "<p>Velkoobchod hraček přijme skladníka. Životopis na hr@lamps.example, tel. 777 123 456.</p>",
              "identifier": {"@type": "PropertyValue", "name": "LAMPS, a.s.", "value": "d224qy"}, "datePosted": "2026-08-24T13:49:26+02:00", "validThrough": "2026-09-23T23:59:59+02:00", "employmentType": ["FULL_TIME", "EMPLOYEE"],
              "hiringOrganization": {"@type": "Organization", "name": "LAMPS, a.s."}, "jobLocation": {"@type": "Place", "address": {"@type": "PostalAddress", "streetAddress": "Ve žlíbku", "addressLocality": "Praha", "postalCode": "19300", "addressCountry": "CZE"}},
              "baseSalary": {"@type": "MonetaryAmount", "currency": "CZK", "value": {"@type": "QuantitativeValue", "minValue": 35000, "maxValue": 45000, "unitText": "MONTH"}}}
        return ('<html><head><script type="application/ld+json">' + json.dumps(ld, ensure_ascii=False) + '</script></head><body><main><h1>Práce ve skladu</h1>'
                '<ul><li data-testid="benefit-item-1">Příspěvek na dovolenou</li><li data-testid="benefit-item-2">Mobilní telefon</li></ul>'
                '<section><h2>Kontaktní údaje</h2><p>Jana Nováková</p><p>Ve žlíbku 2906/1b, 19300 Praha 9</p><p>+420 777 123 456</p></section></main></body></html>')

    def test_the_ad_is_its_job_posting_with_the_unit_the_page_states_and_no_contact(self):
        import contextlib
        mod = self._mod()
        uid = "a94cd5e8-5c6b-43ad-9aeb-eeca4f63bc0e"
        mod.request = lambda url: (200, self._ad(), url)
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url=f"https://www.prace.cz/firma/x/nabidka/{uid}/?rps=1"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["id"], d["url"], d["title"], d["employer"], d["workplace"], d["posted"], d["employment_type"], d["salary_min"], d["salary_max"], d["salary_currency"], d["salary_period"], d["salary_unit_stated"], d["benefits"], d["contacts_withheld"]),
                         (uid, f"https://www.prace.cz/nabidka/{uid}/", "Práce ve skladu", "LAMPS, a.s.", "Praha, 19300", "2026-08-24T13:49:26+02:00", "FULL_TIME, EMPLOYEE", 35000, 45000, "CZK", "MONTH", True, ["Příspěvek na dovolenou", "Mobilní telefon"], True))
        self.assertEqual(d["description"], "Velkoobchod hraček přijme skladníka. Životopis na [e-mail withheld], tel. [telephone withheld].")
        for secret in ("Nováková", "lamps.example", "777 123 456", "2906/1b"):
            self.assertNotIn(secret, out.getvalue())
        # an employer-hosted ad: the site's address answers 200 from another host — not read
        mod.request = lambda url: (200, "<html><body>Detail pozice | O2</body></html>", "https://o2.jobs.cz/detail-pozice?r=detail&id=2001350573&originJobAdUuid=" + uid)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_ad(argparse.Namespace(url=f"https://www.prace.cz/nabidka/{uid}/"))
        self.assertEqual(cm.exception.code, 6)
        self.assertIn("redirected to o2.jobs.cz", e2.getvalue())
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.prace.cz/nabidky/"))
        self.assertEqual(cm.exception.code, 2)


class AWholeBoardInOneAnswerWhereTheCountIsPositionsAndTheContactsAreAField(unittest.TestCase):
    """**`jobbnorge.py`, 2026-09-14 (#366).** Norway's public-sector board
    serves every open posting in one API answer (`/v3/jobs`), and its
    counter (`/v1/jobs/count`) counts POSITIONS — the page itself sums
    `positionCount` — so the adapter prints postings emitted, positions
    summed and positions counted, «equal» when the sum is the count. The
    employer is the department when the site says so
    (`regardDepartmentAsEmployer`). The ad's data route carries
    `contacts` — persons with telephones — never emitted; the text is
    scrubbed. Mutated (`-B`, detached copy): the count compared to the
    number of postings → the walk case reddens; the duplicate id kept →
    the walk case reddens; the department not taken as the employer when
    the site says so → the walk case reddens; the contacts emitted → the
    ad case reddens; the phone scrub dropped → the ad case reddens; the
    primary location not put first → the walk case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_jobbnorge", os.path.join(SCRIPTS, "jobbnorge.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _job(self, ident, title, employer="Finnmark fylkeskommune (FFK)", dept="Kirkenes Tannklinikk", regard=False, positions=1, locs=None, promoted=False):
        locs = locs if locs is not None else [{"address": "Hessengveien 6", "area": "Hesseng", "municipality": "Sør-Varanger", "county": "Finnmark", "isDomestic": True, "isPrimary": True, "zipCode": "9912"}]
        return {"id": ident, "jobScope": "Heltid", "jobDuration": "Fast", "deadline": "16.09.2026", "employer": employer, "employerID": 2731, "regardDepartmentAsEmployer": regard,
                "department": dept, "departmentID": 20889, "title": title, "summary": "Ved klinikken har vi ledig stilling. Ring 93 46 26 68.", "logo": "x",
                "link": f"https://www.jobbnorge.no/ledige-stillinger/stilling/{ident}", "promoted": promoted, "positionCount": positions, "locations": locs, "publicationDate": "19.08.2026",
                "jobType": {"id": 378, "name": "UN1 - Undervisnings- og forskerstillinger"} if regard else {}}

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        asked = []

        def request(url):
            asked.append(url)
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(language="1", limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), asked

    def test_the_whole_list_in_one_answer_and_the_count_of_positions_as_the_witness(self):
        mod = self._mod()
        jobs = [self._job(306650, "Tannlege 100 % fast", promoted=True),
                self._job(306651, "Sykepleier", positions=3, locs=[{"municipality": "Bodø", "county": "Nordland", "isDomestic": True, "isPrimary": False, "zipCode": "8006"}, {"area": "Mørkved", "municipality": "Bodø", "county": "Nordland", "isDomestic": True, "isPrimary": True, "zipCode": "8049"}]),
                self._job(306652, "Førsteamanuensis", employer="NTNU", dept="Institutt for fysikk", regard=True),
                self._job(306650, "Tannlege 100 % fast (again)"),
                self._job(306653, "Rådgiver, Brussel", locs=[{"municipality": "Brussel", "county": "", "isDomestic": False, "isPrimary": True}])]
        rows, err, asked = self._run(mod, [(200, "6"), (200, json.dumps({"jobs": jobs}, ensure_ascii=False))])
        self.assertEqual(asked, ["https://publicapi.jobbnorge.no/v1/jobs/count", "https://publicapi.jobbnorge.no/v3/jobs?language=1"])
        self.assertEqual([r["id"] for r in rows], ["306650", "306651", "306652", "306653"])
        r = rows[0]
        self.assertEqual((r["title"], r["employer"], r["employer_parent"], r["department"], r["workplace"], r["postal_code"], r["job_scope"], r["job_duration"], r["positions"], r["promoted"], r["posted"], r["application_deadline"], r["url"]),
                         ("Tannlege 100 % fast", "Finnmark fylkeskommune (FFK)", None, "Kirkenes Tannklinikk", "Hesseng, Sør-Varanger, Finnmark", "9912", "Heltid", "Fast", 1, True, "19.08.2026", "16.09.2026", "https://www.jobbnorge.no/ledige-stillinger/stilling/306650"))
        self.assertEqual(r["summary"], "Ved klinikken har vi ledig stilling. Ring [telephone withheld].")
        self.assertEqual((rows[1]["workplace"], rows[1]["locations"], rows[1]["positions"]), ("Mørkved, Bodø, Nordland", ["Bodø, Nordland", "Bodø, Nordland"], 3))   # the primary first
        self.assertEqual((rows[2]["employer"], rows[2]["employer_parent"], rows[2]["job_type"]), ("Institutt for fysikk", "NTNU", "UN1 - Undervisnings- og forskerstillinger"))
        self.assertEqual((rows[3]["abroad"], rows[3]["workplace"]), (True, "Brussel"))
        self.assertIn("4 posting(s) emitted, 6 position(s) summed, site counts 6 positions — equal.", err)
        rows, err, asked = self._run(mod, [(200, "7"), (200, json.dumps({"jobs": jobs}, ensure_ascii=False))])
        self.assertIn("6 position(s) summed, site counts 7 positions — 1 short.", err)
        rows, err, asked = self._run(mod, [(200, "6"), (200, json.dumps({"jobs": jobs}, ensure_ascii=False))], limit=2)
        self.assertEqual(len(rows), 2)
        self.assertIn("2 posting(s) emitted of the 4 the list carries (--limit)", err)

    def test_the_ad_reads_the_pages_own_data_and_the_contacts_never_leave(self):
        import contextlib
        mod = self._mod()
        d = {"components": [{"heading": "Tannlege 100 % fast Kirkenes tannklinikk", "text": "<p>Vi søker tannlege. Spørsmål til Marit på +47 934 62 668 eller marit@ffk.example.</p>"}],
             "jobGapComponents": [{"gapType": 1, "title": "Om stillingen", "content": "<p>Ved Kirkenes tannklinikk har vi ledig fast stilling.</p>"}, {"gapType": 2, "title": "Kvalifikasjonskrav", "content": "<ul><li>Norsk autorisasjon</li></ul>"}],
             "contacts": [{"name": "Marit Charlotte Aronsen", "phone": "+4793462668", "title": "Overtannlege"}], "positionCount": 1, "isPublished": True}
        mod.request = lambda url: (200, json.dumps(d, ensure_ascii=False))
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.jobbnorge.no/ledige-stillinger/stilling/306650/tannlege-100-fast-kirkenes-tannklinikk", language="1"))
        r = json.loads(out.getvalue())
        self.assertEqual((r["id"], r["url"], r["title"], r["positions"], r["published"], r["contacts_withheld"]), ("306650", "https://www.jobbnorge.no/ledige-stillinger/stilling/306650", "Tannlege 100 % fast Kirkenes tannklinikk", 1, True, True))
        self.assertEqual([s["title"] for s in r["sections"]], ["Om stillingen", "Kvalifikasjonskrav"])
        self.assertEqual(r["sections"][1]["text"], "Norsk autorisasjon")
        self.assertEqual(r["description"], "Vi søker tannlege. Spørsmål til Marit på [telephone withheld] eller [e-mail withheld].")
        for secret in ("Aronsen", "93462668", "934 62 668", "ffk.example", "contacts\""):
            self.assertNotIn(secret, out.getvalue())
        mod.request = lambda url: (200, '{"error": "not found"}')
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.jobbnorge.no/ledige-stillinger/stilling/1", language="1"))
        self.assertEqual(cm.exception.code, 6)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://www.jobbnorge.no/search", language="1"))
        self.assertEqual(cm.exception.code, 2)


class TheStatesBoardIsTheMunicipalitiesTemplateAndAHost(unittest.TestCase):
    """**`kuntarekry.py --host valtiolle`, 2026-09-14 (#372).** Finland's
    State board is the same operator and the same template as the
    municipalities': `--host` names the board, the counter and the list
    are asked on that host, `source` and `ledger_id` carry the board's
    key, the card's addresses are built on that host, and `ad --url`
    reads the board off the address; an unknown host is refused before
    any request. Mutated (`-B`, detached copy): the host not put on the
    counter → the host case reddens; the host not put on the list → the
    host case reddens; the key not on the record → the host case reddens;
    the card's address built on the default host → the host case reddens;
    the board not read off the ad's address → the ad case reddens; the
    unknown host accepted → the bad-host case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_kuntarekry2", os.path.join(SCRIPTS, "kuntarekry.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _card(self, jid, key, title, pc="Puolustusvoimat"):
        return (f'<li role="listitem"><job-card profit-center="{pc}" title="{title}" publication-date="14.9.2026" publication-time="00:01" publication-end="5.10.2026" publication-end-time="16:15" '
                f'ext-id="{key}" url="/fi/tyopaikat/{title.lower().replace(" ", "-")}-{key}/" job-id="{jid}" job-key="{key}"></job-card></li>')

    def _page(self, cur, total, cards):
        return ('<html><body><job-list variant="grid">' + "".join(cards) + f'</job-list><ip-pagination prev="" next="/fi/tyopaikat/sivu{cur + 1}/" current="{cur}" total="{total}"></ip-pagination></body></html>')

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        sent = []

        def request(url, accept=None):
            sent.append(url)
            return next(it)
        mod.request = request
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(host="valtiolle", filter=None, pages=10, limit=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_search(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), sent

    def test_the_host_names_the_board_on_the_counter_the_list_and_the_record(self):
        mod = self._mod()
        p1 = self._page(1, 1, [self._card(303417, "24521", "Opetusaliupseeri"), self._card(303418, "24522", "Ulosottoylitarkastaja", pc="Ulosottolaitos")])
        rows, err, sent = self._run(mod, [(200, '{"count": 2}'), (200, p1)])
        self.assertEqual(sent, ["https://valtiolle.fi/fi/tyopaikat/?view=count&format=json", "https://valtiolle.fi/fi/tyopaikat/"])
        self.assertEqual([(r["source"], r["ledger_id"], r["url"], r["employer"]) for r in rows],
                         [("valtiolle", "valtiolle:303417", "https://valtiolle.fi/fi/tyopaikat/opetusaliupseeri-24521/", "Puolustusvoimat"),
                          ("valtiolle", "valtiolle:303418", "https://valtiolle.fi/fi/tyopaikat/ulosottoylitarkastaja-24522/", "Ulosottolaitos")])
        self.assertIn("2 emitted over 1 page(s), site counts 2 (valtiolle.fi) — equal.", err)
        rows, err, sent = self._run(mod, [(200, '{"count": 1}'), (200, self._page(1, 1, [self._card(1, "9", "Lakimies")]))], host=None)
        self.assertEqual(sent[0], "https://kuntarekry.fi/fi/tyopaikat/?view=count&format=json")
        self.assertEqual(rows[0]["source"], "kuntarekry")

    def test_the_ad_reads_the_board_off_the_address_and_an_unknown_host_is_refused(self):
        import contextlib
        mod = self._mod()
        ld = {"@context": "http://schema.org", "@type": "JobPosting", "title": "Opetusaliupseeri", "hiringOrganization": "Puolustusvoimat", "jobLocation": {"@type": "Place", "address": {"@type": "PostalAddress", "addressRegion": "Uusimaa", "addressLocality": "Kirkkonummi"}},
              "datePosted": "2026-09-14T00:00:00+03:00", "validThrough": "2026-10-05T16:15:00+03:00", "baseSalary": {"@type": "MonetaryAmount", "currency": "EUR", "value": "2 699,38 €/kk. Tiedustelut 0299 326200."}, "description": "Haemme opetusaliupseeria.", "employmentType": "Määräaikainen"}
        mod.request = lambda url, accept=None: (200, '<html><head><script type="application/ld+json">' + json.dumps(ld, ensure_ascii=False) + '</script></head><body><job-view job-ext-id="24521" job-title="Opetusaliupseeri"></job-view></body></html>')
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url="https://valtiolle.fi/fi/tyopaikat/opetusaliupseeri-joukkueen-varajohtaja-24521/"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["source"], d["ledger_id"], d["key"], d["employer"], d["salary_currency"]), ("valtiolle", "valtiolle:key:24521", "24521", "Puolustusvoimat", "EUR"))
        self.assertEqual(d["salary_text"], "2 699,38 €/kk. Tiedustelut [telephone withheld].")
        self.assertNotIn("0299 326200", out.getvalue())
        asked = []
        mod.request = lambda url, accept=None: asked.append(url) or (200, "")
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_search(argparse.Namespace(host="kela", filter=None, pages=1, limit=None))
        self.assertEqual(cm.exception.code, 2)
        self.assertEqual(asked, [])
        self.assertIn("kuntarekry, valtiolle", e2.getvalue())


class TheWholeRegisterIsOneOpenDataFileAndThePortalsOwnSearchIsNeverSent(unittest.TestCase):
    """**`uradprace.py`, 2026-09-14 (#350).** The Czech public employment
    service's own search is a web component that POSTs `*/rest/*` — refused in
    writing by `up.gov.cz/robots.txt` — and the Ministry publishes the same
    register as an open-data file on `data.mpsv.cz`: one file is the whole
    register, its postings and positions printed, its `Last-Modified` the
    witness, and a body shorter than `Content-Length` is a short file (exit
    6), never a smaller register. The places are codes resolved through the
    published lists (municipality → district → region); an employer who asked
    to be anonymous (`anosp`) is null with a reason, place withheld; the
    contact person every record carries never leaves, and every free text —
    the profession too, one was an e-mail address on the day — is scrubbed.
    Filters are resolved against the lists and an unknown name is an error,
    never an empty market. Mutated (`-B`, detached copy): the description not
    scrubbed → the register case reddens; the anonymous flag not honoured →
    the register case reddens; the district not derived from the
    municipality → the register case reddens; the hourly unit mapped to month
    → the register case reddens; the short-body check relaxed → the short
    case reddens; `--changed-since` made exclusive → the filter case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_uradprace", os.path.join(SCRIPTS, "uradprace.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    LISTS = {
        "kraje": {"polozky": [{"id": "Kraj/19", "nazev": {"cs": "Hlavní město Praha"}}, {"id": "Kraj/116", "nazev": {"cs": "Jihomoravský kraj"}}, {"id": "Kraj/27", "nazev": {"cs": "Středočeský kraj"}}, {"id": "Kraj/35", "nazev": {"cs": "Jihočeský kraj"}}]},
        "okresy": {"polozky": [{"id": "Okres/9999", "nazev": {"cs": "území Hlavního města Prahy"}, "kraj": "Kraj/19"}, {"id": "Okres/3702", "nazev": {"cs": "Brno-město"}, "kraj": "Kraj/116"},
                               {"id": "Okres/3204", "nazev": {"cs": "Kolín"}, "kraj": "Kraj/27"}, {"id": "Okres/3301", "nazev": {"cs": "České Budějovice"}, "kraj": "Kraj/35"}]},
        "obce": {"polozky": [{"id": "Obec/554782", "nazev": {"cs": "Praha"}, "okres": "Okres/9999"}, {"id": "Obec/582786", "nazev": {"cs": "Brno"}, "okres": "Okres/3702"}, {"id": "Obec/533831", "nazev": {"cs": "Kolín"}, "okres": "Okres/3204"}]},
        "cz-isco": {"polozky": [{"id": "CzIsco/93340", "nazev": {"cs": "Doplňovači zboží"}}, {"id": "CzIsco/51201", "nazev": {"cs": "Kuchaři (kromě šéfkuchařů)"}}]},
    }

    def _item(self, pid, title, isco, publish="ano", employer=("JS HOSPITALITY s.r.o.", "06070591"), positions=1, salary=(22500, 25000), unit="mesic", place=None, changed="2026-09-13T23:12:44.473Z", desc=None, langs=None):
        contact = {"komuSeHlasit": {"email": "hr1@janhotels.example", "telefon": "266133004", "jmeno": "Zdislava", "prijmeni": "Hrušková-Secret", "titulPredJmenem": None, "titulZaJmenem": None, "poziceVeSpolecnosti": None},
                   "kdeSeHlasit": {"email": None, "telefon": "+420 777 888 999", "mistoKontaktu": "Bohemia Properties a.s.", "adresa": None}}
        return {"portalId": pid, "id": f"VolneMisto/{pid}", "referencniCislo": f"R{pid}", "azylant": False, "cizinecMimoEu": True, "datumVlozeni": "2026-09-08T00:00:00.000Z", "datumZmeny": changed,
                "mesicniMzdaDo": salary[1], "mesicniMzdaOd": salary[0], "modraKarta": False, "pocetHodinTydne": 40, "pocetMist": positions, "pozadovanaProfese": {"cs": title},
                "statniSpravaSamosprava": False, "terminUkonceniPracovnihoPomeru": None, "terminZahajeniPracovnihoPomeru": "2026-10-01", "souhlasAgenturyAgentura": False, "souhlasAgenturyUzivatel": False,
                "upresnujiciInformace": {"cs": desc} if desc else None, "urlAdresa": None, "zamestnaneckaKarta": True, "expirace": None, "minPozadovaneVzdelani": {"id": "VzdelaniDetailniKategorie/bezVzdel"},
                "smennost": {"id": "Smennost/pruznaPd"}, "typMzdy": {"id": f"TypMzdy/{unit}"} if unit else None, "zverejnovat": {"id": f"ZverejnovatVpm/{publish}"}, "mistoVykonuPrace": place,
                "zamestnavatel": {"ico": employer[1], "nazev": employer[0]} if employer else None, "profeseCzIsco": {"id": f"CzIsco/{isco}"}, "pracovnePravniVztahy": [{"id": "PracovnepravniVztah/plny"}],
                "vhodnostiPracovnihoMista": [{"id": "VhodnostProTypZamestnance/zdravi"}], "kontaktniPracoviste": {"id": "KontaktniPracoviste/ABA"}, "vyhodyVolnehoMista": None, "pozadovanaDovednost": None,
                "pozadovanaJazykovaZnalost": langs, "pozadovanePovolani": None, "pozadovaneVzdelani": None, "prvniKontaktSeZamestnavatelem": contact}

    def _register(self):
        adr = lambda obec, kraj, okres, psc: {"cisloDomovni": 590, "cisloOrientacni": "14", "psc": psc, "kraj": {"id": kraj} if kraj else None, "okres": {"id": okres} if okres else None, "obec": {"id": obec}, "ulice": {"nazev": "Cuřínova"}}
        return [
            self._item(1, "Doplňovači zboží", "93340", positions=2, desc="Volejte 777 123 456 nebo pište na sef@firma.example, znalost vietnamštiny výhodou",
                       place={"typMistaVykonuPrace": {"id": "TypMistaVykonuPrace/adrprov"}, "obec": None, "okresy": None, "adresaText": None,
                              "pracoviste": [{"email": "provoz@firma.example", "nazev": "Cuřínova sídlo", "telefon": "222333444", "adresa": adr("Obec/554782", "Kraj/19", "Okres/9999", "14200")}]},
                       langs=[{"urovenZnalosti": {"id": "UrovenZnalostiJazyka/pas"}, "jazyk": {"id": "Jazyk/jiny"}, "popis": "Hindština — ptejte se na hr@firma.example"}]),
            self._item(2, "Pomocní kuchaři", "51201", publish="anosp", employer=("Skrytý podnik s.r.o.", "11111111"), positions=3,
                       place={"typMistaVykonuPrace": {"id": "TypMistaVykonuPrace/obec"}, "obec": {"id": "Obec/554782"}, "okresy": None, "adresaText": None, "pracoviste": None}),
            self._item(3, "office.ak.sedivy@email.example", "51201", salary=(150, None), unit="hod", changed="2026-09-01T10:00:00.000Z",
                       place={"typMistaVykonuPrace": {"id": "TypMistaVykonuPrace/obec"}, "obec": {"id": "Obec/582786"}, "okresy": None, "adresaText": None, "pracoviste": None}),
            self._item(4, "Kuchaři (kromě šéfkuchařů)", "51201", salary=(None, None), unit=None, changed="2026-08-20T10:00:00.000Z",
                       place={"typMistaVykonuPrace": {"id": "TypMistaVykonuPrace/okres"}, "obec": None, "okresy": [{"id": "Okres/3301"}, {"id": "Okres/3204"}], "adresaText": None, "pracoviste": None}),
            self._item(5, "Doplňovači zboží", "93340", positions=4, changed="2026-08-31T23:59:59.000Z",
                       place={"typMistaVykonuPrace": {"id": "TypMistaVykonuPrace/adrprov"}, "obec": None, "okresy": None, "adresaText": None,
                              "pracoviste": [{"email": None, "nazev": "C & F Manufacturing s.r.o.", "telefon": None, "adresa": adr("Obec/533831", None, None, "28101")}]}),
            self._item(6, "Kuchaři (kromě šéfkuchařů)", "51201", place={"typMistaVykonuPrace": {"id": "TypMistaVykonuPrace/celaCR"}, "obec": None, "okresy": None, "adresaText": None, "pracoviste": None}),
        ]

    def _run(self, mod, register=None, **kw):
        import contextlib
        register = self._register() if register is None else register
        asked = []

        def request(url):
            asked.append(url)
            name = url.rsplit("/", 1)[1][:-5]
            if name in self.LISTS:
                return 200, json.dumps(self.LISTS[name], ensure_ascii=False), {}
            return 200, json.dumps({"polozky": register}, ensure_ascii=False), {"Last-Modified": "Sun, 13 Sep 2026 20:07:40 GMT"}
        mod.request = request
        ns = argparse.Namespace(kraj=None, okres=None, obec=None, isco=None, profese=None, changed_since=None, limit=None, cache=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_list(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), asked, out.getvalue()

    def test_the_register_is_one_file_its_places_are_the_lists_and_the_contacts_never_leave(self):
        mod = self._mod()
        rows, err, asked, raw = self._run(mod)
        self.assertEqual(asked, [mod.CODELISTS[k] for k in ("kraje", "okresy", "obce", "cz-isco")] + [mod.DUMP])
        self.assertEqual([r["id"] for r in rows], ["1", "2", "3", "4", "5", "6"])
        a = rows[0]
        self.assertEqual((a["title"], a["isco"], a["employer"], a["employer_ico"], a["positions"], a["salary_min"], a["salary_max"], a["salary_currency"], a["salary_unit"], a["salary_unit_stated"], a["url"], a["contacts_withheld"]),
                         ("Doplňovači zboží", "Doplňovači zboží", "JS HOSPITALITY s.r.o.", "06070591", 2, 22500, 25000, "CZK", "month", True, "https://up.gov.cz/volna-mista-v-cr#/volna-mista-detail/1", True))
        self.assertEqual((a["place_type"], a["workplace_name"], a["street"], a["postal_code"], a["municipality"], a["districts"], a["region"], a["region_code"]),
                         ("adrprov", "Cuřínova sídlo", "Cuřínova 590/14", "14200", "Praha", ["území Hlavního města Prahy"], "Hlavní město Praha", "19"))
        self.assertEqual(a["description"], "Volejte [telephone withheld] nebo pište na [e-mail withheld], znalost vietnamštiny výhodou")
        self.assertEqual(a["languages"], [{"language": "jiny", "level": "pas", "note": "Hindština — ptejte se na [e-mail withheld]"}])
        b = rows[1]   # anonymous at the employer's request: no name, no IČO, no place — even when the file carried them
        self.assertEqual((b["employer"], b["employer_ico"], b["publication"], b["place_type"], b["municipality"], b["region"]), (None, None, "anosp", None, None, None))
        self.assertIn("ZverejnovatVpm/anosp", b["employer_withheld"])
        c = rows[2]   # a municipality-typed place: district and region derived through the lists; an hourly wage; a profession that was an address
        self.assertEqual((c["title"], c["municipality"], c["districts"], c["region"], c["salary_min"], c["salary_max"], c["salary_unit"], c["salary_unit_stated"]), ("[e-mail withheld]", "Brno", ["Brno-město"], "Jihomoravský kraj", 150, None, "hour", True))
        d = rows[3]   # districts: both named, the region from the first; no wage at all
        self.assertEqual((d["districts"], d["region"], d["municipality"], d["salary_min"], d["salary_currency"], d["salary_unit"], d["salary_unit_stated"]), (["České Budějovice", "Kolín"], "Jihočeský kraj", None, None, None, None, False))
        e = rows[4]   # an establishment whose address names the municipality only: district and region derived
        self.assertEqual((e["workplace_name"], e["postal_code"], e["municipality"], e["districts"], e["region"]), ("C & F Manufacturing s.r.o.", "28101", "Kolín", ["Kolín"], "Středočeský kraj"))
        self.assertEqual((rows[5]["place_type"], rows[5]["address_text"], rows[5]["region"]), ("celaCR", "celá ČR", None))
        for secret in ("Hrušková", "Zdislava", "janhotels", "266133004", "777 888 999", "komuSeHlasit", "kdeSeHlasit", "provoz@", "222333444", "777 123 456", "sef@firma", "hr@firma", "sedivy", "Skrytý", "11111111", '"telefon"', '"email"'):
            self.assertNotIn(secret, raw)
        self.assertIn("6 posting(s) in the file (Last-Modified: Sun, 13 Sep 2026 20:07:40 GMT), 12 position(s) summed — one file is the whole register, nothing paged.", err)
        self.assertIn("6 emitted, 12 position(s).", err)
        self.assertIn("there is no `ad` command", err)

    def test_filters_are_resolved_against_the_lists_and_an_unknown_name_is_an_error_not_an_empty_market(self):
        import contextlib
        mod = self._mod()
        rows, err, _, _ = self._run(mod, kraj="jihomoravsky")
        self.assertEqual(([r["id"] for r in rows], "1 of them match --kraj Jihomoravský kraj." in err), (["3"], True))
        rows, err, _, _ = self._run(mod, kraj="19")
        self.assertEqual([r["id"] for r in rows], ["1"])
        rows, err, _, _ = self._run(mod, okres="kolin")
        self.assertEqual([r["id"] for r in rows], ["4", "5"])
        rows, err, _, _ = self._run(mod, obec="Praha")
        self.assertEqual([r["id"] for r in rows], ["1"])   # the anonymous record's Praha is withheld with the rest
        rows, err, _, _ = self._run(mod, isco="512", profese="kuchar")
        self.assertEqual([r["id"] for r in rows], ["2", "4", "6"])
        rows, err, _, _ = self._run(mod, changed_since="2026-09-01")
        self.assertEqual([r["id"] for r in rows], ["1", "2", "3", "6"])   # the day itself is in; 23:59:59 the day before is out
        rows, err, _, _ = self._run(mod, limit=2)
        self.assertEqual(([r["id"] for r in rows], "2 emitted of the 6 — bounded by --limit, not a shortfall." in err), (["1", "2"], True))
        out = io.StringIO()
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            self._run(mod, kraj="nowhere")
        self.assertEqual((cm.exception.code, out.getvalue()), (2, ""))
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            self._run(mod, kraj="kraj")   # four entries carry the word: ambiguous, not the first one
        self.assertEqual(cm.exception.code, 2)

    def test_a_short_body_is_a_short_file_not_a_smaller_register(self):
        import contextlib
        from unittest import mock
        mod = self._mod()
        mod.robots_allowed = lambda host, path, agents=None: {"allowed": True, "reason": "stub"}
        mod._PACE.wait = lambda: None

        class Resp:
            def __init__(self, body, length):
                self._b, self.headers = body, {"Content-Length": str(length), "Content-Type": "application/json"}
            def read(self):
                return self._b
            def getcode(self):
                return 200
            def __enter__(self):
                return self
            def __exit__(self, *a):
                return False
        body = b'{"polozky": [1, 2, 3]}'
        with mock.patch.object(mod.urllib.request, "urlopen", lambda req, timeout=0: Resp(body[:10], len(body))):
            with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
                mod.request(mod.DUMP)
        self.assertEqual(cm.exception.code, 6)
        with mock.patch.object(mod.urllib.request, "urlopen", lambda req, timeout=0: Resp(body, len(body))):
            code, text, headers = mod.request(mod.DUMP)
        self.assertEqual((code, json.loads(text)), (200, {"polozky": [1, 2, 3]}))


class ASecondBoardOnTheSameTemplateIsAHostAndARecruitersAddressIsNotAField(unittest.TestCase):
    """**`nationalevacaturebank.py --host intermediair`, 2026-09-14 (#295).**
    DPG Media's second board is the same template to the line: `--host`
    names the board, the index is asked on that host, `source` and
    `ledger_id` carry the board's key, a file that named the other board's
    host yields no row, and `ad --url` reads the board off the address.
    And a correction to #287: `hiringOrganization.email` on this template
    is a recruiter's own address — it is no longer a field, and the
    description is scrubbed. Mutated (`-B`, detached copy): the host not
    put on the index → the host case reddens; the key not on the record →
    the host case reddens; the other board's rows accepted → the cross
    case reddens; the e-mail field restored → the contact case reddens;
    the description not scrubbed → the contact case reddens; the unknown
    host accepted → the bad-host case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_nvb2", os.path.join(SCRIPTS, "nationalevacaturebank.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    U1, U2 = "001dcbef-12f4-41a6-afaf-dc24184f8404", "006cffb8-1e44-4f9e-9a05-c9ae95daaea9"
    INDEX = "<sitemapindex><sitemap><loc>https://intermediair.nl/cdn/sitemaps/vacature/vacature-1.xml</loc><lastmod>2026-09-14T00:21:16Z</lastmod></sitemap></sitemapindex>"

    def _file(self, *triples):
        return "<urlset>" + "".join(f"<url><loc>https://www.{host}.nl/vacature/{u}/{slug}</loc></url>" for host, u, slug in triples) + "</urlset>"

    def _run(self, mod, served, **kw):
        import contextlib
        it = iter(served)
        asked = []

        def get(url):
            asked.append(url)
            return next(it)
        mod.get = get
        out, err = io.StringIO(), io.StringIO()
        ns = argparse.Namespace(host="intermediair", limit=None, sample=None)
        for k, v in kw.items():
            setattr(ns, k, v)
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            mod.cmd_sitemap(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), asked

    def test_the_host_names_the_board_and_the_other_boards_rows_are_not_this_boards(self):
        mod = self._mod()
        f1 = self._file(("intermediair", self.U1, "change-manager"), ("nationalevacaturebank", self.U2, "forklift"), ("intermediair", self.U2, "consultant"))
        rows, err, asked = self._run(mod, [(200, self.INDEX), (200, f1)])
        self.assertEqual(asked[0], "https://www.intermediair.nl/cdn/sitemaps/vacature.xml")
        self.assertEqual([(r["source"], r["ledger_id"], r["id"], r["url"]) for r in rows],
                         [("intermediair", f"intermediair:{self.U1}", self.U1, f"https://www.intermediair.nl/vacature/{self.U1}/change-manager"),
                          ("intermediair", f"intermediair:{self.U2}", self.U2, f"https://www.intermediair.nl/vacature/{self.U2}/consultant")])
        self.assertIn("**2 distinct advertisement uuid(s)** on www.intermediair.nl in 1 file(s) (vacature-1.xml 2)", err)
        # the default is still Nationale Vacaturebank
        rows, err, asked = self._run(mod, [(200, self.INDEX.replace("intermediair", "nationalevacaturebank")), (200, self._file(("nationalevacaturebank", self.U1, "x")))], host=None)
        self.assertEqual(asked[0], "https://www.nationalevacaturebank.nl/cdn/sitemaps/vacature.xml")
        self.assertEqual(rows[0]["source"], "nationalevacaturebank")

    def test_an_unknown_host_is_refused_before_any_request(self):
        import contextlib
        mod = self._mod()
        asked = []
        mod.get = lambda url: asked.append(url) or (200, "")
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()) as e2:
            mod.cmd_sitemap(argparse.Namespace(host="monsterboard", limit=None, sample=None))
        self.assertEqual(cm.exception.code, 2)
        self.assertEqual(asked, [])
        self.assertIn("nationalevacaturebank, intermediair", e2.getvalue())

    def test_the_ad_reads_the_board_off_the_address_and_the_recruiters_address_never_leaves(self):
        import contextlib
        mod = self._mod()
        ld = json.dumps({"@context": "https://schema.org/", "@type": "JobPosting", "title": "Change manager", "datePosted": "2026-08-31T22:00:00Z", "validThrough": "2026-10-31T22:59:59Z",
                         "description": "<p>Reageer via anjo.k@teameiffel.example of bel ons.</p>", "employmentType": ["FULL_TIME", "PART_TIME"],
                         "hiringOrganization": {"@type": "Organization", "name": "Team EIFFEL", "email": "anjo.k@teameiffel.example"},
                         "jobLocation": {"@type": "Place", "address": {"@type": "PostalAddress", "addressLocality": "Utrecht", "addressRegion": "Utrecht", "addressCountry": "NL", "postalCode": "3528BJ"}}})
        mod.get = lambda url: (200, f'<html><head><script type="application/ld+json" data-next-head="">{ld}</script></head><body>{"x" * 3000}</body></html>')
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            mod.cmd_ad(argparse.Namespace(url=f"https://www.intermediair.nl/vacature/{self.U1}/change-manager-energietransitie"))
        d = json.loads(out.getvalue())
        self.assertEqual((d["source"], d["ledger_id"], d["id"], d["title"], d["employer"], d["city"], d["contacts_withheld"]),
                         ("intermediair", f"intermediair:{self.U1}", self.U1, "Change manager", "Team EIFFEL", "Utrecht", True))
        self.assertNotIn("employer_email", d)
        self.assertNotIn("teameiffel.example", out.getvalue())
        self.assertIn("[e-mail withheld]", d["description"])


class OneGeneralistOnFiveFrontsWhoseListIsAnArchiveWalkedByDateAndWhoseAdvertHoldsSeveralPositions(unittest.TestCase):
    """**`myjobmag.py`, 2026-09-14 (#391).** MyJobMag is one template on
    five hosts, named by `--host`; every front refuses a query string in
    writing, so the pager is the path `/jobs/page/N` and a `?` is never
    sent. The list states no count and is an archive going back years, so
    the walk is newest-first and stops at the first card older than
    `--days`, saying so; a 200 page without one card is a changed
    template (exit 6). A card is a position or an advert of several, and
    `ad` emits one record per position block, its labelled fields, the
    salary with the period the site prints, the JSON-LD parsed despite its
    raw newlines; the «Method of Application» text — where an employer
    writes the address to send a CV to — is scrubbed. Mutated (`-B`,
    detached copy): the query-string guard dropped → the guard case
    reddens; the date stop made inclusive → the walk case reddens; the
    employer not read off the title → the walk case reddens; the advert
    kind not told apart → the walk case reddens; the application text not
    scrubbed → the ad case reddens; the salary period dropped → the ad
    case reddens."""

    def _mod(self):
        spec = importlib.util.spec_from_file_location("_myjobmag", os.path.join(SCRIPTS, "myjobmag.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _card(self, path, title, date, employer=None, slug=None):
        logo = (f'<a  href="/jobs-at/{slug}"  ><img src="/company_logo/x.png" alt="{employer}" width="100%" /></a>' if slug
                else f'<a  ><img src="/company_logo/86/default-company-logo.png" alt="{title}" width="100%" title=" logo" /></a>')
        return (f'<li class="job-list-li"><ul><li class="job-logo">{logo}</li><li class="job-info"><ul><li class="mag-b"><h2><a style=" " href="{path}">{title}</a></h2></li>'
                f'<li class="job-desc">We recruit. Write to hr@firm.example or 0803 123 4567 ...</li><li class="job-item"><ul><li id="job-date">{date}</li></ul></li></ul></li></ul></li>')

    def _page(self, cards, cur, last):
        pager = "".join(f"<li><a href='/jobs/page/{i}'>{i}</a></li>" if i != cur else f"<li><a class='current_page'>{i}</a></li>" for i in range(1, last + 1)).replace("href='/jobs/page/1'", "href='/jobs'")
        return f'<html><body><h1 class="main-h2-2">Jobs in Nigeria</h1><ul class="job-list">{"".join(cards)}</ul><div class="mag-b bm-b-20"><ul class=\'setPaginate\'>{pager}</ul></div></body></html>'

    def _run(self, mod, served, cmd="list", **kw):
        import contextlib
        asked = []
        it = iter(served)

        def request(url):
            asked.append(url)
            return next(it)
        mod.request = request
        ns = argparse.Namespace(host=None, days=None, pages=None, limit=None) if cmd == "list" else argparse.Namespace()
        for k, v in kw.items():
            setattr(ns, k, v)
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            (mod.cmd_list if cmd == "list" else mod.cmd_ad)(ns)
        return [json.loads(l) for l in out.getvalue().splitlines() if l.startswith("{")], err.getvalue(), asked, out.getvalue()

    def test_the_list_is_walked_by_date_on_the_named_front_and_never_with_a_query(self):
        import contextlib
        mod = self._mod()
        today = datetime.date.today()
        d = lambda n: (today - datetime.timedelta(days=n)).strftime("%d %B")   # the site prints «12 September» for this year
        floor = today - datetime.timedelta(days=30)
        p1 = self._page([self._card("/job/event-rental-sales-representative-luxelayer-rentals", "Event Rental Sales Representative at Luxelayer Rentals", d(2), "Luxelayer Rentals", "luxelayer-rentals"),
                         self._card("/jobs/medical-consultants-at-bergstein-hospital-1", "Medical Consultants at Bergstein Hospital", d(2), "Bergstein Hospital", "bergstein-hospital"),
                         self._card("/job/farm-poultry-attendant", "Farm Poultry Attendant at Regal Bablo Farms", d(3)),
                         self._card("/job/event-rental-sales-representative-luxelayer-rentals", "Event Rental Sales Representative at Luxelayer Rentals", d(2), "Luxelayer Rentals", "luxelayer-rentals")], 1, 3)
        p2 = self._page([self._card("/job/on-the-floor-day", "On the Floor Day at Edge Ltd", floor.strftime("%d %B") if floor.year == today.year else floor.strftime("%d %B, %Y"), "Edge Ltd", "edge-ltd"),
                         self._card("/job/old-one", "Old One at Past Ltd", "10 June, 2024", "Past Ltd", "past-ltd"),
                         self._card("/job/older-one", "Older One at Past Ltd", "06 May, 2024", "Past Ltd", "past-ltd")], 2, 3)
        p3 = self._page([self._card("/job/oldest", "Oldest at Past Ltd", "01 May, 2024", "Past Ltd", "past-ltd")], 3, 3)
        rows, err, asked, raw = self._run(mod, [(200, p1), (200, p2), (200, p3)])
        self.assertEqual(asked, ["https://www.myjobmag.com/jobs", "https://www.myjobmag.com/jobs/page/2"])
        self.assertEqual([r["id"] for r in rows], ["event-rental-sales-representative-luxelayer-rentals", "medical-consultants-at-bergstein-hospital-1", "farm-poultry-attendant", "on-the-floor-day"])
        a, b, c, e = rows
        self.assertEqual((a["source"], a["country"], a["kind"], a["url"], a["employer"], a["employer_slug"], a["posted"], a["contacts_withheld"]),
                         ("myjobmag-ng", "NG", "position", "https://www.myjobmag.com/job/event-rental-sales-representative-luxelayer-rentals", "Luxelayer Rentals", "luxelayer-rentals", (today - datetime.timedelta(days=2)).isoformat(), True))
        self.assertEqual((b["kind"], b["url"], b["ledger_id"]), ("advert", "https://www.myjobmag.com/jobs/medical-consultants-at-bergstein-hospital-1", "myjobmag-ng:advert:medical-consultants-at-bergstein-hospital-1"))
        self.assertEqual((c["employer"], c["employer_slug"]), ("Regal Bablo Farms", None))   # no /jobs-at/ page: the employer is the title's tail
        self.assertEqual(e["posted"], floor.isoformat())   # the day of the floor itself is still in
        self.assertEqual(a["summary"], "We recruit. Write to [e-mail withheld] or [telephone withheld] ...")
        self.assertNotIn("hr@firm", raw)
        self.assertIn("4 card(s) emitted over 2 page(s) on www.myjobmag.com (NG), newest-first, stopped at the first card dated 2024-06-10 — older than --days 30; the site states no count and its list is an archive: walked by date, not a shortfall.", err)
        self.assertIn("1 of them are adverts", err)
        rows, err, asked, raw = self._run(mod, [(200, p1), (200, p2), (200, p3)], days=9999)
        self.assertEqual((len(asked), len(rows)), (3, 7))
        self.assertIn("7 card(s) emitted over 3 page(s) on www.myjobmag.com (NG) — the pager ended; the site states no count.", err)
        rows, err, asked, raw = self._run(mod, [(200, p1.replace("Jobs in Nigeria", "Jobs in Kenya"))], host="ke", pages=1)
        self.assertEqual((asked, rows[0]["source"], rows[0]["country"], rows[0]["url"][:26]), (["https://www.myjobmag.co.ke/jobs"], "myjobmag-ke", "KE", "https://www.myjobmag.co.ke"))
        self.assertIn("bounded by --pages/--limit", err)
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            self._run(mod, [(200, "<html><body><h1>Jobs in Nigeria</h1><ul class=\"job-list\"></ul></body></html>")])
        self.assertEqual(cm.exception.code, 6)   # 200 and not one card: the template changed, not an empty market
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            self._run(mod, [], host="www.myjobmag.example")
        self.assertEqual(cm.exception.code, 2)
        # the guard on the wire: a query string is refused in writing on every front, and the adapter refuses it before the gate
        mod = self._mod()   # a fresh module — `_run` replaced `request`
        mod.gate = lambda url: {"allowed": True}
        mod.pace_for = lambda host: type("P", (), {"wait": staticmethod(lambda: None)})()
        with self.assertRaises(SystemExit) as cm, contextlib.redirect_stderr(io.StringIO()):
            mod.request("https://www.myjobmag.com/jobs?page=2")
        self.assertEqual(cm.exception.code, 7)

    def test_the_ad_emits_one_record_per_position_and_the_application_text_is_scrubbed(self):
        import contextlib
        mod = self._mod()
